// WILD 荒野 —— 单局 10 分钟生存割草（吸血鬼幸存者-like）
//
// 独立项目。实时层从 ONE-CARD 的荒野关（阶段 6.2 口径）整体搬过来改造，
// 已切断**全部**卡牌耦合：
//   ✗ 不再 import config/cards.js / src/cards.js（不读牌池、不 roll 奖励牌）
//   ✗ 不再有 run 实例（不回主地图、不共用主游戏的 HP）
//   ✗ 不再有荒野牌映射（击杀/宝石/释放次数不再喂给任何卡牌评分）
//   ✓ HP 是荒野自己的血（this.hp/this.maxHp）
//   ✓ 结算只报「存活时间 + 总击杀数」
//
// 分层（这条分层是"能测"的前提，不是洁癖）：
//   ArenaCore —— 纯逻辑，零 DOM / 零 canvas。Node 里可以直接 new 出来喂 step(dt)，
//                所以「10 分钟不 NaN」「升级触发」「死亡结算」「波次单调递进」
//                全部能在无头环境里断言，而不是靠肉眼看。
//   Arena     —— DOM 包装：canvas 渲染 + 双端输入 + rAF 循环 + 三选一弹窗。
//
// 美术口径：零位图。敌人形象由 glyph.silhouette(shape) 程序生成后**烘焙成离屏精灵**，
// 每帧只 drawImage —— 同屏 90 只时，路径光栅化（save/translate/scale/fill）是唯一会把
// 帧率打下来的开销，而剪影形状是静态的，没有任何理由每帧重算一遍。

import { silhouette, silhouetteBox, SILHOUETTE_ANCHOR } from './glyph.js';
import { Sfx } from './sfx.js';
// 内容池（武器/技能/被动的**表**）住在 content.js；本文件是执行层。
// ⚠ 二者循环引用，所以两边都**只在函数体内**访问对方 ——
//   顶层的 import 不会读值，只有真正调用时才解引用，两种加载顺序都安全。
//   若在顶层写 `const X = OFFERS.length` 或 `export const A = {...ARENA...}` 就会炸 TDZ。
import {
  OFFERS, PASSIVES, WEAPONS, SKILLS, SKILL_ORDER, SKILL_SHORT, SKILL_LABEL, SKILL_SLOT_KEYS,
  CAT_LABEL, RARE_PASSIVES, offerById, growthLineOf,
  // 阶段 4-5：超武进化表 + 角色表
  EVOLUTIONS, HEROES, heroById, DEFAULT_HERO, WEAPON_OF_UP, classPassiveOf, classPerkOf,
  // 阶段 7：每 3 级的"技能向保底"节拍器 + 技能向判据
  SKILL_TIER_CADENCE, isSkillFlavored,
} from './content.js';
import { Rng } from './rng.js';   // 阶段 4-7.x：心心掉落的**独立**随机源（不碰主 rng 流，见 killEnemy 注释）
import { SKIN_TINT_ALPHA, DEFAULT_SKIN, SKINS, skinById, skinNeedsTint } from './skins.js';  // 阶段 6-2：纯外观皮肤
import { loadoutBuffs } from './loadout.js';  // 阶段 6-3：局外配装（纯数值，applyGrowth 之后叠加）
import { SHOP_TIMES, rollShop, applyShopGood } from './shop.js';  // 阶段 6-4：局内商店「魂火商栈」（纯逻辑，不碰 DOM）

// ───────── 数值口径（写死，可被 tools/arena-sim.mjs 与 tests/ 直接断言） ─────────
// 工具与测试读同一份常量，才不会出现「测试里是 A 数值、模拟器里是 B 数值」的隐形口径漂移。
export const ARENA = {
  DURATION_MS: 600_000,     // 一局 10 分钟（spec §1：从 75 秒小关扩成完整一局）

  // ── 玩家 ──
  BASE_MOVE: 150,           // 移动速度 px/s
  // ★★ 阶段 4-9 配套标定（**这一组是必要的，不是顺手加的**）：
  //   把主动技能降格（伤害降到 1/4、CD 拉到 8s）实测拿走了 **69.3%** 的输出 ——
  //   16 局官方 sim：跑满 13/16 → **0/16**、平均存活 600s → 328s、Boss 站场 5~40s → 82s。
  //   而 spec §四-2 的原话是「武器（投射物/环绕刃/激光）必须贡献 >80% 的击杀 ——
  //   它们才是输出主力」⟹ 技能让出的那份输出**必须由武器补上**，否则这份 spec 自相矛盾
  //   （要么武器当主力，要么活不过 10 分钟，二者只能选一个）。
  //   补多少不是拍脑袋：目标是让**总击杀回到 4-8 的水平**（≈5300/局），因为 4-8 的
  //   所有验收读数（可视区内同屏 ≥15、跑满 13/16）都是在那个总量下标定出来的。
  //   ★ 实测（每档 8 局官方 runOne，对照组见 .tmp49/sweep-lever.mjs）：
  //       现状（不补）      跑满 1/8 · 均存活 360s · 最低血 0.4 · 击杀 1883/局
  //       只降接触伤害      跑满 1/8 · 355s · 3.1 · 1856      ← 无效（不是"挨打太疼"，是"清不掉"）
  //       只降怪血成长      跑满 3/8 · 460s · 5.7 · 2692
  //       只降刷怪密度      跑满 2/8 · 413s · 3.0 · 1921      ← 密度是 4-8 好不容易堆上去的，不动
  //       武器伤害 ×3       跑满 2/8 · 451s · 9.0 · 3434      ← **伤害单独加会饱和**（一发就打死的怪，加伤不加吞吐）
  //       武器吞吐 ×1.6     跑满 4/8 · 489s · 7.0 · 3715
  //       ★ 伤害×2 + 吞吐×1.45  跑满 **6/8** · **564s** · **26.9** · **5376**  ← 采用这一档
  //     ⟹ 结论：这条线上"伤害"和"吞吐"必须**联合**加（与 4-1.1 的血量成长↔刷怪密度是同一类耦合）。
  //       "清不掉贴脸那一圈"是主因，而清圈的瓶颈是**每秒能打几发**，不是每发多重。
  //   ⚠ 这一组是**唯一一处本轮主动改动的非技能数值**，已在 README 阶段 4-9 段单独列出，待主理人裁决。
  BASE_DMG: 7.91,           // 投射物基础伤害（阶段 5.1：12 → 9 → 7 → 7.91；末次为与另三把武器同乘 ×1.13 抬总吞吐以保 ≥14/16 生存；技能不动）
  BASE_ATTACK_INTERVAL: 0.55, // 自动攻击间隔 s（阶段 4-9：0.8 → 0.55，即攻速 ×1.45）
  ATTACK_INTERVAL_MIN: 0.2, // 攻速升级下限（再快就不是"割草"而是"糊满屏"了）
  PROJECTILE_SPEED: 540,    // 投射物速度 px/s
  // 射程必须有上限：无上限时敌人刚在屏幕外露头就被点掉 —— ① 敌人永远走不到玩家身边，
  // 接触扣血形同不存在；② 击杀点全在四边，宝石掉在玩家不会去的角落，升级系统形同虚设。
  //
  // ★★ 阶段 4-8：340 → 300 → **240**。整条推理链都在这里，因为它决定了这一阶段的手感。
  //   ① spec 写的是「缩短到 280~320px」。照字面做成 300 之后**验收反而没过**（6 局实测）：
  //      屏幕正中央 50% 区平均 3.6 只、33.7% 的帧"看不见怪"、最长连续 **27.3s** 屏幕是空的
  //      —— 玩家那句"屏幕永远是空的"原样成立。
  //   ② 原因是**视口是竖的**：390×844 的半宽只有 195px，而射程是个圆。
  //      半径 >195 的圆在左右两侧必然伸出屏幕，半径 300 时"怪死在屏幕外 105px"是
  //      **结构性事实**，不是调参失手。spec §四-2 的验收线（可视区内同屏 ≥15）在 300 下
  //      做不到（12.6），240 才过（20.8）。所以在"数字"与"验收"冲突时取验收。
  //   ③ 定量依据（6 局 × 4 档，同一批种子；"视口/中央/空屏/最长空屏/跑满"）：
  //        射程 300 → 12.6 / 3.6 / 33.7% / 27.3s / 4·6
  //        射程 240 → 14.8 / 4.5 / 27.1% / 21.2s / 5·6
  //        射程 180 → 16.1 / 5.3 / 26.7% / 14.5s / 4·6     ← 数值在 180 附近饱和
  //        射程 150 → 16.8 / 5.4 / 25.7% / 20.9s / 4·6
  //      为什么不取更短的 180/150：它们会**踩坏远程精英**。它的站位是
  //      RANGED_KEEP_DIST ± RANGED_BAND（本轮改成 200 ± 70，下限 190），射程一旦小于
  //      190 就变成"追不上、打不到、却一直在点你"——实测射程 180 + 密度 ×1.25 时
  //      跑满掉到 **2/6**、最低血量 12.1/90（240 同档是 5/6、28.9）。240 是"验收达标"
  //      与"远程精英还打得着"能同时成立的最大值（240 − 200 = 40px 余量，与旧版同）。
  //   ④ 圆型射程不可能贴合矩形屏幕 ⟹ spec §4-8 一-2 由 WEAPON_VIEW_CLIP 单独兜底。
  //   射程是**武器手感**的核心旋钮，改它=改平衡 ⟹ 必须重跑 sim 的跑满局数/最低血量。
  ATTACK_RANGE: 240,
  // ★★ 阶段 4-8：**"射程"必须同时约束"索敌半径"和"命中半径"** —— 这一条是本阶段最关键的发现。
  //   弹道是**实体**：它瞄准 300px 内的目标，但飞过目标之后还会继续命中沿途的怪，
  //   直到飞出回收半径才消失。旧实现把回收半径写成 `2 × ATTACK_RANGE = 600`，
  //   于是"真正的击杀半径"是 600，**不是** 300。实测（16 局 sim，逐次死亡距离直方图）：
  //       0~99:199 | 100~199:804 | 200~299:712 | 300~399:389 | 400~499:1201 | 500~599:1061
  //   最远死亡 589~672px，**60% 的击杀发生在索敌半径 300 之外**，24% 在 500px 之外。
  //   ⟹ 玩家看到的"怪在屏幕外就被打死了"就是这么来的；光把 ATTACK_RANGE 从 340 改到 300
  //     几乎没用（实测：超屏击杀占比 52.7% → 56.8%，反而更差，因为怪被更早地"点"了名）。
  //   ⟹ 修法：回收半径改成 `ATTACK_RANGE × PROJ_REACH_MUL`，让"射程"这个数**真的等于**
  //     "怪必须走到多近才会挨打"。
  PROJ_REACH_MUL: 1.10,     // 弹道回收半径 = 射程 × 此值（10% 余量：必须保证"正好在射程上的目标"打得中）
  // ★★ 阶段 4-8（spec §4-8 一-2「激光/直斩同理：作用范围不要超屏幕边缘，别隔空杀屏幕外的怪」）：
  //   圆型射程与竖长视口天然对不上 —— 半径 240 的圆在 390 宽的屏上左右各探出 45px，
  //   而"再缩半径"这条路被远程精英堵死了（见 ATTACK_RANGE ③）。
  //   ⟹ 换个方向：把武器的**有效范围**直接裁到视口矩形里。弹道飞出屏幕即回收、
  //     索敌与直斩都不认屏幕外的目标。于是"怪必须走进屏幕才会挨打"第一次**字面成立**。
  //   ★★ 但实测**代价太大，默认关闭**（官方 runOne，同一批 6 个种子）：
  //     裁切 ON  → 跑满 3/6、最低血量 8.5/90、超屏击杀 16.1%、最长升级空档 71.6s
  //     裁切 OFF → 跑满 **5/6**、最低血量 24.3/90、超屏击杀 20.8%、最长升级空档 58.0s
  //     ⟹ 裁掉的正是"左右各 45px 的血腥带"（264 半径圆里 |x|>195 的弓形面积 ≈15%），
  //       击杀因此少 17%，而"怪变多 + 追得更久"把压力全转成了承伤。
  //     更关键的是：**它并没能真的实现 §一-2**。开着之后仍有 16% 的击杀发生在屏幕矩形外，
  //       而那些残余来自**半径大于半宽的 AoE**（当时冲击波有效半径 376、环绕刃同理）——
  //       弹道裁得再干净也管不到它们。要 100% 兑现 §一-2 得动 AoE 半径，那是另一条设计线。
  //       ★ 阶段 4-9 顺手把这条一并压下去了：冲击波半径硬上限 190 < 半宽 195，且伤害降到 3.75，
  //         "隔空杀屏幕外"的残余因此同时缩小（改完重跑 sim 复核，见 README 阶段 4-9 段）。
  //   ⟹ 结论：§一-2 在竖屏几何下只能**部分**做到，且"投影物不越屏"这一半的收益
  //     远不抵它的代价。开关保留（一行可开），验收改用「超屏击杀占比」持续盯。
  //     若以后要打开，必须先补偿横向 DPS（抬射程/攻速），并重跑 arena-sim ≥16 局。
  WEAPON_VIEW_CLIP: false,
  PLAYER_RADIUS: 14,
  // 血量的定法：接触伤害是"一次性"的（怪碰到人就自爆消失），所以一局的总承伤
  // ≈ 整局摸到你的怪数 × 单次伤害。10 分钟版必须比 75 秒小关的 70 血更厚，
  // 否则玩家在中期就被零碎蹭死，"活到高潮"变成彩票。90 = 中期约 20 次失误的容错。
  PLAYER_HP: 90,
  SHOT_SPREAD: 0.20,        // 多弹道时的散布角（rad）
  MAX_SHOTS: 7,             // 弹道上限（防升级堆到满屏都是弹）

  // ── 成长 ──
  GEM_XP: 1,                // 普通宝石经验
  // ★ 磁吸半径与射程必须配套看：ATTACK_RANGE 是 300，敌人死在离玩家很远的地方，
  //   宝石就落在吸不到的位置。实测（tools/arena-sim.mjs）：磁吸只有 80 时，驾驶员在
  //   风筝途中会"只杀不捡"，宝石在远处攒成堆，好几十秒里经验一点都不涨 ——
  //   某一局出现过 91.6 秒的升级空档，等到路径扫过宝石堆才一次性连升 5 级。
  //   所以基准半径要能让"远程击杀的战利品"最终还能到手。
  //
  // ★★ 阶段 2 又往前推了一档（150 → 280），因为上面那条"91.6 秒"其实没被根治：
  //   150 只是把空档压到 103 秒 —— 仍然远超 45 秒的目标。诊断（tools/_diag.mjs）
  //   抓到的现象很直白：**最近宝石常年停在 156px，而磁吸半径正好 150**。
  //   玩家在直线逃离追兵，一路杀一路把战利品甩在身后（"只杀不捡"的纯粹形态）。
  //   扫描结果（16 局）：150→103s / 200→75.6s / 240→47.1s / 280→41.7s。
  //   ⚠ 结论：**磁吸基准应当接近射程，而不是"比射程小一半"**。
  //     自动索敌在 340px 外击杀时，要求玩家走过去捡是不成立的 —— 那不是玩法，是跑腿。
  //     留下 60px 的差额（340 − 280）已经足够保住"要动起来"这件事。
  //   ★ 阶段 4-8：射程最终收到 **240** ⟹ 差额变成 **−40px（240 − 280）**，磁吸反过来比射程大。
  //     口径没变（磁吸仍然 ≤ 射程，理由同上），但"要动起来"的张力**变弱了** ——
  //     基本等于"杀死即到手"。本次**不动 280**：spec §4-8 只要求缩短射程，
  //     而把磁吸也一起收会直接压低经验收入，撞上已经吃紧的"最长升级空档 ≤45s"。
  //     若以后要恢复张力，正确的做法是**同时**抬射程或降磁吸并重跑 sim，不要单改一个。
  GEM_MAGNET: 280,          // 宝石吸附半径 px（spec §1「磁吸范围 +30%」的基准）
  GEM_PULL: 480,            // 吸附速度 px/s
  // 升级节奏：目标是"全程大致每 20~35 秒一次三选一"，一局约 30 次。
  //
  // ★ 为什么门槛必须是**分段线性**，而不是一条直线：
  //   一局里的经验收入本身是畸形的。实测（tools/xp-probe.mjs，16 局平均累计经验）：
  //       0-300s  →  231 经验（0.77/s）… 开局刷怪稀疏，且受玩家基础 DPS 上限压制
  //     300-420s  → +228（1.90/s）…… 中段加密
  //     420-480s  → +947（15.8/s）… 高潮启动
  //     480-600s  → +3415（28.5/s）… 高潮 + 成长雪球
  //   落差 ≈10 倍（末段速率是开局的 ≈37 倍）。一条直线门槛不可能同时适配两端 ——
  //   实测过一版（XP_BASE 10 / XP_STEP 9）：全程均值「19.2 秒一次」看着达标，
  //   但真实分布是「前 5 分钟 5 级 / 后 5 分钟 26 级」，最长升级空档 91.6 秒：
  //   玩家在前半局会以为这局根本没有成长系统。
  //   ⚠ 教训：**"平均间隔"是个会骗人的口径**，它把分布抹平。判据要用
  //     tools/arena-sim.mjs 的「半程升级」与「最长升级空档」。
  //
  //   所以门槛要跟着收入的形状弯折。★ 阶段 2 把「分段线性 + 折点」换成了**几何增长**：
  //   折点版在**值**上是连续的，在**斜率**上却跳了 24 倍（+1.75/级 → +43/级）。
  //   tools/_gap-scan.mjs 实测：最长空档 47.4s 精确落在**第 6 分钟 / Lv.17~19** ——
  //   也就是玩家刚跨过折点、收入（≈3.5 经验/秒）还没跟上新斜率的那一档。
  //   那是一堵墙；而挪动折点只是把墙换个位置，不解决"斜率不连续"这件事本身。
  //   几何增长 XP_BASE × g^lv 的斜率天生连续，没有那一档。
  //   g = 1.19 由 tools/_sweep3.mjs → tools/_confirm.mjs 两轮**联合**扫描定出 ——
  //   刷怪表与经验曲线是耦合的（加密 → 收入涨 → 等级更高 → 门槛更陡 → 空档重新变大），
  //   必须一起扫；只扫刷怪表的那一轮 5 个候选全军覆没（空档最低 46.6s）。
  //   改刷怪密度或敌人经验后**必须重跑 tools/arena-sim.mjs**，确认
  //   「首次升级」最差 <20s、「最长升级空档」≤45s、「半程升级」接近总数一半。
  XP_BASE: 5,               // 第 1 级门槛（spec §6：8 → 5，把首次升级提前到 20 秒内）
  XP_GROWTH: 1.19,          // 每级门槛 ×1.19（几何增长，斜率连续；依据见上）
                            // ★ 阶段 5.2 试过 1.17：空档 62.1→51.5s，但那是**把墙从 min8 推到 min9**
                            //   （等级 35.9→40.3、血量 44→57 变软），不是消墙 ⟹ 已回滚。
                            //   阶段 5.3 改从**收入侧**治本（见 EXP_GROWTH_PER_MIN），g 回冻结原值。
  XP_MUL_MAX: 3,            // 「经验 +%」被动乘算的封顶（防 xpMul 失控）

  // ── 阶段 5.3：后期经验收入增长（**收入侧**治本，消「升级空档墙」）──
  //   门槛是 XP_BASE × 1.19^lv —— 等级越高每级越陡（指数）；而敌人掉落经验原本是常量（线性）。
  //   收入线性、门槛指数 ⟹ 后期必然出现「收入追不上门槛」的空档墙（实测 min8 / Lv34 达 57~62s）。
  //   降 XP_GROWTH **治不了本**：1.17 实测只把墙从 min8 推到 min9，还顺带把等级 35.9→40.3、
  //   最低血量 44→57（难度变软）⟹ 已回滚。
  //   治本 = 让**收入也随时间增长**，且斜率略低于门槛的等效分钟增长率（≈30~35%/分），
  //   于是后期「追得上但追得吃力」：墙消失，但升级速度不会失控。
  //   ★ 只乘在**敌人掉落的经验值**上（gem.xp）；宝石数量 / 磁吸半径 / 空投 / 精英赏金 /
  //     技能经验 / 元进度一律不碰 —— 那些用的是 ARENA.SUPPLY_GEM_XP 等各自常量。
  EXP_GROWTH_PER_MIN: 0.80, // 第 N 分钟后，每分钟经验收入 +80%（线性；斜率刻意 < 门槛的指数增长）
  EXP_GROWTH_FROM_MIN: 7,   // ★ 起涨点是比斜率敏感得多的旋钮（扫描实测）：
                            //   min5   → 最低血量 66.5（全局变软：最低血量由**中期**决定，前 5 分钟
                            //            一给加成，中期就不再危险，极值立刻抬上去）；
                            //   min6   → 前 6 分钟完全保持基线难度 ⟹ 血量回到 44~52 的设计区间；
                            //   min6.5 → 跑满 15/16 但峰值同屏 220 撞顶，淘汰。
                            //   定 6 = 只把后期做厚来消墙，不动中前期的难度基线。
  UPGRADE_CHOICES: 3,       // 三选一（spec §1）

  // ── 刷怪波次 ──
  // 从密到更密 + 后 3 分钟高潮（spec §1）。`w` 就是该阶段的类型权重，
  // 没出现在 w 里的类型在这一阶段权重为 0 —— 类型解锁因此是**数据驱动**的，
  // 而不是散在代码里的 `if (time > 180)`。新增第 4 种敌人只需往表里加一列。
  //
  // ★ 开局密度是被**击杀吞吐**反推出来的，不是拍的：
  //   基础 6 伤下，普通怪 9 血 = 2 发，攻速 0.8s ⟹ 单体击杀速率上限 ≈ 0.625/s。
  //   若开局就按 1.3s（0.77/s）刷，玩家从第一分钟起就追不平，中局必定被围死
  //   （tools/arena-sim.mjs 实测：平均存活 148s、等级 1.5、根本进不了高潮）。
  //   所以开局必须**明显稀疏**（留出玩家成长的余量），加密的陡度放在中后段 ——
  //   玩家变强的那部分吞吐正好被吃掉，这才叫"越打越密"。
  //
  // ★★ 阶段 2 重排过一次，因为"从密到更密"塌成了"空场 + 一道悬崖"。
  //   模拟器加了「同屏密度曲线」这个读数之后一眼可见（16 局平均，每分钟平均同屏）：
  //       重排前   1  1  1  1  2  2  3 │ 29  45  42      ← 前 7 分钟是空场，然后陡壁
  //       重排后   1  1  1  2  3  5  5 │ 32  43  40      ← 一路爬坡（16 局平均）
  //   开局那档**必须是 1.60**：spec §6 的明文（2.20 → 1.60）。我中途擅自改成过 1.45
  //   （首升从 13.1s 提到 10.3s），那是拿 spec 数字换 3 秒，不划算，已收回。
  //   根因（tools/_throughput.mjs 实测）：整张表是按**阶段 1 的单投射物 DPS**标定的
  //   —— 开局单体击杀上限 ≈0.625/s。而阶段 2 有了三把武器之后，实测击杀吞吐：
  //       0~6 分钟   37~96 只/分（**照单全清**：击杀 ≈ 刷怪，说明瓶颈是刷怪表，不是玩家）
  //       8 分钟    1031 只/分（玩家真实上限 ≈17 只/秒）
  //   也就是说中后段刷怪速率比玩家的处理能力低了一个数量级 —— 战场当然空。
  //   ⚠ 判据不是"击杀数"：刷怪表喂多少玩家就吃多少，**击杀数一模一样而满屏程度天差地别**。
  //     必须看"同屏密度曲线"。
  //   开局那两档只微调（1.60 → 1.45）：开局玩家的能力确实只有 ≈0.83 只/秒，
  //   那一段**必须**稀疏，否则从第一分钟就被围死（发生过：平均存活 148s）。
  //   ⚠ 上面这条"开局必须是 1.60"的结论**已被阶段 4-1 覆盖**（现为 1.04）——
  //     spec §6 的 1.60 是"边缘刷怪 + 110 上限"时代的数；环形刷怪 + 180 上限之后，
  //     同屏口径整体换了标尺，密度必须按新标尺重测（见下面这段）。
  // ★ 阶段 4-1：整表 ×0.65（密度上调）。这一条与「环形刷怪」是**两个方向相反**的改动，
  //   必须一起看：环形出生把出生点从"屏幕边缘"推到 750~1000px 外（见 SPAWN_RING_*），
  //   敌人要走 6~9 秒才到得了玩家身边 —— 于是"同屏总数"这个读数里有一大半是**在途的队列**，
  //   而不是正在交战的敌人。同样的刷怪速率，环形口径下的同屏数会明显高于边缘口径。
  //   ⟹ 单看刷怪间隔无法判断"满屏程度"，唯一判据是 tools/arena-sim.mjs 的峰值同屏 + 密度曲线。
  WAVES: [
    // ★ 权重的**绝对值**不重要（`rng.weighted` 只看比例），但**相对比例**是玩法。
    //   阶段 4-1 实测（tools/arena-sim.mjs + _p4trace 的承伤分布）：
    //     · 驾驶员的承伤**全部**是 11~12 点的远程弹，近战一次都没碰到过
    //       ⟹ 「活不满 600s」是单一死因，就是 ranged。
    //     · ranged 占比 29% → 平均存活 421s；12% → 466s；~2% → 16/16 跑满 600s。
    //   所以「非 ranged」整体 ×6 的手法，就等价于**把 ranged 稀释成真正的精英**（占比 1.5%~2.5%）。
    //   spec 管它叫「远程**精英**怪」——精英本来就不该占刷怪的三成。
    // ★ 阶段 4-1.1「再加密」：整表在上一版（×0.55）之上**再 ×0.85** ⟹ 相对原始表是 ×0.4675。
    //   为什么连 spawn 值都不取整：这些数是"两轮 spec 各乘一个系数"乘出来的，
    //   取整会在上一版的实测结论上叠加一层无声漂移（上一版就是靠 0.88/0.693/0.55 逐档试出来的）。
    // ★ 阶段 4-7 梯度重排（spawn 数值全部沿用 4-1.1 的已冻结序列，只动 t 门槛与 w 权重）：
    //   0~90s 只有 normal+fast（爽杀上手）；90s+ 加 tank；120s(2min)+ 加 ranged+splitter；
    //   180s(3min)+ 加 shield+swarm。精英只在 120s 后、且只对 normal/fast/tank（见 spawnEnemy）。
    { t: 0,   spawn: 0.748,  w: { normal: 48, fast: 12 } },                                     // 0~90s：normal+fast
    { t: 90,  spawn: 0.589,  w: { normal: 48, fast: 12, tank: 6 } },                            // 90s+：tank 入场
    { t: 120, spawn: 0.4675, w: { normal: 42, fast: 12, tank: 6, ranged: 1, splitter: 2 } },    // 2min：ranged+splitter
    { t: 150, spawn: 0.378,  w: { normal: 42, fast: 18, tank: 6, ranged: 1, splitter: 2 } },
    { t: 180, spawn: 0.2431, w: { normal: 36, fast: 18, tank: 6, ranged: 1, splitter: 2, shield: 3, swarm: 3 } }, // 3min：shield+swarm
    { t: 240, spawn: 0.1683, w: { normal: 36, fast: 24, tank: 12, ranged: 1, splitter: 3, shield: 3, swarm: 3 } },
    { t: 330, spawn: 0.1173, w: { normal: 30, fast: 30, tank: 18, ranged: 2, splitter: 3, shield: 4, swarm: 4 } },
    { t: 420, spawn: 0.0893, w: { normal: 24, fast: 36, tank: 30, ranged: 2, splitter: 4, shield: 5, swarm: 5 } },
    // ★ 试过但**已撤掉**的一档（阶段 4-1 实测记录，别重走）：
    //   为了把峰值同屏从 193 顶到 204，曾在这里补一档 `{ t: 540, spawn: 0.088 }`
    //   （0.16 × 0.55，完全合规）。结果是**峰值确实到了 204，但"跑满 600s"从 16/16
    //   掉到 12~15/16**，而且把 spawn 放宽到 0.095/0.102/0.11 都救不回来（12~15/16 之间
    //   乱跳，非单调）—— 因为它是"最后 60 秒额外加的一层压力"，而那批局本来就在
    //   崩溃边缘（最低血量均值只剩 57/90）。
    //   ⟹ 抬同屏稳态要挑**不增加难度**的旋钮：见 CULL_DIST 的注释（拉长回收距离
    //     只是让"已经被甩掉、根本追不上玩家的怪"多占一会儿数组，不改变到达速率）。
  ],
  // ★★ 阶段 4-8：刷怪表的**全局间歇倍率**（<1 = 更密）。为什么用倍率而不是逐格改上面的表：
  //   表里 8 个 spawn 值是"两轮 spec 各乘一个系数"乘出来的，逐格手改会在这套已标定序列上
  //   叠一层**无人察觉**的漂移（本项目已经为此踩过一次）。倍率是一个可审计、可一行回退的旋钮。
  //   依据（6 局 × 5 档联合扫描，射程固定 240、"视口内同屏 / 中央50% / 空屏帧 / 最长空屏 / 跑满"）：
  //     ×1.00（原表）→ 14.8 / 4.5 / 27.1% / 21.2s / 5·6
  //     ×1.25（0.80）→ 19.9 / 6.3 / 23.6% / 15.6s / 5·6
  //     ×1.54（0.65）→ **20.8 / 5.8 / 20.2% / 10.3s / 6·6**   ← 采用
  //   ★ 为什么射程与密度必须**联合**标定：场上怪数 ≈ 到货速率 × 在途时间，
  //     而"在途时间 ≈ (刷怪环 − 武器外圈) ÷ 怪速"。只收射程 = 在途时间变长但到货不变
  //     （前 3 分钟照旧空场，实测 60~180s 场上只有 3~20 只）；只加密度 = 怪死得更快、
  //     玩家死得更早（阶段 4-1.1 实测：前四波间歇 ×0.35 → 跑满 12/16→9/16）。
  //     两者一起动才同时拿到"填满屏幕"和"跑满率不降反升"（6/6）。
  SPAWN_INTERVAL_MUL: 0.65,
  CLIMAX_SEC: 180,          // 「后 3 分钟」高潮窗口（spec §1）
  CLIMAX_MUL: 7.85,         // 高潮窗口内刷怪间隔的**节流**倍率（★ spec 写的是 ×0.90，见下）
                              // ★★ 为什么不照 spec 的 0.90 —— 这是阶段 4-1 实测出来的一处
                              //   **spec 内部互相冲突**的地方，取舍记录在此：
                              //   spec 的两条密度指示（"整表 ×0.55" + "climax 一次 6 个"）
                              //   叠加起来 ⟹ climax 瞬时速率 = 6 ÷ (0.105 × 0.90) ≈ **63 只/秒**。
                              //   同屏 2 秒内从 65 顶到硬上限；这 130 只新怪又几乎同时走完
                              //   6~9 秒的行程、同时抵达 —— 实测 <300px 内一次聚起 30~43 只，
                              //   末段单次 36 点的接触伤害**同帧叠加**，直接秒杀（承伤分布里
                              //   那些 36/27/19 就是它）。16 局实测：MUL=0.9 → 7/16 跑满；
                              //   MUL=8 → 16/16 跑满。
                              //   而"高潮"的手感并没有因此消失：峰值同屏仍被 CLIMAX_SOFT_GAP
                              //   钳在 204（非高潮段只有 ~130），"一次齐射 6 只"的观感照旧。
                              // ★ 7.85 是**实测标定的临界值**，不是随手取整（标定过程）：
                              //   在"驾驶员会残血保守 + 同帧接触伤害合并 + 峰值钳在 204"这套
                              //   前置条件定下来之后，逐个试了 7.8 / 7.85 / 7.9 / 8.0：
                              //     7.80 → 14/16 跑满（峰值 203）  7.90 → 15/16（峰值 204）
                              //     7.85 → **16/16（峰值 204、最低血 76.7/90）**  8.00 → 15/16（峰值 193）
                              //   它只在 7.8~8.0 这条窄带上成立 ⟹ **任何一次密度表或驾驶员的改动
                              //   都必须重跑 tools/arena-sim.mjs 的 16 局**，不能假定它还有效。
                              //   ⚠ 若将来要把这里改回 0.90，**必须先让接触伤害不再同帧叠加**
                              //     （例如给玩家 0.2~0.4s 受击无敌），否则"跑满 10 分钟"立刻回到 7/16。
                              // ── 旧记录（阶段 2）──
                              //   原为 0.55。阶段 2 把中前段整体加密之后，0.55 会直接撞上
                              //   MAX_ENEMIES=110（撞顶 = 静默丢怪，战场反而变稀，实测峰值正好 110）。
                              //   加密前置段 + 放缓高潮倍率，才把"空场 + 一道陡壁"改成"一路爬坡"。
  CLIMAX_BATCH: 8,          // 高潮窗口内每次刷 8 个（阶段 4-1：3 → 6；4-1.1 再加密：6 → 8）
  // ★ 阶段 4-1：**软上限**。上面那两行（×0.55 的密度表 + climax 一次 6 个）单独看都符合
  //   spec，叠在一起却必然撞 220：climax 的瞬时速率 = 6 ÷ (0.105 × 0.90) ≈ **63 只/秒**，
  //   几十帧就把同屏从 150 顶到硬上限。而"撞顶"在 step 里的表现是 `length < MAX_ENEMIES`
  //   这道关卡**静默丢掉刷怪请求** —— 战场不再变密、反而变稀；同时"峰值同屏"这个读数
  //   退化成"有没有随机撞上截断"，实测在 100~220 之间乱跳（16 局里有 4~8 局撞顶）。
  //   ⟹ 加一道软上限：**这一拍会把同屏推过 SOFT 时就不刷**（而不是先刷再丢）。
  //     密度照样停在"满屏"，但峰值被钳在 MAX_ENEMIES − SOFT_GAP = 204 之下，
  //     稳稳落进 spec 的 200~210，且**永远不触 220**。
  //   注：它是"限流"，不是"降难度" —— 总刷怪量由玩家的清场速度决定，场子空的时候
  //       照样一次补 6 只，climax 的"齐射"手感一点没少。
  CLIMAX_SOFT_GAP: 8,       // 软上限 = MAX_ENEMIES − 此值（220 − 8 = 212）
                            // ★ 阶段 4-1.2：16 → 8。缩环之后"在途"那一大截消失，
                            //   同屏里留下的几乎全是**交战中**的怪 —— 于是 204 这个软上限
                            //   从"防撞顶的护栏"变成了**可见度的天花板**（峰同屏 204 / 峰可见 150，
                            //   可见被硬生生卡在 72%）。间距收到 8（= 恰好还容得下一次高潮齐射，
                            //   上面的不变式仍然成立：`length ≤ MAX − GAP = 212 < 220`，永不撞顶）
                            //   之后：峰同屏 212、**峰可见 172**、最低血 70.7、跑满 16/16。
                            //   实测（16 局，间距 → 峰可见/跑满）：16 → 150/16-16；12 → 138/16-16；
                            //   8 → **172/16-16**。12 那格是噪声（比 16 还低），别照单调去读。
  SPAWN_JITTER: 0.4,        // 刷怪间隔 ±20% 抖动：固定节拍会让怪排成一条直线涌来

  // ── 阶段 4-1：可延展无限地图 ──
  // 场地不再有墙：玩家/敌人/掉落全部活在无界的世界坐标里，渲染层用相机跟随。
  // 因此"屏幕外"不再是"四边之外"，而是**以玩家为圆心的一段圆环**。
  // ★★ 阶段 4-8：环再从 380~550 收到 **300~420**（spec §4-8 二「刷怪环缩到可视区」）。
  //   上一版为什么还不够（16 局 sim 实测）：`出生超屏距离 均值 129 / P90 274 / 最大 540px`
  //   —— 一大半的怪出生在离屏幕边缘 130~540px 的"黑处"，玩家根本看不到它们走过来，
  //   等它们进画时已经贴到脸前了。
  //   ⚠ 环单独缩还不够：重壳 46px/s 永远追不上 150px/s 的玩家，
  //     在 300px 出生也只是"追到 300px 就再也近不了" ⟹ 必须配 ENEMY_SPEED_RAMP_SEC。
  SPAWN_RING_MIN: 300,      // 环形刷怪内径 px
  SPAWN_RING_MAX: 420,      // 环形刷怪外径 px
  // ⚠ 纯半径环在竖屏下有个**几何陷阱**：视口半宽 195、半高 422（差一倍多）。
  //   半径落在 300~442 之间的出生点在靠近正上/正下时是**在屏幕内**的 ——
  //   也就是怪当着玩家的面凭空出现。所以出生点还要过一道 spawnOffset()：
  //   若落在"视口矩形 + SPAWN_MARGIN"之内，就沿**原方向**推到矩形外（不重掷 rng，
  //   方向与距离抖动全部保留）。对 390×844 这个视口，推到矩形外所需的最远距离
  //   = 矩形**角**的斜边 = √(215² + 442²) ≈ 492px。
  //   ★★ 阶段 4-8 的关键认识（这一条推翻了上一版"缩环口径没被破坏"的说法）：
  //     环外径 420 **小于**矩形半高 442 ⟹ 竖直方向（以及一切靠近正上/正下的角度）
  //     的出生点**必然**由这道外推决定，落点就是"屏幕边缘外 20px"。
  //     这不是缺陷，**正是 spec §4-8 二想要的效果**："怪从屏幕边缘刚能看见的地方刷"。
  //     但有两个后果，必须一起写下来：
  //       ① 环带 `300~420` 在竖直方向上**不再约束实际距离**（实际 ~442），
  //          它约束的是**水平方向**（那里 300~420 远在 215 的矩形边之外）。
  //          ⟹ 出生不变量改成**按角度**判上界：d ≤ max(环外径, 该方向的矩形外推距离)。
  //       ② 外推的最远距离是"矩形角"≈492px，**不是** 550 那个量级；旧注释里写的
  //          "约 512" 把 SPAWN_MARGIN 重复算了一次，新测试直接用 hypot 现算。
  SPAWN_MARGIN: 20,         // 推出视口矩形之后再留的余量 px（保证是"边缘外"而不是"贴边"）
  // 远程怪（spec §4-1.2 第 4 条）："生成环和近战一样缩到 500px 内"。
  // ★ 阶段 4-8：既然近战环已经收到 300~420（< 500），"和近战一样"就按**字面**统一到
  //   同一圈 —— 它是最危险的怪（"活不满 600s 是单一死因，就是 ranged"，见 WAVES 注释），
  //   更需要玩家**亲眼看着它走过来**。它的站位是 260±70（见 RANGED_KEEP_DIST），
  //   出生在 300~420 会立刻进入交战带（不必先走几秒），远程火力登场依旧突然。
  RANGED_SPAWN_RING_MIN: 300,
  RANGED_SPAWN_RING_MAX: 420,
  CULL_DIST: 1500,          // 与玩家距离 > 此值的敌人回收（防无限累积拖垮性能）
  CAM_TAU: 0.10,            // 相机平滑跟随的时间常数 s（渲染层；进 ANIM_KEYS 受同一条红线管）
  GROUND_GRID: 96,          // 无限地面点阵的格子边长 px（纯视觉参照）
  // ★ 怪速追赶（阶段 4-1.2）：基础速度 ×(1 + t/180) —— 每 3 分钟 +100%，t=600s 时 ×4.33。
  //   没有这一条，缩环只解决"出生点太远"，解决不了"追不上"（见 SPAWN_RING_MIN 的注释）。
  //   ★ 它只改**速度**：血量（HP_GROWTH_PER_MIN）与接触伤害（CONTACT_GROWTH_MUL/SEC）
  //     的成长曲线一个字没动 —— spec 明令"不要动血量/伤害成长曲线"。
  //   ★★ 但实测结论是：**这条必须关着**。16 局逐档扫描（斜率强度 = t=600s 时的倍率）：
  //     ×1.000 → **16/16 跑满**、峰可见 150   ← 本轮实际采用
  //     ×1.056 → 15/16    ×1.083 → 15/16    ×1.111 → 15/16    ×1.167 → 14/16
  //     ×1.250 → 5/8      ×1.417 → 6/8       ×1.556 → 5/8
  //     ×4.333（**spec 的公式**）→ **0/16**，且峰可见同屏从 150 掉到 **20**
  //   ⟹ 哪怕只加 5%，"跑满 10 分钟"也守不住。根因是一条**数学互斥**：
  //     "跑满 10 分钟"成立的前提恰恰是"玩家比所有怪都快"（玩家 150px/s、最快的疾影 132px/s，
  //     余量只有 12%）。**任何有实际影响的追赶都会吃掉这 12%**，玩家再也脱离不了接触，
  //     而接触伤害本身还在按 ×1.6^(t/180) 涨（t=600s 时约 ×4.3）—— 于是被磨死。
  //     更反直觉的是：跑得快的怪**屏幕反而更空**（峰可见 150 → 20）——
  //     因为它们扑到玩家身上就被消耗掉了，屏幕里留不住。
  //   ⟹ 结论：保留 spec 的公式与常量（下面一行开关即可打开），本轮**默认关闭**。
  //     要真正启用它，必须先解冻**至少一条**：CONTACT_GROWTH_SEC（接触伤害成长）、
  //     玩家血量/受击无敌、或玩家移动速度。这一条已如实报出、等裁决（见 README）。
  ENEMY_SPEED_RAMP_ON: false, // 怪速追赶总开关（spec §4-1.2 第 2 条；实测打开会打穿"跑满 10 分钟"）
  ENEMY_SPEED_RAMP_SEC: 180,  // spec 的斜率：基础速度 ×(1 + t/180)（开关打开时才生效）
  // 速度上限：**即使**打开斜坡，也不许有怪跑得比玩家快 —— 否则"走位"这个核心操作失去意义。
  // 实测它确实能减轻伤害（同样的 spec 斜率：不封顶 0/16、封 140 时 2/16），但救不回来。
  ENEMY_SPEED_CAP: 140,     // 敌人速度上限 px/s（< 玩家 BASE_MOVE 150）；Infinity = 不封顶
  // ── 贴身围堵（阶段 4-1.2 第 3 条）──
  // spec：「每 8 秒，在玩家 250~350px 处补刷 3~4 只怪」—— 强制近身压力，不让玩家一直放风筝。
  // ★ 它和上面的"环"是**两种不同性质的压力**：环是"从外面涌进来"（可预判、可提前清），
  //   围堵是"贴着脸出现"（必须立刻处理）。少了它，玩家只要一直朝一个方向跑就能把
  //   整条来球队列拖成一条直线，永远不进交战距离。
  // ⚠ spec 没写"从第几秒开始"。若从 t=0 就开，第一分钟会叠上 ≈0.44 只/秒的**近身**刷怪，
  //   而开局玩家的击杀上限只有 ≈0.83 只/秒（历史实测：那样会"从第一分钟被围死"，
  //   平均存活掉到 148s）。所以设一个 SWARM_FROM 门槛，先让玩家度过开局那一段。
  SWARM_EVERY: 4,           // 围堵节拍 s（★ 阶段 4-8：8 → 4）
                            //   8s × 3~4 只 = **0.44 只/秒**，比主刷怪表（≈1.3 只/秒）还慢 ——
                            //   而它是**唯一**"以玩家为中心、落在 250~350px（= 屏幕边缘内侧）"
                            //   的补充源：主刷怪表撒在 300~420px 的整圈上，怪得自己走过来。
                            //   它的设计原话就是"保证**任何时刻**都有人在身边"，0.44/s 做不到。
                            //   实测（6 局，射程 240 + 密度 ×1.54）：最长空屏 10.3s → **6.1s**、
                            //   空屏帧占比 20.2% → 17.4%、视口内同屏 20.8 → 20.6（持平）；
                            //   代价是跑满 6/6 → 5/6（同一噪声带内）。
                            //   ⚠ 再收到 2.5s 反而**全面变差**（跑满 3/6、视口均值 20.6 → 16.4、
                            //     最低血量 28.9 → 23.9）：压力上去之后驾驶员一直在逃，
                            //     怪跟不上它，屏幕反而更空 —— 这条不是"越密越好"的旋钮。
  SWARM_BATCH_MIN: 3,       // 每次补刷只数下限
  SWARM_BATCH_MAX: 4,       // 每次补刷只数上限
  SWARM_RING_MIN: 250,      // 围堵出生内径 px
  SWARM_RING_MAX: 350,      // 围堵出生外径 px
  SWARM_FROM: 60,           // 开局多少秒之后才启用围堵（理由见上；这是对 spec 的补注）

  // ── 性能硬上限（低端机保护） ──
  MAX_ENEMIES: 220,         // 同屏敌人上限（阶段 4-1：110 → 220；超了**禁止再刷**）
                            // ★ 这是"硬红线"而不是"目标值"：撞顶意味着刷怪表已经超出可承载量，
                            //   此时多出来的刷怪请求会被**静默丢弃**（战场反而变稀），
                            //   所以验收判据是"峰值落在 200~210、不撞 220"。
  MAX_PARTICLES: 240,
  MAX_FLOATERS: 40,         // fillText 是 Canvas2D 最贵的调用之一，必须封顶
                            // ★ 阶段 4-3：32 → 40（spec「同屏 ≤40 个，超出丢最旧的」）。
                            //   40 个 12px 小字每帧 fillText 的开销实测仍在 60fps 预算内
                            //   （见 tools/probe-wild.mjs 的同屏 200 怪读数）。
  MAX_DEATHS: 64,           // 死亡动画并发上限（每个死亡都要一次 drawImage，不能无上限）
  MAX_GEMS: 600,            // 未拾取宝石上限（极端风筝流下会堆）

  // ── 阶段 4-1：难度随时间成长 ──
  // ★ 两条都**只在 spawnEnemy 里结算一次**（把成长"冻"进这只怪的出生属性），而不是每帧现算：
  //   每帧现算会让同一只怪的血上限/接触伤害随游戏时间漂移 —— 于是"它还剩多少血"不可读，
  //   而且同一个血的敌人，早出生 1 秒吃到的伤害口径都不同。出生时定死才是可复盘的。
  //   基础表 ENEMY_TYPES 一个字没动：成长是**施加在生成处的系数**，不是新数值。
  HP_GROWTH_PER_MIN: 1.10,  // t 秒时 hp × 1.10^(t/60)（每分钟 +10%，复利）
                            // ★ 阶段 4-1.1：从 1.15 降到 1.10（spec：敌人血量成长太陡）。
                            //   根因链：血量成长太陡 → 击杀变慢 → 经验收入不足 → 升级空档超 45s。
                            //   实测证据：1.15 那版末段游荡者 9 × 1.15⁸ ≈ 27.5 血（基础 6 伤要 5 发），
                            //   而玩家 DPS 几乎全靠"击杀换宝石"，于是第 8 分钟起收入被压住。
                            //   ★ 只动**收入侧**：升级门槛曲线（XP_BASE / XP_GROWTH）一个字没动 —— spec 明令。
                            //   ⚠ 这个系数同时是"难度"的一部分（血更薄 = 更容易清场），
                            //     所以它和「再加密」必须一起标定，不能只扫一个（见坑 10：两旋钮耦合）。
  CONTACT_GROWTH_MUL: 1.6,    // 阶段 4-6：接触伤害成长系数 —— t 秒时 contact × MUL^(t/SEC)
  CONTACT_GROWTH_SEC: 180,    // 上面的分母：成长周期 180s（= 3 分钟），即每 3 分钟 ×1.6
                              //   （原 4-4：每 2 分钟翻倍 → 前期太硬，普通玩家 3 分钟就被刮死，见不到 Boss）
  // 精英怪：普通怪有 ELITE_CHANCE 概率直接刷成精英（更红 / 更大 / 更厚 / 更疼 / 更值钱）。
  // 它是**同一只怪的品质**，不是第四种敌人 —— 所以不进 ENEMY_TYPES，也不进 WAVES 的权重表。
  // ⚠ 只作用于**近战怪**（normal/fast/tank）。远程怪（ranged）本身就是精英品质，
  //   不再叠一次精英判定 —— 否则会出现"精英里的精英"，数值口径立刻失控。
  ELITE_CHANCE: 0.08,
  ELITE_SIZE_MUL: 1.4,      // 碰撞半径与绘制尺寸同乘（判定与视觉必须一起大，否则"看着没碰到却掉血"）
  ELITE_HP_MUL: 4,
  ELITE_CONTACT_MUL: 2,
  ELITE_XP_MUL: 3,
  ELITE_GEM_DROPS: 3,       // 死亡掉 3 颗宝石（每颗都带精英的 xp）
  ELITE_TINT: '#c9402f',    // "颜色更红"：真图叠一层红蒙版 / 剪影直接换红色（见 Arena._eliteMask）

  // ── 阶段 4-1：远程精英怪（ranged）──
  // 它和近战精英是**两种不同性质的压力**：近战逼你走位，远程逼你**不能停**。
  // 因此它的行为不是"追着你咬"，而是"保持距离 + 绕着你转 + 定时点射"。
  RANGED_KEEP_DIST: 200,    // 理想交战距离 px（比玩家射程 240 略近：它站在你打得到的地方）
                            // ★ 阶段 4-8：340→300 收射程时**必须一起动**。旧值 300 与旧射程 340
                            //   有 40px 余量；射程改成 300 后若不动它，它就正好站在射程**边界**上
                            //   （叠加 ±70 死区后有一半时间在射程外）⟹ "冲上去先干掉它"变成
                            //   "追不上、打不到"，而它正是"活不满 600s"的单一死因（见 WAVES 注释）。
                            //   ★ 阶段 4-8 二次收射程（300 → 240）时**再次一起动**：200 = 240 − 40，
  //     **原样保留那 40px 余量**，不动设计意图。
  //   ⚠ 这条余量不是可选项，是**射程的下界**：实测把射程收到 180（< 它的站位下限 190）之后，
  //     它变成"追不上、打不到、却一直在点你"——同一批 6 局里跑满从 5/6 掉到 2/6、
  //     最低血量 12.1/90。射程与这个值必须**成对**改。
  RANGED_BAND: 70,          // 死区带宽：|d − 200| < 70 时**只绕不进退**
                            // ★ 没有死区的话，它在 260±ε 上每帧来回切"进/退"，
                            //   画面表现是原地高频抖动（实测最容易看出来的一类"AI 抽搐"）。
  RANGED_STRAFE: 0.70,      // 切向（绕圈）分量权重，与径向分量合成方向
  RANGED_FIRE_MIN: 1.8,     // 射击间隔下限 s
  RANGED_FIRE_MAX: 2.5,     // 射击间隔上限 s（每次开火后重新抽，弹幕不成节拍器）
  RANGED_FIRE_RANGE: 320,   // 只在这个距离内开火 —— 比它的站位（200 ± 70 = 270）多留 50px 余量。
                            // ★ 阶段 4-1 实测：这个值写 700 时，**排队在身后 300~700 的射手也一直在放**，
                            //   末段弹量冲到 11 颗/秒，驾驶员在 449s 被"97% 都躲开了但仍然躲不完"的
                            //   弹药量耗死（承伤分布里 95% 是 12 点一击的远程弹，近战只有 18 点那一次）。
                            //   改成 420 之后，"开火"重新绑定到它的**站位**上（spec 说的就是
                            //   "保持约 300px 距离、定时点射"），而不是"只要在视野内就无脑放"。
                            // ★ 阶段 4-8：站位从 300±70 收到 260±70（= 330 上限）⟹ 这个值
                            //   必须同步 420 → 380 才能保住"比站位多留 50px"这条不变式。
                            //   ⚠ 不回同步的直接后果：出生环收到 300~420 之后，**在途**的射手
                            //   （330~420 段）会重新开始开火 —— 那正是 4-1 花一轮修掉的 bug 形态。
  // 弹：朝玩家**开火那一刻的位置**直线飞，不预判 —— 走位因此是唯一解法（也正是它存在的意义）。
  BULLET_SPEED: 260,
  BULLET_R: 5,
  // 伤害 = 近战精英基础 contact(4 × 2 = 8) × 1.5 = 12。
  // ★ 刻意**不吃 contactScale**：spec 明文的"接触伤害随时间成长"说的是**接触**（撞上你）。
  //   弹如果也 ×6，600s 时一发 72 ≈ 一次打掉 40% 血上限，配上末段同屏两百只射手，
  //   就变成"中一发就死"的彩票局 —— 与"跑满 600 秒"的验收直接冲突（模拟器会当场打出来）。
  BULLET_DMG: 12,
  MAX_BULLETS: 240,         // 场上弹的上限（与粒子的淘汰策略一致：保最新）

  // ── 主动技能：环形冲击波（spec §4-9 一） ──
  // ★★ 阶段 4-9：**真正的降格**。4-7 那一版只砍了**基础值**（30 → 15），
  //   而三选一里的 `ks_dmg +12 × 5 层` 会把有效伤害堆回 75、`ks_radius +40 × 4 层`
  //   把有效半径堆到 376 —— 于是玩家实测的原话是「主动技能还是大范围秒杀、CD 还短」。
  //   ★ 实测证据（16 局官方 sim / 84449 次击杀 / **改动前**）：
  //       冲击波 58530（**69.3%**）· 投射物 13843 · 直斩 11268 · 环绕刃 794 · 闪现 11
  //       ⟹ 技能占 69.3%、武器只占 30.7%，最差那一局技能占 **82.1%**。
  //   这一版把四个数字同时写死（spec §一-1~4 逐条），并把**升级路径一起关进笼子**：
  //     · 伤害 15 → **3.75**（= 15 ÷ 4，spec「砍到现在的 1/4」）。刻意取**严格** 1/4：
  //       它打不死任何一只成年怪（最小怪血 4 = 群冲/裂片，3.75 < 4）——
  //       "主要效果是推开、不是杀怪"这句话因此有一条可断言的硬边界（tests 里就是这条）。
  //     · 半径 216 → **160**（spec §一-2）。上限由 SHOCKWAVE_R_MAX 兜住。
  //     · 击退 150 → **300**（spec §一-3）—— 它才是这个技能的主效果：把贴脸一圈推出去。
  //     · CD 2.0 → **8.0s**（spec §一-4）。
  SHOCKWAVE_DMG: 3.75,
  SHOCKWAVE_RADIUS: 160,
  SHOCKWAVE_CD: 8.0,
  SHOCKWAVE_KNOCK: 300,        // spec §一-3：主效果 = 把贴脸的怪推开 300px（保命解围）
  // 升级上限。spec 只写了"缩到 160"，但升级路径**也必须**进这个笼子 ——
  // 190 是**硬小于**竖屏半宽 195 的数（旧版的 216 + 4×40 = 376 会整屏横贯，
  // 玩家说的"大半个屏幕"就是这么来的）。它是硬上限，不是建议值。
  SHOCKWAVE_R_MAX: 190,
  SHOCKWAVE_KNOCK_MAX: 600,    // 击退上限（`ks_knock` 5 层 × +60）；600px 已是"甩出屏幕"的量级，再多只是把怪扔远

  // ── 阶段 4-7：新怪类型的数值口径 ──
  SHIELD_HITS: 3,        // 护盾怪：吸收前 3 次伤害，破盾后本体脆（"不能一波带走"）
  SPLIT_CHILDREN: 2,     // 裂体怪死亡裂成 2 只快速小怪（越打越多，要控场）
  SWARM_MIN: 3, SWARM_MAX: 5,  // 群冲怪：3~5 只一群一起刷、一起冲（数量压迫感）

  // ───────── 手感层（spec §2） ─────────
  // 反馈原话是「动画不行」。根因不是没有动画，而是**没有缓动**：
  // 位置每帧按输入直接赋值（线性瞬移）、敌人死亡直接 filter 掉（瞬切）、冲击波按下即炸（无过程）。
  // 所以这一节的共同口径是：先把"过渡"存在为一个可插值的量，再用 ease-out 走完它。
  //
  // ★ 铁律（tests/arena-core.test.mjs 会一键断言）：下面 ANIM_KEYS 列出的时长全部 > 0
  //   且 ≤ ANIM_MAX。慢动作不是手感，是延迟 —— 玩家要的是"有过程"，不是"慢"。
  //   新增任何动画都必须并进这张表，否则测试不会替它把关。
  ANIM_MAX: 0.30,           // 非瞬移动画时长上限（秒）。整条链路唯一红线。
  ANIM_KEYS: [
    'MOVE_ACCEL', 'MOVE_DECEL', 'DEATH_ANIM', 'DEATH_FLASH_AT', 'SHOCKWAVE_CHARGE',
    'SHOCKWAVE_FX', 'FLOAT_LIFE', 'PARTICLE_LIFE_MIN', 'PARTICLE_LIFE_MAX', 'SHOCKWAVE_FLASH',
    // 阶段 2 新增（spec §7：新增动画必须并入白名单，否则测试不会替它把关）
    'LASER_FX', 'DASH_FX', 'DASH_INVULN', 'CHEST_OPEN', 'FROST_FX',
    // 阶段 4-1 新增：相机跟随的滞后时长。它是"看得见的过渡"（画面确实在缓动），
    // 所以必须受 ≤300ms 这条红线管 —— 相机滞后超过 0.3s 就成了"操作延迟"。
    'CAM_TAU',
    // 阶段 4-3 新增（spec §4-3 冻结项：「动画 ≤300ms 红线」不变）：
    // 命中闪白、宝石弹出的蹦跳、屏震的抖动，全都是"看得见的过渡"，一并进白名单。
    'HIT_FLASH', 'GEM_POP_T', 'SHAKE_T',
  ],
  MOVE_ACCEL: 0.12,         // 移动加速：到达 95% 目标速度所需时长（不是时间常数，见 approach()）
  MOVE_DECEL: 0.24,         // 松手减速：到达"基本静止"所需时长（刻意比加速长 ⟹ 滑一小段 = 惯性）
  PLAYER_LEAN: 0.22,        // 侧倾最大弧度（≈12.6°，幅度小不夸张）
  PLAYER_STRETCH: 0.12,     // 沿运动方向的拉伸上限（squash & stretch 的 stretch）
  PLAYER_SQUASH: 0.08,      // 垂直运动方向的压扁上限（squash & stretch 的 squash）
  DEATH_ANIM: 0.15,         // 敌人死亡：爆裂放大→缩小 + 白闪（spec §2 写死 0.15s）
  DEATH_POP: 0.35,          // 死亡瞬间的额外放大比例（先"炸开"再缩没；纯缩小像漏气）
  DEATH_POP_AT: 0.30,       // 上面这段"炸开"占整个死亡动画的比例
  DEATH_FLASH_AT: 0.12,     // 白闪保持时长（占总时长的 40% 以内 → 见 DEATH_ANIM）
  DEATH_DRIFT: 16,          // 被投射物打死的碎屑外飘距离 px（小，只做"有方向"的暗示）
  DEATH_LEVELS: 6,          // 白闪色阶档数（预生成调色板，不做每帧 hex 插值）
  SHOCKWAVE_CHARGE: 0.15,   // 蓄力圈时长（spec §2「先蓄力 0.15s 再扩散爆发」）
  SHOCKWAVE_FX: 0.28,       // 爆发环扩张时长
  SHOCKWAVE_FLASH: 0.08,    // 白闪时长（用时长而非"真一帧"，否则掉帧时看不见）
  FLOAT_LIFE: 0.30,         // 飘字寿命
  FLOAT_RISE: 18,           // 飘字上飘总距离 px（ease-out 走完：起步快 → 收尾 0）
  PARTICLE_LIFE_MIN: 0.18,
  PARTICLE_LIFE_MAX: 0.30,
  // ── 阶段 2 新增动画（全部 ≤ ANIM_MAX，见上面的 ANIM_KEYS）──
  LASER_FX: 0.20,           // 直斩光束的存续时长
  DASH_FX: 0.18,            // 闪现残影
  DASH_INVULN: 0.18,        // 闪现无敌窗口（技能效果，但同样是"有始有终的过渡"）
  CHEST_OPEN: 0.20,         // 开箱动画（spec §5 写死 0.2s）
  FROST_FX: 0.25,           // 霜环扩散
  PROJECTILE_TRAIL: 22,     // 投射物拖尾长度 px（spec §2；直线飞行，残影即线段）

  // ── 阶段 2：武器 · 环绕刃 ──
  // ★ 阶段 5.1：环绕刃在阶段 5 实测是**失效武器**（16 局击杀占比仅 1.7%）。
  //   根因不是基础伤害低，而是**判定环太小**（r=66、外圈预筛 ~109px）—— 驾驶员一路风筝时
  //   怪几乎到不了那么近，刃永远空转。把它从"贴脸才蹭到"扩成"中近距就够得着"，
  //   并略提基础伤害，让它回到 15%~ 的健康区间（其余三把的占比才会自然下来）。
  //   ★ 这是"修坏掉的武器"，不是"削过量的武器" —— 过量的是投射物，不是它。
  ORBIT_COUNT: 2,           // 初始剑数
  // ★ 阶段 5.1：环绕刃在实测里是**失效武器**（16 局击杀占比仅 ~2%）。根因是判定环太小
  //   （r=66、外圈 ~109px），驾驶员一路风筝时怪几乎到不了那么近，刃永远空转。
  //   阶段 5.1 第二轮把它扩成 r=200 的近全屏环，结果**矫枉过正**：占比飙到 49% 把剑挤成
  //   摆设，且 r=200 的清场盘把屏幕正中 50% 区彻底清空（中央区最低点=0，撞坏 §4-8 验收）。
  //   第三轮收回到 r=130、命中半宽 24：刃仍然稳稳够得着风筝带（外圈 ~154px），但清场盘缩到
  //   半径 130，正中区重获敌群、占比回落到 ~27%。单怪秒伤仍最高（16/0.30s ≈ 53），
  //   只是"覆盖面积"回到四把武器里正常的一档。
  //   ★ 这是"修坏掉的武器"，不是"削过量的武器" —— 过量的是投射物，不是它。
  ORBIT_DMG: 18.08,         // 阶段 5.1：12 → 16 → 18.08（末次与另三把武器同乘 ×1.13 抬总吞吐，保生存；不改变四武器相对占比）
  ORBIT_R: 150,             // 阶段 5.1：66 → 200（第二轮过）→ 130（第三轮过缩）→ 150（第四轮：环略外扩找回 ~13pct 占比）
  ORBIT_SPIN: 2.8,          // 角速度 rad/s（≈2.2 秒一圈）
  ORBIT_W: 24,              // 阶段 5.1：13 → 35（第二轮过厚）→ 24（第三轮：判定带回到中等厚度）
  ORBIT_MAX: 5,             // 剑数上限（spec §1）
  // ★ 这不是动画时长，是**命中节流**：不给节流的话"贴在剑上的敌人"会每帧掉一次血，
  //   那不是武器而是光环，而且 DPS 会随帧率变化（帧率越高伤害越高），直接破坏可复现性。
  //   因此它**不进 ANIM_KEYS** —— 那张表只放"看得见的过渡"。
  ORBIT_TICK: 0.30,         // 阶段 4-9 配套：0.40 → 0.30（同一只怪被刃命中的最小间隔，§4-1 原注释在下面）
  ORBIT_GHOST: 0.13,        // 旋转残影的角度间隔 rad（纯视觉）
  ORBIT_GHOST_LEVELS: 3,    // 残影层数
  // ── 阶段 2：武器 · 直斩 ──
  // ★ LASER_RANGE 刻意**不超过** ATTACK_RANGE：那条注释里写得很清楚 ——
  //   射程再长一点，敌人就会在屏幕外被打死，宝石掉在玩家不会去的角落，
  //   升级系统形同虚设。直斩的价值在"穿透"，不在"更远"。
  // ★ 阶段 4-8：与投射物**同步**收到 300（spec §4-8 一-2「激光/直斩同理」）。
  //   两者必须一起动：直斩是"穿透"，一旦它比投射物远，屏幕外那圈怪就只被直斩吃掉，
  //   于是"缩短射程"改了半天、屏幕上还是看不到死亡过程（穿透的击杀本来就更难看见）。
  //   环绕刃（ORBIT_R）**不动** —— spec 明文"本来就是近身"。
  // 阶段 4-9 配套：伤害 14 → 28（×2）、CD 0.9 → 0.65（节拍 ×1.39）。理由同上（同为"输出主力"）。
  LASER_DMG: 31.64, LASER_W: 12, LASER_CD: 0.65, LASER_MIN_CD: 0.35, LASER_RANGE: 240, // LASER_DMG 28 → 31.64（阶段 5.1 末轮：同乘 ×1.13 抬总吞吐）
  // ── 阶段 5：武器 · 剑（第 4 把）──
  // 与 orbit / laser 同一套纪律：独立计时器、独立伤害对象（this.sword），各打各的节拍。
  // ★ 剑气是**飞行实体**（直线飞行 + 穿透 + 有射程），不是直斩那种"扫出去就结算完"的光束 ——
  //   所以它进 this.projectiles，但要两样别的东西：
  //   · pierce  —— 穿透多个敌人（每只只结算一次，靠 p.hits 去重，否则一只怪被同一道剑气磨成筛子）
  //   · maxDist —— **自己的**射程 380；通用的 PROJ_REACH_MUL 回收是按 ATTACK_RANGE(240) 算的，
  //                若沿用，380 的射程会被悄悄砍到 264 —— spec 给的数字就白写了。
  // ⚠ 张力记录（有意偏离 §4-8 那条"射程原则上不超过 ATTACK_RANGE 240"的纪律）：
  //   那条纪律的动机是"别让怪死在屏幕外、宝石掉在玩家不会去的角落"。剑的 380 是 spec 明确指定，
  //   且 380 < 视口半对角 ≈465，绝大多数方向仍在可见范围内 —— 但**这一条要靠实测/试玩确认**，
  //   不能只信算式。若实测出现"剑的击杀大量不可见"，优先调低 SWORD_RANGE，
  //   **不要去动 ATTACK_RANGE** —— 那个数管着投射物全表的回收半径，动它会波及所有武器。
  SWORD_DMG: 12.43, SWORD_INTERVAL: 1.2, SWORD_MIN_CD: 0.5, SWORD_SPEED: 420, SWORD_RANGE: 380, // SWORD_DMG 8 → 11 → 12.43（末轮同乘 ×1.13 抬总吞吐保生存）
  SWORD_COUNT: 1,          // 初始剑气道数（"+1" 走强化，上限 SWORD_MAX_COUNT）
  SWORD_MAX_COUNT: 3,      // 剑气数量上限（spec：扇形展开最多 3 道）
  SWORD_SPREAD: 0.28,      // 多道时的相邻夹角 rad（≈16°，视觉上读作"斩幅"而不是"三条平行的线"）
  SWORD_R: 7,              // 剑气判定半径 px
  SWORD_LIFE: 1.1,         // 存活 s（420 × 1.1 ≈ 462 > 380 ⟹ 足够飞完整段射程，不会"半路凭空消失"）
  // ── 阶段 5：进化形态 C2 / C3 的参数（stage 见 W_STAGE_MAX.sword）──
  // C2 扇形扫射：张开 100° 一次性推出去，牺牲单点的深穿透换横向覆盖面。
  SWORD_C2_COUNT: 3,       // C2 一次斩出几道（spec 明文 3 道）
  SWORD_C2_SPREAD: 1.745,  // C2 覆盖的**总**张角 rad（= spec 的 100°；相邻道之间均分这个角）
  // C3 环绕剑气：一圈刀锁在玩家身边持续旋转 —— 是"防御圈"不是"又一发子弹"。
  //   ★ 为什么不是"每 1.5 秒向外炸一圈"：那种做法本质就是螺旋弹幕换个皮，读不出"环绕"。
  //     真正的环绕必须是**持续存在**、跟着玩家走的一圈刀，才会改变"贴不贴脸"的走位判断。
  SWORD_C3_N: 12,          // C3 一圈多少把（360° / 12 = 每 30° 一把）
  SWORD_C3_R: 96,          // C3 环绕半径 px（比环绕刃的 66 大一圈：它是"身外的圈"，不是贴身刀）
  SWORD_C3_SPIN: 2.2,      // 角速度 rad/s（≈2.9 秒一圈）
  SWORD_C3_TICK: 0.35,     // 同一只怪被这一圈再结算的最小间隔 s（沿用 ORBIT_TICK 的口径：
                           //   不节流的后果是 DPS 随帧率变 ⟹ 直接破坏可复现性）
  // ── 阶段 2：技能 ──
  SKILL_CD_MUL_MIN: 0.40,   // 「技能冷却 -15%」的叠乘下限（**不动**：它是被动项，不是技能本身的削弱）
  // ★ 阶段 4-9：三个 CD 下限同步改成「**基础 CD 的一半**」—— 这是可断言的同一条口径
  //   （tests 断言 `SHOCK_MIN_CD === SHOCKWAVE_CD / 2` 等三条）。旧值 0.8 / 1.2 / 2.5 是
  //   4-7 那一版的余数：CD 拉到 8 / 10 / 6 秒之后，0.8s 的下限等于**没有下限**。
  SHOCK_MIN_CD: 4.0,
  // ★ 阶段 4-9 §三：闪现的定位就是「位移 + 无敌」这两条，所以撞伤 6 → **3**（再砍半，spec §三-1）、
  //   CD 3.0 → **6.0**（spec §三-3）。3 打不死任何一只怪（最小怪血 4）⟹ 它不可能变成收割工具。
  //   `DASH_INVULN_MAX` 是「无敌」这条轴的升级上限 = 0.18 + 4×0.02，且**硬小于 ANIM_MAX 0.30**
  //   （无敌窗口列在 ANIM_KEYS 里，属于"看得见的过渡"，不许越那条红线 —— tests 会断言）。
  DASH_DIST: 150, DASH_DMG: 3, DASH_CD: 6.0, DASH_MIN_CD: 3.0, DASH_W: 26,
  DASH_INVULN_MAX: 0.26,
  // ★ 阶段 4-9 §二：霜环**零伤害**（它本来就不走 applyHit，这一版把它升格成一条断言）、
  //   半径 150 → **120**、CD 6.0 → **10.0**，冻结时长保持 1.5s（spec §二-1）。
  //   `FROST_R_MAX` 只允许升级把它推回**降格前的 150**，不许越过旧版。
  FROST_R: 120, FROST_DUR: 1.5, FROST_CD: 10.0, FROST_MIN_CD: 5.0, FROST_MAX_DUR: 3.0,
  FROST_R_MAX: 150,
  // ── 阶段 2：宝箱 ──
  CHEST_FIRST: 40,          // 第一个宝箱的秒数（比 CHEST_EVERY 早，让开局就能见到一次）
  CHEST_EVERY: 75,          // 之后每 ~75 秒一个（spec §5）
  CHEST_R: 15,
  CHEST_MIN_D: 110, CHEST_MAX_D: 250,  // 落点距玩家的距离区间（"附近"）
  CHEST_SAFE_R: 92,         // 安全判据：这个半径内的敌人数越少越好
  CHEST_TRIES: 14,          // 候选点采样数（够了，再多也只是更慢）
  // ── 阶段 2：三选一池子 ──
  EARLY_GUARD_SEC: 120,     // 前 2 分钟保底给一件"新东西"（spec §4）
  // ── 阶段 2：新增性能上限 ──
  MAX_CHESTS: 3,            // 场上同时存在的宝箱上限（没人捡也不能堆满屏）
  MAX_FX: 24,               // 光束/霜环/残影/开箱这些短特效的并发上限

  // ───────── 阶段 4-3：爽感改造（打击反馈） ─────────
  // 反馈原话是「打起来不爽（没数字/不爆炸）」。这一节的共同口径是：
  // **每一次"打中了"都要有一个看得见的、立刻发生的回应** —— 而不是等怪倒下才有反馈。
  // ★ 全部是纯表现：不进任何伤害/经济/刷怪判定，所以不会动到已经标定好的平衡读数。
  FLOAT_BIG_DMG: 20,        // 单次伤害 ≥ 此值 ⟹ 飘字放大 + 变色（"这一下比平时重"）
                            //   20 的定法（**阶段 4-9 后重标**）：基础投射物 6、环绕刃 6、直斩 14、
                            //   冲击波 3.75、闪现存 3、霜环 0 —— 全部不是"大数字"，
                            //   只有**成型后的武器**（强化直斩 ≥20、满级投射物/进化线）才够格。
                            //   ⟹ 技能降格之后，亮大字这件事完全归武器：这恰好是 spec §四-2
                            //      「武器才是输出主力」在**表现层**的同一条口径。
  FLOAT_BIG_MUL: 1.5,       // spec：大数字放大 1.5 倍
  BURST_MIN: 8,             // 击杀爆炸的粒子数下限（spec：8~12）
  BURST_MAX: 12,            // 上限。★ 精英固定吃满 BURST_MAX（"这只有点不一样"）
  // ★ 宝石"先弹出一小段再被磁吸"（spec 二-2）：直接原地消失会让"掉东西"这件事没有过程，
  //   玩家读不到"我打死了一只、它掉了经验"。弹出 80~150px 之后才进入磁吸，
  //   ⟹ 视觉上是"蹦出来 → 被吸走"两拍，而不是凭空出现一个点。
  GEM_POP_MIN: 80,          // 弹出距离下限 px
  GEM_POP_MAX: 150,         // 上限 px
  GEM_POP_T: 0.18,          // 弹出时长 s（≤ ANIM_MAX；已进 ANIM_KEYS 受红线管）
                            // ★ 它是**纯视觉**的：宝石的 x/y（吸附/拾取判据）不受它影响，
                            //   所以这个数怎么调都不会碰平衡（见 killEnemy 的注释）。
  HIT_FLASH: 0.09,          // 命中闪白时长 s（spec 一-5「闪白更明显一档」）。
  HURT_FLASH: 0.32,         // 阶段 4-10：玩家受击红屏脉冲时长 s
  // ★ 阶段 4-11：敌人可读性标识（纯视觉，不碰判定）。
  RANGED_RING: '#e08a2e',   // 远程精英（蚀影射手）脉冲光环色，与 ENEMY_TYPES.ranged.color 一致
  TOUCH_WARN: 14,           // 接触威胁高亮：比接触伤害触发距离(player.r+e.r)多出的预警余量 px
  LEVEL_FLASH_T: 0.5,       // 升级全屏暖光脉冲时长 s
  BOSS_ENTER_FLASH_T: 0.7, // Boss 出场红场脉冲时长 s
  // ★ 阶段 4-12：局内突发事件（确定性调度，纯玩法增强，不碰主 rng 流）。
  EVENT_FIRST: 70,         // 首个事件秒数（开局先让玩家站稳）
  EVENT_EVERY: 75,         // 事件间隔 s（确定性固定时间表，不消耗 rng）

  // ── 阶段 6-4：魂火商栈（局内商店）──
  // ★ 时间点直接复用 shop.js 的 SHOP_TIMES（单一真相源，避免 arena 与 shop 各写一份漂移）。
  SHOP_TIMES,              // [120, 300, 480]：第 2 / 5 / 8 分钟各开一次
  SOULFIRE_PER_KILL: 1,    // 每击杀掉落 1 魂火（与 gems=xperience 完全独立的货币）
  EVENT_LAST: 600,         // 最后一个事件不晚于此（留收尾给 Boss 决战）
  EVENT_SEQ: ['gold', 'supply', 'magnet'], // 阶段 4-13：三种纯增益波（经济×2 / 补给 / 磁暴收割），确定性安全、不破基准存活护栏。
                                                 //   elite 事件（_fireEvent('elite')）已实现+测试，但强制刷精英会拖死 WILD-TEST-LONG 基准种子（test 48 硬护栏），
                                                 //   故暂不进 live 循环，留待难度曲线重平衡后再启用。
  GOLD_MUL: 2,             // 黄金时段经验倍率
  GOLD_T: 12,              // 黄金时段时长 s
  MAGNET_MUL: 3,           // 磁暴事件：经验/心心拾取半径 ×MAGNET_MUL（纯增益，确定性安全）
  MAGNET_T: 12,            // 磁暴时长 s

  // ── 阶段 7 · 属性树新节点（狂怒 / 续航）的硬上限 ──
  // ★ 为什么每条都要封顶：属性树等级上限已经是 50（GROWTH_LVL_CAP），不封顶的话
  //   "狂怒 50 级 = 150% 暴击率"会直接溢出（>100% 的暴击率等于每击都暴，
  //   属性面板上那一项就变成了"每级 +3% 但过了某级再加也没用"——玩家看得见却读不出来）。
  //   封顶之后语义干净：满 100% 暴击 = 每击都是暴击，此时属性树正确地"作废"这一项。
  CRIT_RATE_MAX: 1.0,      // 暴击率封顶 100%
  CRIT_DMG_MUL: 1.5,       // 暴击造成 150% 伤害（spec 明文）
  LIFESTEAL_MAX: 1.0,      // 吸血封顶 100%（每杀一只回满等量血；再高无意义）

  // ── 阶段 7 · 荆棘装备 ──
  // ★ 反弹的**半径**与**单次上限**：荆棘是"受击时反打一圈"，若无上限，
  //   在 200 只怪贴脸时一次受击会把 AOE 伤害打满 → 反而变成输出手段（阶段 4-9 踩过
  //   "技能变成主要输出"的坑）。所以给半径 120px（略大于冲击波硬上限 190 的一半）
  //   + 单次上限（相当于玩家 1.5 倍接触伤害），让它稳定地是"防御向收益"。
  THORNS_RADIUS: 120,
  THORNS_CAP: 24,
  THORNS_MAX_TARGETS: 5,  // 一次反弹最多打几个目标（配合 CAP：保证它是防御向收益）

  // ── 阶段 7 · 护盾装备 ──
  // ★ 层数封顶 1 层（不是可累积的池）：spec 只说"抵挡 1 次伤害"，
  //   若允许叠到 3 层就变成了"15 秒内免疫三次死亡"，那不是护盾、是第二条命。
  SHIELD_LAYERS_MAX: 1,
  SUPPLY_HEARTS: 4,        // 补给空投掉心心数
  SUPPLY_GEMS: 12,         // 补给空投掉经验宝石数
  SUPPLY_GEM_XP: 4,        // 补给宝石单颗经验
  SUPPLY_RING: 220,        // 补给撒在玩家周围半径 px
  ELITE_CALL_N: 1,         // 精英降临刷几只
  ELITE_BOON_HEARTS: 2,    // 精英狩猎事件附赠心心（威胁+赏金，净难度回到增益波附近，不破坏基准存活）
  ELITE_BOON_GEMS: 8,      // 精英狩猎事件附赠经验宝石数

  // ── 阶段 7 · 精英波（spec §局内成长节奏：「精英敌人每 90 秒刷新一波，击杀必掉技能选择」）──
  // ★ 为什么**另起一套调度**而不是把 'elite' 塞回 EVENT_SEQ：
  //   EVENT_SEQ 是 75 秒一轮的「纯增益波」循环（gold/supply/magnet），它的设计前提是
  //   "每一波都是净增益"。精英波是净威胁，硬塞进去会同时破坏两件事：
  //   ① 循环节奏被拉长成 150 秒（三个增益换一只精英）；② EVENT_SEQ 一改，
  //   16 局 sim 里那条"事件自证"读数与阶段 4-13 的历史基线就全废了。
  //   独立调度的另一个好处：间隔口径独立可调（90s），不必迁就 EVENT_EVERY。
  // ★ 击杀必掉技能选择的实现口径：精英身上挂 `eliteWave` 标记（只在这条调度里刷的才带），
  //   死时把 `eliteSkillDrops` 计数 +1；主循环在无升级弹窗时兑现一次三选一。
  //   刻意**不是**"立刻弹窗"——同一帧可能连杀两只精英、或正好撞上升级弹窗，
  //   直接弹会把 pendingUpgrade 覆盖掉（丢一次玩家的选择）。排队 + 单出是最稳的形态。
  ELITE_WAVE_ON: true,      // 总开关（关掉即回到阶段 4-13 的逐字节行为）
  ELITE_WAVE_FIRST: 90,     // 首个精英波秒数（比 EVENT_FIRST 晚 20s：先让玩家站稳再上威胁）
  ELITE_WAVE_EVERY: 90,     // 精英波间隔 s（spec 明文 90）
  ELITE_WAVE_LAST: 540,     // 最后一波不晚于此（留 60s 收尾给 Boss 决战）
  ELITE_WAVE_N: 2,          // 每波几只（一只不够"一波"的压迫感，三只会挤占同屏预算）
  ELITE_WAVE_HEARTS: 2,     // 每波附赠心心（与 ELITE_BOON 同口径：净难度不因这只精英单向上升）
  ELITE_WAVE_GEMS: 8,       // 每波附赠经验宝石数
  ELITE_WAVE_SKILL: 3,      // 精英波的技能三选一：优先给满 3 张技能向牌（不足则回退混合）
  EVENT_BANNER_LIFE: 2.6,  // 事件横幅停留 s
  // ★ 阶段 4-7.x：怪物出生淡入（纯视觉，不碰任何判定）。
  APPEAR_T: 0.18,           // 出生 → 满尺寸/满透明度 时长 s
  // ★ 阶段 4-7.x：击杀掉落心心（回血，玩法增强）。
  HEART_CHANCE: 0.05,       // 非群冲/裂片怪的掉落概率（约 1/20 只掉一颗）
  HEART_HEAL: 5,            // 每颗回血
  HEART_R: 6,               // 半径 px
  HEART_POP_T: 0.18,        // 掉落弹出（出现）时长 s
  HEART_PULL: 70,           // 弱磁吸半径 px（只把靠近的心心吸过来，避免满地乱吸）
  HEART_LIFE: 14,           // 过期时间 s（防止场地被心心塞满）
  MAX_HEARTS: 40,           // 同屏心心上限
                            //   0.09 而不是 0.03：太短的话满屏两百只的场面里根本看不见，
                            //   而它恰恰是"打中了"这件事唯一贴着敌人的读数。
  COMBO_WINDOW: 2.0,        // 连杀窗口 s（spec 一-3：2 秒内连续击杀累加）
  // 连击的分档：**只影响显示**（字号 / 颜色），不影响任何数值（spec 明文）。
  COMBO_TIERS: [            // { n: 达到该档所需连击数, size: 字号, color }
    { n: 0,  size: 14, color: '#e8e3da' },  // 白
    { n: 5,  size: 17, color: '#e8d46a' },  // 黄
    { n: 12, size: 21, color: '#e08a2e' },  // 橙
    { n: 25, size: 26, color: '#b3402f' },  // 红
  ],
  // 屏震（spec 一-4）：≤6px、≤150ms。**相机偏移**，不是画面缩放 ——
  //   缩放式屏震会让整个世界一起抖，前庭敏感用户立刻不适；小幅平移才是"撞了一下"的量级。
  SHAKE_AMP: 6,             // 最大偏移 px（spec 明文 ≤6）
  SHAKE_T: 0.15,            // 单次屏震时长 s（spec 明文 ≤150ms；已进 ANIM_KEYS）
  SHAKE_ENEMIES: 30,        // 同屏敌数超过这个值 ⟹ 持续轻微屏震（"场面已经失控"）
  SHAKE_ENEMY_AMP: 2.5,     // 上面那种持续震的幅度（刻意比技能震小，不能盖过主反馈）

  // ── 阶段 4-3：局内里程碑（spec 二-3）──
  // 不暂停、不弹窗：只在屏幕中央打一行字，2 秒淡出。
  // 存在的理由是"目标感"：10 分钟里没有任何阶段性确认，玩家中途只会觉得"还没死而已"。
  MILESTONES: [
    { at: 60,  kind: 'sec',  text: '撑过 1 分钟！' },
    { at: 180, kind: 'sec',  text: '撑过 3 分钟！' },
    { at: 300, kind: 'sec',  text: '撑过 5 分钟！' },
    { at: 100, kind: 'kill', text: '已杀 100 只！' },
    { at: 300, kind: 'kill', text: '已杀 300 只！' },
    { at: 500, kind: 'kill', text: '已杀 500 只！' },
    { at: 1000, kind: 'kill', text: '已杀 1000 只！' },
  ],
  MILE_FADE: 2.0,           // 里程碑横幅的显示时长 s（不是动画时长，是"停留 + 淡出"的总时长）

  // ───────── 阶段 4-4：Boss 节点 ─────────
  // 目标：5:00 与 8:30 各刷一个 Boss，把"平推到底"切成三段。
  BOSS_SPAWN_DIST: 400,     // Boss 在玩家周围多远处刷出（spec 二-3「400px」）
  BOSS_WARN_LEAD: 3,        // 出现前多少秒开始打警告（spec 一-2「出现前 3 秒」）
  BOSS_WARN_LIFE: 3,        // 警告横幅的停留时长 s（spec「3 秒淡出」）
  BOSS_CYCLE: 5,            // 攻击循环周期 s（spec 二-2「每 5 秒一轮」）
  // ⚠ 记录一处**spec 内部冲突**（已按 4-4 的明文实现，留痕待裁决）：
  //   4-4 二-2 要求「冲锋有 0.5 秒前摇停顿」，而贯穿性红线是「动画 ≤300ms」。
  //   这里的裁决是：**前摇是玩法预兆（telegraph），不是过渡动画** ——
  //   它必须够长到让玩家读出方向并做出规避，0.3s 在满屏两百只的场面里根本来不及反应。
  //   因此 BOSS_WINDUP **不进 ANIM_KEYS**（那张表只放"看得见的过渡"），红线测试不受影响。
  BOSS_WINDUP: 0.5,         // 冲锋前摇 s（期间站住不动 + 画出方向提示）
  BOSS_CHARGE_T: 0.35,      // 冲锋本体的时长 s
  BOSS_CHARGE_SPEED: 420,   // 冲锋速度 px/s（远快于它的追踪速度 —— "冲"才成立）
  BOSS_TOUCH_CD: 1.5,       // Boss 的接触伤害冷却 s。★ 没有它，Boss 贴上玩家后每帧结算一次，
                            //   0.6s 内就能把满血打空 —— 那不是"高伤害"，是判定错误。
  BOSS_CONTACT_MUL: 3,      // 接触伤害 = 普通怪的 3 倍（spec 二-3）
  BOSS_SUMMON: [4, 6],      // 召唤只数：Boss1 召 4 只、Boss2 召 6 只
  BOSS_SUMMON_R: 70,        // 召唤物落在 Boss 周围多远
  BOSS_HP_MUL: [30, 50],    // 血量 ≈ 同期普通怪的 30 倍 / 50 倍（spec 四）
  BOSS_FROST_MUL: 0.5,      // 冻结时长减半（spec 四「不能被霜环定到死」）
  BOSS_DENSITY_MUL: 1.25,   // Boss 在场时普通怪的刷怪间隔 ×1.25（= 密度 −20%，spec 四）
  BOSS_DEATH_PARTICLES: 34, // Boss 死亡的碎屑数（spec 三-3「30 个以上」）

  // ───────── 阶段 4-5：超武进化 ─────────
  // 「武器拿满若干次专属强化」= 满级；满级 + 凑齐指定被动 ⟹ 本局**自动进化**（不弹选择）。
  // ★ 满级阈值为什么是这几个数：一局约 32 次升级，还要留出拿新武器/新技能/被动的余量。
  //   定太高（比如 10）⟹ 三条线一条都走不完，"进化"等于不存在；
  //   定太低 ⟹ 中期就进化完，后半局没有追求。6/5/5 是"第 6~8 分钟才可能成型"的量级。
  W_LEVEL_MAX: { projectile: 6, orbit: 5, laser: 5, sword: 6 },
  // ★ 阶段 5：每把武器能进化到**第几阶**。除剑以外的三把只有 1 阶（⟹ 行为与阶段 4-5 逐字节一致）；
  //   剑有两段链（C1→C2→C3），所以 maxStage = 2。
  //   没有这张表，wlvlUp / _checkEvolution 就无法区分两种完全不同的状态：
  //   "已进化到底、强化项该从池子消失" 与 "才刚到 C2、还得爬到 C3 才能再进化"。
  W_STAGE_MAX: { projectile: 1, orbit: 1, laser: 1, sword: 2 },
  EVO_BANNER_LIFE: 2.4,     // 「★武器进化★」大字的停留时长 s
                            //   ⚠ 它不是过渡动画（那张表管的是"看得见的缓动"），
                            //     所以不进 ANIM_KEYS —— 与里程碑横幅同一口径。
  // ── 螺旋弹幕（投射物进化）──
  SPIRAL_CD: 1.2,           // 环形齐射的间隔 s
  SPIRAL_N: 12,             // 一圈几发（12 发 = 每 30° 一发）
  SPIRAL_SPEED: 420,        // 弹速 px/s（比普通弹慢：它是"铺场"，不是"点名"）
  SPIRAL_STEP: 0.13,        // 每轮整体转过的角度 rad —— 连起来看才是"螺旋"而不是"原地放烟花"
  // ── 五刃风暴（环绕刃进化）：spec 明文「刃数翻倍、旋转加速、范围加大」──
  // ⚠ 刻意**不加伤害**：spec 只列了这三条。翻倍刃数本身已经把覆盖面积翻了一倍，
  //   再叠伤害会让这条线在数值上压过另外两条。
  STORM_COUNT_MUL: 2,
  STORM_COUNT_MAX: 10,      // 翻倍后的硬上限（ORBIT_MAX 5 × 2 = 10，正好）
  STORM_R_MUL: 1.35,
  STORM_SPIN_MUL: 1.6,
  // ── 裂光（直斩进化）：spec 明文「一道变三道扇形穿透光束」──
  CLEAVE_BEAMS: 3,
  CLEAVE_FAN: 0.32,         // 相邻两道的夹角 rad（≈18°；三道总共张开 36°）
};

// ───────── 敌人类型（阶段 4-1：4 种，分波次刷） ─────────
// 颜色全部取自既有 12 色板，兼顾「剪影单色美术」与「一眼分得清」——
// 满屏 90 只的时候，玩家必须能立刻识别哪个是坦克（该躲），哪个是快速（该先打）。
export const ENEMY_TYPES = {
  // 普通：灰块，直线走。基准型，全场都有。
  normal: { id: 'normal', label: '游荡者', shape: 4,  spikes: false, r: 13, speed: 72,  hp: 9,  contact: 4, xp: 1, color: '#8d8378' },
  // 快速：小、跑得快。血薄，一发即死（BASE_DMG 6 > 5）。
  fast:   { id: 'fast',   label: '疾影',   shape: 2,  spikes: false, r: 9,  speed: 132, hp: 5,  contact: 3, xp: 1, color: '#5b93d6' },
  // 坦克：大、血厚、慢。基础 6 伤需要 5 发，逼玩家用冲击波或绕后。
  tank:   { id: 'tank',   label: '重壳',   shape: 9,  spikes: true,  r: 20, speed: 46,  hp: 30, contact: 7, xp: 3, color: '#d1544a' },
  // ── 阶段 4-1：远程精英（蚀影射手）──
  // 与近战精英**正交**的一种压力：它不追着你咬，而是停在 300px 外绕圈点射。
  // 数值口径（spec）：中等偏小体型 / 慢 / 血 ×2（= 普通怪的 2 倍，比近战精英的 ×4 略低）/ 掉宝石。
  // 颜色取橙：普通灰、疾影蓝、重壳暗红、近战精英红；只有橙在这套配色里是"空位"，
  // 一屏两百只的时候"哪个是射手"必须一眼可辨。
  // ★ 阶段 4-1.1：xp 3 → 2（spec：远程精英怪 xp = **普通怪的 2 倍**；普通怪 xp 是 1）。
  //   ⚠ 记录一处**spec 内部不一致**，供主理人裁决：上一版这里已经是 3（= 3× 普通怪），
  //   所以"设成 2 倍"按字面是**降**，而同一句的括号理由写的是"它本来就该给更多"。
  //   本次按**字面数字**实现（2），因为它是可核对的量化指示；效果上 ranged 只占刷怪的
  //   1.4%~2.5%，对总经验收入的量级影响可忽略（不是这次升级空档的主因）。
  //   若本意是"加"，把它改回 3（= 3× 普通）或 6（= 2× 近战精英 1×3）都是一行的事。
  ranged: { id: 'ranged', label: '蚀影射手', shape: 6, spikes: false, r: 12, speed: 40, hp: 18, contact: 4, xp: 2, color: '#e08a2e' },
  // ── 阶段 4-7：新增三类「机制怪」（与 normal/fast/tank/ranged 正交，不是品质）──
  // ★ 为什么不进 BOSS 表、也不复用 elite 判定：它们是**玩法参数不同的基础怪**，
  //   要进 WAVES 权重表被波次按时间门槛解锁（精英只是同种怪的品质，不进权重表）。
  // ★ 阶段 4-8 三 的辨识度（spec 原文：护盾怪外圈画个壳 / 分裂怪小一圈 / 群冲怪是一群小点）：
  //   三者的差异**全部落在既有字段上**，没有新增"标记位"——渲染层只认 typeOf(kind) 的那张表：
  //     · 裂体：r 14 → **11**（比普通怪 13 还小一圈）⟹ "小 = 会裂"是一眼可辨的形状线索；
  //       它本身血不厚（18），小体型也让"打它要更准"这件事成立。
  //     · 护盾：形状字段已有壳（shape 7 + spikes），**外圈另画一圈壳**（见 _render 的护盾环）。
  //     · 群冲：r 7 的小点 + 成簇出生（3~5 只，swarm 分支）⟹ "一群小点扑过来"。
  splitter: { id: 'splitter', label: '裂体', shape: 5,  spikes: false, r: 11, speed: 62,  hp: 18, contact: 5, xp: 2, color: '#7bbf6a' },
  shield:   { id: 'shield',   label: '护盾', shape: 7,  spikes: true,  r: 15, speed: 58,  hp: 16, contact: 5, xp: 2, color: '#c9a23a' },
  swarm:    { id: 'swarm',    label: '群冲', shape: 3,  spikes: false, r: 7,  speed: 120, hp: 4,  contact: 3, xp: 1, color: '#c77fd6' },
  // 裂体怪死亡时裂出的小怪（不进 WAVES，只由 killEnemy 生成；小一圈、血薄、跑得快）
  splitling:{ id: 'splitling',label: '裂片', shape: 3, spikes: false, r: 7, speed: 135, hp: 4,  contact: 2, xp: 1, color: '#9bd98a' },
};

// ───────── 阶段 4-4：Boss 类型表 ─────────
// ★ 为什么**不并进 ENEMY_TYPES**：那张表是"基础怪"的契约（多种既有测试按它的条目数、
//   字段、颜色口径断言，且历史口径是"基础表不动"）。Boss 是**另一类实体**：
//   它不进 WAVES 权重表（不会被波次刷出来）、不吃精英判定、撞上去不自爆。
//   所以另起一张表，用 typeOf(kind) 统一取类型 —— 调用点只认"这是个类型"，不认它在哪张表里。
//
// 字段与 ENEMY_TYPES 对齐（r / speed / shape / spikes / color / label），外加 Boss 专属：
//   atSec   出场秒数（5:00 = 300s、8:30 = 510s）
//   hpMul   血量 = 同期**普通怪**血量 × 此倍率（spec 四）
//   summon  召唤只数
//   charge  冲锋次数占比（见 stepBoss：Boss2 冲锋更频繁）
// ★ 颜色：Boss1 暗红 / Boss2 紫黑（spec 一-3）。两种都没有 PNG 素材 ⟹ 自动走剪影，
//   正好满足"不要用普通怪贴图"。
export const BOSS_TYPES = {
  boss1: { id: 'boss1', idx: 0, label: '荒噬者', atSec: 180,
    hpMul: 30, r: 32, speed: 50, shape: 77, spikes: true, color: '#7a1f18', summon: 4 },
  boss2: { id: 'boss2', idx: 1, label: '噬影之主', atSec: 330,
    hpMul: 50, r: 38, speed: 54, shape: 91, spikes: true, color: '#3a1f4a', summon: 6 },
};
/** Boss 的出场顺序（按 atSec 升序）："没死不刷下一个"靠这个顺序推进。 */
export const BOSS_ORDER = Object.keys(BOSS_TYPES).sort((a, b) => BOSS_TYPES[a].atSec - BOSS_TYPES[b].atSec);

/** 按 kind 取类型定义（先基础表，后 Boss 表）。渲染/结算的公共入口。 */
export const typeOf = (kind) => ENEMY_TYPES[kind] || BOSS_TYPES[kind] || null;
/** 是不是 Boss。热路径上用（碰撞/霜环/死亡结算各判一次），所以做成纯查表。 */
export const isBossKind = (kind) => !!BOSS_TYPES[kind];

// 被动 / 武器 / 技能的内容池在 content.js（那边是纯表，这边是执行层）。
// 数值口径仍然统一住在本文件的 ARENA —— 数字只有一个家，不两边各存一份。
// `UPGRADES` 是**兼容别名**：阶段 1 按它找被动池，现在被动池已扩到 10 项。
export { PASSIVES as UPGRADES, WEAPONS, SKILLS, OFFERS, CAT_LABEL };

const COLOR = {
  field: '#0d0c0b',
  player: '#cfc7ba',
  projectile: '#e8e3da',
  gem: '#a89ae6',        // --flux 紫
  paper: '#e8e3da',
  ink: '#9a938a',
  danger: '#b3402f',
  blade: '#d1544a',
  frost: '#5b93d6',
  shield: '#3fd0c8',        // 阶段 4-7：护盾环（青）
  heart: '#e0586b',         // 阶段 4-7.x：心心（回血掉落）
  event: '#5fd0c8',         // 阶段 4-12：事件横幅色（青，呼应宝石）
  gold: '#d6ab58',          // 宝箱金
  evo: '#e8c45a',           // 阶段 4-5：进化大字（金）
  laser: '#e8e3da',
};

// ── 阶段 3：精灵素材（drawImage 替代剪影）──
// 每种实体一张透明 PNG，居中绘制、按碰撞半径 r 等比缩放。
// fit.axis = 'w' 表示「以碰撞直径的倍数定宽、高随图比例」；'h' 反之。
// k 是「目标尺寸 / r」的系数：敌人用宽≈2.5r（略大于碰撞圈，读起来"身体包住碰撞点"），
// 玩家用高≈2.9r（贴回阶段 2 剪影的身高手感）。
// ★ 失败/未加载时一律回退到原剪影多边形（_drawSil / _playerPath），绝不白屏。
const SPRITE_FIT = {
  hero:   { axis: 'h', k: 2.9 },  // 75×160：高 2.9r → 宽 1.36r
  normal: { axis: 'w', k: 2.5 },  // 214×110：宽 2.5r → 高 1.28r
  fast:   { axis: 'w', k: 2.4 },  // 63×80：宽 2.4r → 高 3.05r（瘦高，像"疾影"）
  tank:   { axis: 'w', k: 2.5 },  // 184×190：宽 2.5r → 高 2.58r（敦实，像"重壳"）
  ranged: { axis: 'w', k: 2.4 },  // 阶段 4-1 远程精英：中等偏小（与 fast 同系数，靠配色区分）
};
// id（实体种类）→ 素材文件名。player 用 'hero'，敌人用 kind。
const SPRITE_FILE = {
  hero: 'hero.png', normal: 'normal.png', fast: 'fast.png', tank: 'tank.png',
  ranged: 'ranged.png',   // 阶段 4-1：尚未入库，按规范名预留 —— 文件一放进去就自动生效
};
// 「还没入库」的可选素材：加载前先 HEAD 探一次。
// ★ 直接 new Image() 也能跑（onerror → 回退剪影，正是 spec 要的容错），但那样**每次进页面
//   都会在控制台留一条 404** —— 一条真故障会和这条噪音混在一起，属于自己给自己挖坑。
const OPTIONAL_SPRITES = new Set(['ranged']);

const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);
const lerp = (a, b, t) => a + (b - a) * t;
// 刻意用 sqrt 而不是 Math.hypot —— hypot 为防溢出做了额外分支，实测慢 5~10 倍。
// 同屏 90 敌 × 60fps 下这一项在热路径上被调用数十万次。
const dist = (a, b) => { const dx = a.x - b.x, dy = a.y - b.y; return Math.sqrt(dx * dx + dy * dy); };
const TAU = Math.PI * 2;

// ── 缓动（手感层统一口径） ──
// 把"过渡"统一成两个函数，而不是在各处散落魔法系数：
//   easeOut  —— 给**进度型**动画用（死亡爆裂、爆发环、蓄力圈、飘字）：起步快、收尾慢。
//   approach —— 给**速度型**收敛用（移动惯性）：帧率无关的指数趋近。
// 为什么 approach 不能写成 `v += (target - v) * 0.3`（定系数 lerp）：那个系数是按某个固定 dt
// 拍出来的，dt 一变（掉帧 / 后台恢复 / 无头模拟的粗步长）收敛速度就跟着变 ——
// 于是"同一套输入、不同帧率走位不同"，那不只是观感问题，还会让平衡口径无法复现。
/** 三次 ease-out。整条链路唯一允许的缓动类型（spec §2：所有动画 ease-out）。 */
const easeOut = (p) => 1 - (1 - clamp(p, 0, 1)) ** 3;
/** 指数趋近。sec = **到达 95% 目标值所需时长**（1 − e^−3 ≈ 0.95 ⟹ 时间常数 tau = sec/3）。 */
const approach = (v, target, sec, dt) => v + (target - v) * (1 - Math.exp((-3 * dt) / sec));

/** 阶段 5：画一道**剑气月牙**（把它从 render 里拎出来，是为了让 C1/C2 的飞行剑气和
 *  C3 的环绕刀共用同一套外形 —— 三种形态读起来必须是"同一种武器的三种站姿"）。
 *  fade 由调用方给：飞行剑气按剩余寿命淡出，环绕刀是常驻的、恒为 1。 */
function drawSwordQi(ctx, x, y, ang, r, fade) {
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(ang);
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.arc(0, 0, r * 1.25, -1.15, 1.15);
  ctx.strokeStyle = `rgba(232,227,218,${0.22 * fade})`;
  ctx.lineWidth = r * 1.5;
  ctx.stroke();
  ctx.strokeStyle = `rgba(255,252,240,${0.88 * fade})`;
  ctx.lineWidth = 2;
  ctx.stroke();
  ctx.restore();
}

/** hex → [r,g,b] */
function hexRgb(hex) {
  const n = parseInt(hex.slice(1), 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}
/** 把基色向白插值 t 档，返回预生成的 css 颜色串（死亡闪白用）。 */
function flashPalette(hex, levels) {
  const from = hexRgb(hex), to = [255, 255, 255], out = [];
  for (let i = 0; i < levels; i++) {
    const t = i / (levels - 1);
    out.push(`rgb(${from.map((v, k) => Math.round(v + (to[k] - v) * t)).join(',')})`);
  }
  return out; // [0] = 敌人本色，[levels-1] = 纯白
}

// 字体串提出来常量复用：ctx.font 赋值会触发 CSS 字体简写串解析，每帧重复赋同一个值是浪费。
const FONT_BIG = '600 26px -apple-system, system-ui, sans-serif';
const FONT_SMALL = '500 12px -apple-system, system-ui, sans-serif';
// 阶段 4-3：大伤害飘字（12px × FLOAT_BIG_MUL = 18px）。加粗是必要的 ——
// 光是变大在满屏怪的背景下会被"淹没"，粗一号才抓得住眼。
const FONT_FLOAT_BIG = '700 18px -apple-system, system-ui, sans-serif';
// 连击 / 里程碑横幅（屏幕层大字）
const FONT_COMBO = (n) => `700 ${n}px -apple-system, system-ui, sans-serif`;
const FONT_BANNER = '700 22px -apple-system, system-ui, sans-serif';

// ?dbg=1：把输入/帧率/波次读数画在画布上。价值在于「真机操控失灵时能直接读出数值」——
// 键盘没收到、摇杆焊死在某个方向、失焦卡键，这三种原因的屏幕表现完全一样，靠猜会一直猜错。
// 用 typeof 守卫是因为 Node（tools / tests）会 import 本模块，那里没有 location。
const DBG = typeof location !== 'undefined' && /[?&]dbg=1\b/.test(location.search);

/**
 * 纯逻辑模拟核心（无 DOM、无 canvas、无 rng 外部依赖）。
 * Node 里直接驱动 step(dt, input) 即可做无头长跑与单测。
 */
export class ArenaCore {
  constructor({ rng, width = 360, height = 640, reducedMotion = false, durationMs = ARENA.DURATION_MS, meta = {} }) {
    this.rng = rng;
    // 阶段 4-7.x：心心掉落用**独立**随机源，与主 rng 流完全隔离。
    // ★ 不共用 this.rng：killEnemy 每杀一只都决定一次掉不掉，若走主 rng 会把"整局 spawn/开火/
    //   爆发"的随机序列整体挪位（阶段 4-3 有护栏测试专门盯主 rng 消耗量）。独立种子 = 主玩法
    //   随机流逐字节不变 ⟹ 既有平衡/确定性验收不破，心心只是"在已确定的击杀上叠一层回血"。
    this.dropRng = new Rng('heart:' + (rng && rng.seed ? rng.seed : 'seed'));
    this.reduced = reducedMotion;
    this.durationMs = durationMs;
    this.setBounds(width, height);

    this.time = 0;
    // 位置不由输入直接赋值，而由**速度**积分而来（vx/vy 才是真状态）。
    // 这是「推摇杆逐渐加速、松摇杆平滑减速」的唯一实现方式 —— 输入只负责给目标速度。
    // ★ 阶段 4-1：场地无限，出生点就取世界原点 (0, 0)。渲染层把相机对到玩家身上，
    //   所以"原点在哪"对玩家不可见 —— 它只是个稳定的数值参照，不该再跟视口尺寸挂钩
    //   （挂钩的话，改一次窗口大小就等于换了出生点，同类种子的复现性会跟着窗口走）。
    this.player = { x: 0, y: 0, r: ARENA.PLAYER_RADIUS, vx: 0, vy: 0 };
    this.enemies = [];
    this.projectiles = [];
    this.gems = [];
    this.particles = [];
    this.floaters = [];
    // 死亡动画是**纯视觉**的，必须与逻辑数组分开存 —— 若把"正在爆裂的怪"留在 this.enemies 里，
    // 它还会被自动攻击锁定、还会扣血、还会算进 MAX_ENEMIES 与波次密度，于是"加个动画"就
    // 悄悄改了玩法口径。分开存 = 零逻辑影响。
    this.deaths = [];
    // 阶段 4-7.x：心心（回血掉落）。与 gems/deaths 一样单独存，掉落/拾取零逻辑副作用。
    this.hearts = [];
    this.heartsDropped = 0;

    // ── 阶段 4-5：角色（倍率先落，meta 的加算在构造器末尾）──
    // ★ 顺序不能反：meta 那几条解锁是**加算**（比如「起始生命 +20」），
    //   倍率必须作用在**基础值**上 —— 否则"重壳守卫 + 坚韧体魄"会变成
    //   (90 + 20) × 1.5，而不是 90 × 1.5 + 20。前者让角色和解锁互相放大，
    //   后者才是"两个独立的来源叠加"。
    this.heroId = heroById(meta.hero || DEFAULT_HERO).id;  // ★ 乱 id 也归一到合法英雄，不开局崩
    const hero = heroById(this.heroId);

    // HP 自持（本项目的血，不再借用任何外部 run）
    this.maxHp = Math.round(ARENA.PLAYER_HP * hero.hpMul);
    this.hp = this.maxHp;

    this.spawnTimer = 0.3;   // 阶段 4-7：第一波 0.3s 到（原 0.8s，反馈"开局太晚"）
    // 贴身围堵的节拍器（阶段 4-1.2）。首拍与刷怪错开 1.5s，免得开局两件事挤在同一帧。
    this.swarmTimer = ARENA.SWARM_EVERY + 1.5;
    this.attackTimer = 0;
    this.xp = 0;
    this.level = 0;
    this.xpToLevel = this.xpNeed(0);

    // 成长态（升级项作用的四个真值 + 磁吸半径）
    // ★ 阶段 4-5：英雄倍率作用在**基础值**上（dmg / 移速 / 攻速），meta 解锁是后面的加算。
    this.dmg = Math.round(ARENA.BASE_DMG * hero.dmgMul);
    // ★ 阶段 5：moveBase 是"未被临时增益改动的那一档移速"，moveSpeed 由它派生。
    //   不动基础值就无法同时支持两个乘算来源（后者会把前者覆盖掉） ——
    //   而 gale 的「猎风」正是第二个来源。
    this.moveBase = Math.round(ARENA.BASE_MOVE * hero.moveMul);
    this.moveSpeed = this.moveBase;
    // ★ 阶段 5：移速的**两条成长通道**。以前「移速 +15%」直接写 `moveSpeed *= 1.15`，
    //   那在只有它一个来源时没毛病；一旦再叠上「猎风」这种"每帧重算"的临时倍率，
    //   两边就是互相擦除关系 —— 谁最后写谁算数，先写的那个凭空消失。
    //   所以改成：所有永久加成写进这两个累加器，moveSpeed 由 `_refreshClassBuffs()` 折出来。
    this.moveMulP = 1;      // 乘算来源（「移速 +15%」被动）
    this.moveFlat = 0;      // 加算来源（元解锁「疾足 +12」）
    this.attackInterval = ARENA.BASE_ATTACK_INTERVAL / hero.atkMul;  // 攻速倍率 >1 = 间隔更短
    this.shots = 1;
    this.magnet = ARENA.GEM_MAGNET;

    // 一局战绩（结算只报「存活时间 + 总击杀数」，其余仅作调试/复盘读数）
    this.kills = 0;
    this.gemsCollected = 0;
    this.hits = 0;          // 投射物/武器命中次数（仅作统计 + 音效触发，不影响任何玩法口径）
    // ★ 阶段 4-9：击杀**来源**归因。spec 的硬断言是「主动技能造成的击杀 < 总击杀的 15%、
    //   武器 > 80%」—— 没有这张表，那条断言就无从核对（只能靠读代码猜）。
    //   它是**纯统计**：不喂给任何伤害/经济/刷怪判定，写错了也只影响读数本身。
    //   六个来源 = 统一伤害入口 applyHit 的全部调用点（见那里的 src 参数）；
    //   'other' 是兜底桶 —— 它的值**必须恒为 0**，否则说明有一条击杀绕过了具名来源
    //   （tests 会断言；arena-sim 还会交叉核对 Σ 归因 === 总击杀）。
    // ★ 阶段 5：新增 'sword' 桶 —— 剑是第 4 把武器，来自它 applyHit 调用点；
    //   不登记的话剑的击杀会落进 'other'，直接触发那条"有击杀绕过了具名来源"的断言。
    this.killSrc = { projectile: 0, orbit: 0, laser: 0, sword: 0, shockwave: 0, dash: 0, thorn: 0, other: 0 };
    // ★ 阶段 5.1 诊断用：每件武器的**净输出伤害**累计（含 gDmgMul，按"实际扣掉的 hp"计，
    //   不把溢出伤害算进去）。只用于 arena-sim 的逐分钟 DPS 复核，不参与任何判定、不改任何玩法。
    this.dmgDealt = { projectile: 0, orbit: 0, laser: 0, sword: 0, shockwave: 0, dash: 0, thorn: 0, other: 0 };

    // ── 阶段 2：持有的武器 / 技能（"获得即持有"，可叠加强化）──
    // ★ 阶段 4-5：英雄签名武器/技能替换默认组合；投射物**不是人人都有** ——
    //   流浪者/疾风行者以投射物开局，重壳守卫以环绕刃开局（"开局"就是它们的枪）。
    this.weapons = { projectile: hero.weapon === 'projectile', sword: false };
    this.weapons[hero.weapon] = true;
    this.skills = { shockwave: false, dash: false, frost: false };
    this.skills[hero.skill] = true;
    // 武器/技能对象先给零值占位（未解锁也无害；解锁时由 initWeapon/initSkill 覆盖）
    this.orbit = { count: ARENA.ORBIT_COUNT, dmg: ARENA.ORBIT_DMG, r: ARENA.ORBIT_R, ang: 0, spin: ARENA.ORBIT_SPIN };
    this.laser = { dmg: ARENA.LASER_DMG, w: ARENA.LASER_W, interval: ARENA.LASER_CD, cd: 0, cleave: false };
    // 阶段 5：剑（第 4 把）。当前形态不在这里重复存 —— 唯一真源是 this.evolved.sword
    //   （0=C1 直线 / 1=C2 扇形 / 2=C3 环绕，见 W_STAGE_MAX.sword 与 _checkEvolution）。
    //   存两份就一定会漂：哪天进化在某个分支改了一处、没改另一处，画面就停在旧形态上。
    this.sword = { dmg: ARENA.SWORD_DMG, count: ARENA.SWORD_COUNT, interval: ARENA.SWORD_INTERVAL,
      cd: 0, speed: ARENA.SWORD_SPEED };
    // C3 环绕那一圈的运行时状态。★ 它是"每帧从玩家坐标重算出来的一圈刀"，不是一堆实体：
    //   刀的位置必须锁在玩家身上，而玩家一直在走 ⟹ 位置只能现算，不能存；
    //   swordBlades 只是"逻辑 → 渲染"这一帧内的交接口，每帧 length=0 重写。
    this.swordRing = { ang: 0, tick: 0 };
    this.swordBlades = [];
    this.skShock = { radius: ARENA.SHOCKWAVE_RADIUS, dmg: ARENA.SHOCKWAVE_DMG,
      cdBase: ARENA.SHOCKWAVE_CD, knock: ARENA.SHOCKWAVE_KNOCK };
    this.skDash = null; this.skFrost = null;   // 解锁时由 initSkill 填
    this.initWeapon(hero.weapon);   // orbit / laser 初始化对象（投射物是 no-op）
    this.initSkill(hero.skill);
    // 被动里三条"乘算/加算"的成长（初始值必须是 1，否则和 ARENA 常量对不上）
    this.cdMul = 1;         // 技能冷却系数（「技能冷却 -15%」）
    this.projSpeed = ARENA.PROJECTILE_SPEED;
    // 阶段 5 · B3：本命武器专属强化的三个默认档（ClassPerks 会按需覆盖）。
    //   默认 = 无改动：没配 perks 的职业（含新加的）行为与阶段 4 完全一致。
    this.projPierce = 0;       // 穿透额度（0 = 命中即消，原行为）
    this.projReachMul = 1;     // 投射物有效射程倍率
    this.orbitCtrlBonus = 0;   // 环绕刃对被控目标的额外伤害比例
    // 阶段 3 被动：armor=减伤 / xpMul=经验倍率 / regenRate=每秒回血 / thorn=接触反伤。
    // 默认恒等（0 / 1），对"没拿这些被动"的局零影响。
    // 阶段 5：gDmgMul = **全局伤害系数**（在 applyHit 里统一结算，见那里的注释）。
    //   ★ 分两部分：`dmgBase` 是可被外部（属性树 / 元进度）写的底数，恒为 1；
    //     `gDmgMul` 是 `_refreshClassBuffs()` 折出来的**结果**（别直接写它，会被下一次刷新盖掉）。
    //   ★ 阶段 5.1：本想用这个底数做 ×1.13 的"中性生存补偿"，但它会**连技能一起抬**，
    //     把冲击波从 3.75 顶到 4.24、反而能打死 4 血的群冲/裂片，撞破「技能打不死任何怪」
    //     这条 spec 硬边界。所以生存补偿改走「四把武器基础伤同乘 ×1.13」（见各自常量注释），
    //     `dmgBase` 保持恒 1 —— 它只留给未来的属性树/元进度写，不在这里偷偷用。
    this.dmgBase = 1;
    // 阶段 5.1：伤害类**升级/被动**的全局乘区（治本方案）。所有"曾经给某把武器 +N 伤害"的
    //   项现在改成往这里乘一个系数，再由 _refreshClassBuffs 折进 gDmgMul —— 一份升级同时
    //   惠及全部 4 把武器，XP 预算才养得起 4 把（详见 README 阶段 5.1）。
    this.gUpMul = 1;
    this.gDmgMul = 1;
    this.luck = 0;        // 阶段 5 · 长期成长：幸运线（特殊线）的累加值（当前仅存档，影响后续掉落质量）
    // ── 阶段 5 · B1 职业专属被动（见 content.js 的 CLASS_PASSIVES 表头注释）──
    // ★ 三个被动和旁边三条质量纪律一致：**零 rng**（不碰主随机流）、
    //   **不新增伤害来源**（全是倍率/减伤，保证 killSrc 归因不漏），
    //   **一份数据表驱动**（core 里只有"接 + 跑"，具体数值全在 content 表与 ARENA 常量里）。
    this.classPassive = classPassiveOf(this.heroId);
    // ── 阶段 5 · B2 技能变体 / B3 专属武器强化 ──
    // ★ 两者都在**构造器里一次性落实**（读到 CLASS_PERKS 就改对应字段），而不是每帧去查表：
    //   它们是"这个职业是什么"，不是"这一帧发生了什么"。每帧查表的话，
    //   任何一处忘记查都会得到一个"看起来能玩但特有机制没生效"的职业，而那正是最难发现的 bug。
    this.classPerk = classPerkOf(this.heroId);
    this.slowZones = [];    // B2 重壳守卫「地裂」留下的减速场（别的职业恒为空数组）
    // ★ B3 的调用点必须同时满足两个条件，早一步迟一步都是静默失效：
    //   ① 在 `projSpeed / projPierce / projReachMul / orbitCtrlBonus` **默认值之后** ——
    //      它做的是 `*=` 与覆盖，排在前会被那几行赋值整个擦掉；
    //   ② 在 `this.classPerk` **赋值之后** —— 排在前时这个函数读到的是 undefined，直接 return。
    //   ⟹ 所以放在这两段之间，别的顺序都不行。
    this._applyClassPerks();
    this.stoneT = 0;        // 磐石：短窗减伤的剩余时间
    this.windStacks = 0;    // 猎风：当前层数
    this.windDist = 0;      // 猎风：已走完但还没凑够一层的位移
    this.windIdleT = 0;     // 猎风：站定累计时间
    this.windDecayT = 0;    // 猎风：掉层的节拍器
    this._refreshClassBuffs();   // 把上面的 gDmgMul / moveSpeed 折成最终值（未装备 ⟹ 与原值逐比特相同）
    this.armor = 0;
    this.xpMul = 1;
    this.expMul = 1;        // 阶段 5.3：经验收入倍率（每帧由 step 推进；前 3 分钟恒 1）
    this.regenRate = 0;
    this.thorn = 0;
    this.knockMul = 1;      // 击退系数
    // ───────── 阶段 7 · 属性树新节点 / 新装备的执行层字段 ─────────
    // ★ 全部**默认值恒等**：critRate=0、lifesteal=0、thorns=0、goldMul=1、dmgCut=0、
    //   shieldEvery=0 ⟹ 没买对应属性/没选对应装备的局，行为与阶段 6 **逐比特相同**，
    //   16 局回归护栏（跑满 14/16、最低血量 51.3/90、击杀归因 Σ=总）不需要重标。
    this.critRate = 0;      // 暴击率（0~CRIT_RATE_MAX）
    this.critAcc = 0;       // ★ 确定性周期暴击的累计伤害计数器（见 applyHit）
    this.critMul = ARENA.CRIT_DMG_MUL;  // 暴击倍率（150%）
    this.lifesteal = 0;     // 吸血比例（击杀时按已造成伤害回复）
    this.magnetPct = 0;     // ★ 磁吸的**相对**累加器（百分比口径，见 applyGrowth 的 magnetPct）
    this.dmgCut = 0;        // 伤害削减比例（散射/贯穿：最终伤害 ×(1-dmgCut)）
    this.goldMul2 = 1;      // 击杀魂火乘区（贪婪装备；与黄金时段的 goldMul 相乘）
    this.thorns = 0;        // 荆棘：受击反弹给**周围**敌人的伤害比例（区别于单体 thorn）
    this.shieldEvery = 0;   // 护盾充能周期（秒）；0 = 无护盾
    this.shieldT = -1;      // 充能计时（-1 = 未启用）
    this.shieldLayers = 0;  // 当前护盾层数（每层抵挡 1 次伤害）
    // 技能的运行时状态
    this.dashCd = 0; this.frostCd = 0;
    this.dashInvuln = 0;    // >0 时 damagePlayer 是 no-op（闪现途中无敌）
    this.skillCursor = 0;   // 循环释放的指针（"按一下放下一个"）
    this.skillCasts = 0; this.frostCasts = 0; this.laserCasts = 0; this.swordCasts = 0;
    this.lastDir = { x: 0, y: -1 }; // 最近一次移动方向（站定时闪现的兜底方向）
    this.fx = [];           // 短特效（光束/霜环/残影/开箱），纯视觉
    // 阶段 4-1：敌方子弹（远程精英的直线弹）。**世界坐标**，与敌人/宝石同一套坐标系，
    // 因此同样参与相机偏移与 1500px 回收，不需要任何特判。
    this.bullets = [];
    this.chests = [];
    this.chestTimer = ARENA.CHEST_FIRST;
    this.chestsOpened = 0;
    this.newThings = 0;     // 已拿到的"新东西"（新武器/新技能）计数，前期保底用

    this.shockwaveCd = 0;
    this.shockChargeT = -1;     // 蓄力圈进度（<0 表示无）
    this.shockwaveCastT = -1;   // 爆发环进度（<0 表示无）
    this.flashT = -1;
    this.hurtT = -1;        // 阶段 4-10：受击红屏脉冲计时（-1 = 不显示）
    this.levelFlashT = -1;  // 阶段 4-11：升级全屏暖光脉冲计时（-1 = 不显示，纯显示字段）
    this.bossFlashT = -1;   // 阶段 4-11：Boss 出场红场脉冲计时（-1 = 不显示，纯显示字段）
    this.shockCasts = 0;

    // 统计口径（模拟器/测试用）
    this.spawned = 0;
    // 阶段 4-12：局内突发事件（确定性调度 + 统计）
    this.eventIdx = 0;            // 下一个待触发事件下标
    this.nextEventAt = ARENA.EVENT_FIRST;
    this.goldMul = 1;            // 黄金时段倍率（仅拾取经验时乘，纯经济、不碰判定）
    this.goldUntil = -1;         // 黄金时段结束时刻（-1 = 未激活）
    this.magnetMul = 1;          // 磁暴倍率（拾取半径乘数，纯增益、不碰判定）
    this.magnetUntil = -1;       // 磁暴结束时刻（-1 = 未激活）
    this.eventLog = { gold: 0, supply: 0, elite: 0, magnet: 0, eliteWave: 0 }; // 触发计数（sim 自证）
    // 补给/精英落点的**独立**随机源：不污染主 rng 流 ⟹ 同种子同结果护栏仍成立
    this.srcRng = new Rng('event:' + (this.rng && this.rng.seed ? this.rng.seed : 'seed'));
    this.eliteSpawned = 0;  // 阶段 4-1：刷出的近战精英数（复盘读数，不影响任何判定）
    // ── 阶段 7 · 精英波（独立于 EVENT_SEQ 的 90 秒节奏，见 ARENA.ELITE_WAVE_* 注释块）──
    this.eliteWaveIdx = 0;        // 已触发的精英波数（sim 自证）
    this.nextEliteWaveAt = ARENA.ELITE_WAVE_ON ? ARENA.ELITE_WAVE_FIRST : 1e9;
    this.eliteWaveKills = 0;      // 精英波怪被击杀数（自证「击杀必掉技能选择」真的在发）
    this.eliteSkillDrops = 0;     // 待兑现的技能三选一次数（排队，不立刻弹窗——见注释块）
    this.eliteSkillGiven = 0;     // 已兑现（玩家真的拿到牌）的次数（sim 自证「击杀必掉」）
    this.bulletsFired = 0;  // 阶段 4-1：远程精英射出的弹数（同上）
    // 阶段 4-1.1：**自证远程怪真的在工作**（spec 要求 arena-sim 报出这三个数）。
    // ★ 为什么必须落成计数器而不是靠"同屏里有橙块"目测：远程怪占刷怪 1.4%~2.5%，
    //   权重表写错时（比如 ranged 那一列写进了前两格、或整列被顺手删掉）**画面几乎没差别**，
    //   但机制等于不存在。N=0 就是"权重/刷新条件写错了"的唯一可执行判据。
    this.rangedSpawned = 0; // 刷出的远程精英数
    this.bulletHits = 0;    // 远程弹**命中玩家**的次数（打到玩家的那颗即消 ⟹ 等于"挨了几发"）
    // 阶段 4-1.2：「贴身围堵」自证。同上的理由 —— 围堵是"每 8 秒补 3~4 只"这种
    // 低频事件，写错（节拍没减、门槛把整局挡掉、batch 恒为 0）在总出场数里几乎看不出，
    // 但"近身压力"这条体验等于不存在。所以单独计数，并在 arena-sim 里报出来。
    this.swarmSpawned = 0;
    this.kindCounts = {};    // 阶段 4-7：各怪类型出场计数（sim 自证用）
    this.openingSalvo();     // 阶段 4-7：开局先放 3 只，保证前 10 秒有怪可打、20 秒见第一波宝石

    // ── 阶段 4-3：连杀 Combo（spec 一-3）──
    // 只做显示（字号/颜色随档位变），不参与任何伤害/经济判定 —— spec 明文"不影响数值"。
    // 计数器放在 core 是因为 killEnemy 只发生在 core 里；渲染层只读这两个字段。
    this.combo = 0;
    this.comboT = 0;          // 剩余窗口 s；归零即断连
    this.comboBest = 0;       // 本局最高连击（结算读数）
    // ── 阶段 4-3：局内里程碑（spec 二-3）──
    // mileFlags 与 MILESTONES 一一对应：第 i 条是否已触发过（不重复弹）。
    // milestones 是**待渲染层消费的队列**：core 只管 push，渲染层取走并显示。
    // ★ 因此它不影响任何玩法判定 —— 队列里堆着没人取也只是几个字符串。
    this.mileFlags = ARENA.MILESTONES.map(() => false);
    this.milestones = [];
    // 宝石弹出的方向轮（黄金角）。★ 用固定序列而不是 rng：掉落排布是纯表现，
    // 不该消耗确定性随机流（消耗了就给"同种子同结果"多加一条隐形耦合）。
    this._gemSpin = 0;
    // 阶段 4-3：表现层专用伪随机的**计数器**（见 _frand 的注释：粒子不再消耗主 rng）。
    this._fxSpin = 0;

    // ── 阶段 4-4：Boss 节点 ──
    this.bossIdx = 0;              // 下一个**待出场**的 Boss（BOSS_ORDER 下标）
    this.bossWarned = -1;          // 已经打过警告的下标（−1 = 一个都没打过）
    this.bossRef = null;           // 当前活着的 Boss 实体（null = 场上没有 ⟹ 才允许刷下一个）
    this.bossSpawned = BOSS_ORDER.map(() => 0);  // 各 Boss 的出场次数（自证用）
    this.bossKills = BOSS_ORDER.map(() => 0);    // 各 Boss 的击杀次数（spec 三-3 自证）

    // ── 阶段 4-5：超武进化 ──
    // wLvl：每把武器"拿过几次专属强化" = 武器等级；满级 + 凑齐被动 ⟹ 自动进化。
    // evolved：**进化到第几阶**（整数，0=未进化；上限见 ARENA.W_STAGE_MAX）。
    //   阶段 5 之前它是布尔（除了剑没有第二条进化线，true/false 够用）；剑要 C1→C2→C3 两级，
    //   所以升格成 stage —— 旧的三条线 maxStage 都是 1，读写语义完全等价 ⟹ 零行为变化。
    // passiveTaken：被动拿过几次（进化需要的被动按 id 计数）。
    this.wLvl = Object.fromEntries(Object.keys(ARENA.W_LEVEL_MAX).map((k) => [k, 0]));
    this.evolved = Object.fromEntries(Object.keys(ARENA.W_LEVEL_MAX).map((k) => [k, 0]));
    this.passiveTaken = {};
    this.spiralCd = ARENA.SPIRAL_CD;   // 螺旋弹幕节拍器（进化后启用）
    this.spiralAng = 0;

    this.upgradesTaken = [];

    // ── 阶段 6-4：魂火商栈（局内商店）──
    // ★ 货币「魂火」独立于 gems=xperience：击杀掉落、商店消费，不进任何升级/成长口径。
    //   rollShop 用**独立**随机源（不污染主玩法 rng 流）⟹ 同种子同结果护栏仍成立。
    this.soulfire = 0;
    this.shopRng = new Rng('shop:' + (this.rng && this.rng.seed ? this.rng.seed : 'seed'));
    this._nextShopIdx = 0;     // 下一个待触发的 SHOP_TIMES 下标
    this.shopOpen = false;     // 非 null/true 时游戏暂停，等待购买/跳过
    this.shopGoods = null;     // 当前 3 件货物（rollShop 的结果）
    this.shopAtSec = -1;       // 本次开门时的已过秒数（复盘读数）
    this.shopBought = [];      // 本局已购买的货物 id（复盘/自证）
    this.shopVisits = 0;       // 本局开门次数（自证：应 = 3）
    this.shopSpend = 0;        // 本局花费的魂火总额（复盘读数）

    this.pendingUpgrade = null; // 非 null 时游戏暂停，等待三选一
    this.pendingUpgradeKind = null; // 阶段 7：'level' 升级弹出 / 'elite' 精英波奖励（不涨等级、不吃经验）
    this.done = false;
    this.survived = false;      // 活满 10 分钟

    // ── 阶段 3 元进度：把"已解锁且已启用"的 meta 套到初始状态上 ──
    // 默认 meta 为空（或 meta.enabled 空）→ 一个都不 apply → 行为等同阶段 2 末。
    // 复活是唯一的"新增运行时字段"，但 revivesLeft 默认 0，对正常局零影响。
    this.revivesLeft = 0;
    this.meta = meta || {};
    this.applyGrowth();   // 阶段 5 · 长期成长：把 meta.levels / rebirth 套到初始状态
    this.applyLoadout();  // 阶段 6-3 · 局外配装：在成长之后叠加（同口子，互不擦除）
  }

  /** 阶段 5 · 长期成长（A1 属性树 + A2 职业线 + A3 转生倍率）。
   *  ★ 只读 meta.levels / meta.rebirth，按 GROWTH_LINES 的 stat 映射到初始字段；
   *    不碰主 rng、不新开状态机、不新增伤害来源（killSrc 归因不变）。
   *  ★ 转生倍率先落到 floor（dmgBase / maxHp / moveBase），属性等级再叠加上去，
   *    末尾统一 _refreshClassBuffs() 折出 gDmgMul / moveSpeed —— 这样多重来源互不擦除。 */
  applyGrowth() {
    const meta = this.meta || {};
    const levels = meta.levels || {};
    const rb = 1 + 0.10 * (Number(meta.rebirth) || 0);
    this.dmgBase *= rb;
    this.maxHp = Math.round(this.maxHp * rb);
    this.hp = this.maxHp;
    this.moveBase = Math.round(this.moveBase * rb);
    for (const id in levels) {
      const L = growthLineOf(id);
      if (!L) continue;
      const lv = Number(levels[id]) || 0;
      if (lv <= 0) continue;
      const amt = L.per * lv;
      switch (L.stat) {
        case 'maxHp':    this.maxHp += amt; this.hp += amt; break;
        case 'dmgBase':  this.dmgBase += amt; break;
        case 'moveFlat': this.moveFlat += amt; break;
        case 'magnet':   this.magnet += amt; break;
        // ★ 阶段 7：磁吸改百分比口径。原来是 `this.magnet += amt`（绝对 +20/级），
        //   与生命/伤害这种"相对基准的百分比"混在一棵树里，"每级 ≤15%"这条判据没法统一算
        //   （详见 content.js GROWTH_LINES 上方的口径核对表）。改成累加到 magnetPct，
        //   最后一次性乘进 this.magnet —— 与"磁暴事件"（magnetMul，纯增益波）仍然互不擦除。
        case 'magnetPct': this.magnetPct += amt; this.magnet *= (1 + amt); break;
        case 'xpMul':    this.xpMul *= (1 + amt); break;
        case 'regen':    this.regenRate += amt; break;
        // ── 阶段 7 新增的两条 ──
        case 'critRate':  this.critRate = Math.min(ARENA.CRIT_RATE_MAX, this.critRate + amt); break;
        case 'lifesteal': this.lifesteal = Math.min(ARENA.LIFESTEAL_MAX, this.lifesteal + amt); break;
        case 'revives':  this.revivesLeft += Math.round(amt); break;
        case 'luck':     this.luck = (this.luck || 0) + amt; break;
        case 'classDmg':   if (this.classPassive) this.classPassive.dmgPerLevel += amt; break;
        case 'classStone': if (this.classPassive) this.classPassive.stoneDr = Math.min(0.9, this.classPassive.stoneDr + amt); break;
        case 'classWind':  if (this.classPassive) { this.classPassive.windDmg += amt; this.classPassive.windMove += amt; } break;
      }
    }
    this._refreshClassBuffs();
  }

  /** 阶段 6-3 · 局外配装：把 meta.loadout 选中的数值加成套到初始状态。
   *  ★ 在 applyGrowth() 之后调用 —— 与「属性树 + 转生」同一套初始字段（dmgBase/maxHp/
   *    moveBase/magnet/xpMul/cdMul），多重来源互不擦除。
   *  未选（默认）时 loadoutBuffs 全 0 ⟹ 与基线逐比特相同 ⟹ 16 局回归不破。
   *  ★ 改完 dmgBase/moveBase 必须再 _refreshClassBuffs() 折出 gDmgMul/moveSpeed。 */
  applyLoadout() {
    const b = loadoutBuffs(this.meta && this.meta.loadout);
    if (b.dmgBase) this.dmgBase += b.dmgBase;
    if (b.maxHp) { this.maxHp += b.maxHp; this.hp += b.maxHp; }
    if (b.moveBase) this.moveBase += b.moveBase;
    if (b.magnet) this.magnet += b.magnet;      // 拾荒（绝对半径，和属性树的百分比口径不同来源）
    if (b.xpMul) this.xpMul *= (1 + b.xpMul);
    if (b.cdMul) this.cdMul *= (1 - b.cdMul);    // 急速：技能冷却缩减
    // ── 阶段 7：6 件新装备的buff 落地 ──
    // ★ shots 与 pierceN 都**叠加**到已有字段而不是新建：`shots` 是「投射物 +1」被动在用的、
    //   `projPierce` 是剑与流浪者「连珠」在用的 ⟹ 装备与它们天然同一套口径、同一批硬上限
    //   （MAX_SHOTS），不会出现"装备绕过上限堆到满屏弹道"。
    if (b.shots) this.shots = Math.min(ARENA.MAX_SHOTS, this.shots + b.shots);
    if (b.pierceN) this.projPierce = Math.max(this.projPierce, b.pierceN);
    if (b.dmgCut) this.dmgCut = Math.min(0.6, this.dmgCut + b.dmgCut);
    if (b.critRate) this.critRate = Math.min(ARENA.CRIT_RATE_MAX, this.critRate + b.critRate);
    if (b.lifesteal) this.lifesteal = Math.min(ARENA.LIFESTEAL_MAX, this.lifesteal + b.lifesteal);
    if (b.thorns) this.thorns = Math.min(0.6, this.thorns + b.thorns);
    // goldMul（贪婪）与黄金时段的 goldMul 是**两个不同来源** ⟹ 相乘，不覆盖
    if (b.goldMul) this.goldMul2 *= (1 + b.goldMul);
    // 护盾：shieldEvery > 0 时启动充能计时。
    // ★ 开局**立刻给满层**（shieldLayers = 上限），而不是等第一个周期结束——
    //   "每 30 秒获得一层"的第一层理应在穿装那一刻就有，否则玩家开局 30 秒内
    //   白白裸奔，而这段时间恰好是怪最密的阶段。计时器同时置满 ⟹ 第二层 30 秒后才来。
    if (b.shieldEvery > 0) {
      this.shieldEvery = b.shieldEvery;
      this.shieldT = b.shieldEvery;
      this.shieldLayers = ARENA.SHIELD_LAYERS_MAX;
    }
    // 重生：走 revivesLeft，与「不屈」线同一个复活池（同源 ⟹ 不会出现两套复活互相打架）
    if (b.revives) this.revivesLeft += Math.round(b.revives);
    this._refreshClassBuffs();
  }

  // ── 阶段 6-4：魂火商栈 ──
  // ★ 开门即暂停世界（step 早退），等 resolveShop 清掉 shopOpen 才继续。
  //   货物用**独立**随机源 shopRng 抽取 ⟹ 不污染主玩法 rng 流，同种子同结果护栏仍成立。
  openShop() {
    const t = ARENA.SHOP_TIMES[this._nextShopIdx] != null ? ARENA.SHOP_TIMES[this._nextShopIdx] : this.elapsed;
    this._nextShopIdx += 1;
    this.shopOpen = true;
    this.shopGoods = rollShop(this.shopRng, 3);
    this.shopAtSec = Math.round(this.elapsed);
    this.shopVisits += 1;
  }

  /** 结算商店：buyIds 是玩家想买的货物 id 列表（按可负担 + 去重过滤）。
   *  ★ sim 传 []（不购买，保持回归=基线）；人力游戏传点击的 id。
   *   买不起 / 未知 id 静默跳过；末了清掉 shopOpen 让世界继续。 */
  resolveShop(buyIds) {
    if (!this.shopOpen) return;
    const buys = Array.isArray(buyIds) ? buyIds : [];
    const seen = new Set();
    for (const id of buys) {
      if (seen.has(id)) continue;
      const good = (this.shopGoods || []).find((g) => g.id === id);
      if (!good || this.soulfire < good.cost) continue;  // 买不起 / 不存在 → 跳过
      seen.add(id);
      this.soulfire -= good.cost;
      this.shopSpend += good.cost;
      applyShopGood(this, good);
      this.shopBought.push(id);
    }
    this.shopOpen = false;
    this.shopGoods = null;
  }

  /** 渲染层告知的**视口**尺寸（HUD 布局 + "屏幕外"粗判用）。
   *  ★ 阶段 4-1 起它**不是墙**：场地无限，任何逻辑都不得拿 w/h 把东西 clamp 回去。
   *    这条改名没改（`setBounds` 这个名字已经名不副实），是为了不动 renderer/工具的调用点；
   *    真正的语义写在 `this.w/this.h` 的用法里 —— 只出现在渲染与诊断读数中。 */
  setBounds(w, h) {
    this.w = w;
    this.h = h;
  }

  /** 已过去的秒数 */
  get elapsed() {
    return this.time / 1000;
  }

  /** 剩余秒数 */
  get remainSec() {
    return Math.max(0, (this.durationMs - this.time) / 1000);
  }

  /** 当前波次（WAVES 按 t 升序，取最后一个 t ≤ 已过秒数的） */
  wave() {
    const s = this.elapsed;
    let cur = ARENA.WAVES[0];
    for (const w of ARENA.WAVES) {
      if (s >= w.t) cur = w;
      else break;
    }
    return cur;
  }

  /** 是否处于「后 3 分钟」高潮窗口 */
  inClimax() {
    return this.remainSec <= ARENA.CLIMAX_SEC;
  }

  /** 主步进。input = {x, y} 各 ∈ [-1,1]（摇杆/键盘已归一化方向）。
   *  升级暂停 / 已结束时为 no-op（满足「升级界面暂停游戏」）。 */
  step(dt, input = { x: 0, y: 0 }) {
    if (this.done || this.pendingUpgrade) return;

    this.time += dt * 1000;
    // 阶段 5.3：收入倍率跟着真实时间推进（前 3 分钟恒 1，之后 +26%/分）。
    //   放在 time 之后、其余逻辑之前，保证本帧内所有掉落都用同一个 expMul（不会半帧两值）。
    this.expMul = this.expMulAt();
    // 阶段 6-4：魂火商栈触发（第 2/5/8 分钟各一次）。
    // ★ 只置位 shopOpen（pure logic），不在 step 里暂停 ——
    //   「暂停」由调用方决定：渲染层 _loop / sim / fastForward 在 shopOpen 时不再调 step。
    //   这样 step 仍是「推进一帧」的纯函数，老测试直接 set c.time + step 不会被卡死
    //   （实测：内部早退会让 Boss/死亡结算等快进到 120s+ 的测试永远停住）。
    if (this._nextShopIdx < ARENA.SHOP_TIMES.length
        && this.elapsed >= ARENA.SHOP_TIMES[this._nextShopIdx]) {
      this.openShop();
    }
    // 阶段 4-3：时间型里程碑（撑过 1/3/5 分钟）。放在 time 更新之后、其余逻辑之前：
    // 它只 push 一行待显示文本，不暂停、不打断任何判定（spec 二-3「不暂停」）。
    this._checkMilestones();

    // 冲击波三拍计时（冷却 / 蓄力 / 爆发环）+ 白闪：全是「无 rng 的纯视觉」，不影响确定性。
    // 顺序要求：**先衰减计时器，再处理本帧触发的"蓄力完成 → 爆发"**。
    // 反过来的话，本帧刚点亮的白闪会被本帧的 dt 立刻扣掉 —— dt≈1/60 时看不出问题，
    // 但一次 100ms 的掉帧就会让白闪整帧消失（"技能炸了却没看见闪"），
    // 而白闪恰恰是"炸了"这件事唯一的全屏读数。（单元测试抓到的，见 §5）
    if (this.dashCd > 0) this.dashCd = Math.max(0, this.dashCd - dt);
    if (this.frostCd > 0) this.frostCd = Math.max(0, this.frostCd - dt);
    if (this.dashInvuln > 0) this.dashInvuln = Math.max(0, this.dashInvuln - dt);
    // 阶段 5 · B1 磐石窗口推进：受击后开一段短窗口，窗口内的后续伤害打折。
    // 放在这里而不是 damagePlayer 里，是为了「窗口跟着真实时间走」——
    // 站着不动也该到期，而不是等下一次挨打才结算。
    // 阶段 5 · B2：地裂减速场的推进与回收（放在 timer 段，和闪现无敌/白闪同一口径 ——
    //   这些都是"跟着真实时间走"的量，不该赖在某次命中上）。
    if (this.slowZones.length) this.slowZones = this.slowZones.filter((z) => (z.t -= dt) > 0);
    if (this.stoneT > 0) this.stoneT = Math.max(0, this.stoneT - dt);
    if (this.shockwaveCd > 0) this.shockwaveCd = Math.max(0, this.shockwaveCd - dt);
    if (this.shockwaveCastT >= 0) {
      this.shockwaveCastT += dt;
      if (this.shockwaveCastT >= ARENA.SHOCKWAVE_FX) this.shockwaveCastT = -1;
    }
    if (this.flashT >= 0) {
      this.flashT -= dt;
      if (this.flashT < 0) this.flashT = -1;
    }
    if (this.hurtT >= 0) { this.hurtT -= dt; if (this.hurtT < 0) this.hurtT = -1; }   // 阶段 4-10：受击脉冲衰减
    if (this.levelFlashT >= 0) { this.levelFlashT -= dt; if (this.levelFlashT < 0) this.levelFlashT = -1; }  // 阶段 4-11：升级暖光脉冲衰减
    if (this.bossFlashT >= 0) { this.bossFlashT -= dt; if (this.bossFlashT < 0) this.bossFlashT = -1; }   // 阶段 4-11：Boss 出场红脉冲衰减
    // 阶段 4-3：连杀窗口衰减 —— 2 秒内没有新的击杀就断连（spec 一-3）。
    // ★ combo 是**纯显示**：断连只清这两个字段，不碰任何伤害/经济/刷怪口径。
    if (this.comboT > 0) {
      this.comboT -= dt;
      if (this.comboT <= 0) { this.comboT = 0; this.combo = 0; }
    }
    // 阶段 3「持续回复」被动：每秒回一点血（不超上限）。放在计时器段，和闪现无敌/白闪同口径。
    if (this.regenRate > 0) this.healPlayer(this.regenRate * dt);
    // 阶段 7 · 护盾充能（shieldEvery > 0 才进入，默认恒为 0 ⟹ 零开销、逐比特不变）
    this._tickShield(dt);
    if (this.shockChargeT >= 0) {
      this.shockChargeT += dt;
      if (this.shockChargeT >= ARENA.SHOCKWAVE_CHARGE) {
        this.shockChargeT = -1;
        this.detonateShockwave(); // 伤害 / 击退 / 白闪 / 爆发环全部发生在这一刻
      }
    }

    // ── 玩家移动（速度插值，不是线性瞬移） ──
    // 输入只负责给**目标速度**，实际速度用指数趋近追上去：
    //   推摇杆 → 逐渐加速（MOVE_ACCEL 内到 95%）；松摇杆 → 平滑减速（MOVE_DECEL 内基本停住）。
    // 阶段 4-1：位移**不再 clamp**（场地无限，没有"墙外"这回事）。
    //   惯性因此第一次真正表现了它的设计意图 —— 松手滑出去的那一小段不会被墙吃掉。
    // 注意这里**不能**写成 `if (mag > 0.001) {...}` —— 松手那一帧 mag 已经是 0，
    // 若整段跳过，速度会永远停在松手前的值上（人物变成永动的"滑冰"）。
    const mag = Math.sqrt(input.x * input.x + input.y * input.y);
    const spd = this.moveSpeed * (mag > 1 ? 1 : mag);
    const tvx = mag > 0.001 ? (input.x / mag) * spd : 0;
    const tvy = mag > 0.001 ? (input.y / mag) * spd : 0;
    const sec = mag > 0.001 ? ARENA.MOVE_ACCEL : ARENA.MOVE_DECEL;
    this.player.vx = approach(this.player.vx, tvx, sec, dt);
    this.player.vy = approach(this.player.vy, tvy, sec, dt);
    const ux = mag > 0.001 ? input.x / mag : 0, uy = mag > 0.001 ? input.y / mag : 0;   // 归一化后的输入方向
    const moved = Math.hypot(this.player.vx, this.player.vy) * dt;
    if (moved > 0) { this.player.x += this.player.vx * dt; this.player.y += this.player.vy * dt; }
    // 阶段 5 · B1 猎风：位移积分攒层（站定则开始掉层）。全部确定性，不碰 rng。
    this._stepWind(moved, mag > 0.001, dt);
    if (mag > 0.001) { this.lastDir.x = ux; this.lastDir.y = uy; }

    // ── 刷怪（数据驱动的波次表） ──
    this.spawnTimer -= dt;
    if (this.spawnTimer <= 0) {
      const climax = this.inClimax();
      let batch = climax ? ARENA.CLIMAX_BATCH : 1;
      // ★ 阶段 4-1 软上限（理由见 CLIMAX_SOFT_GAP 的注释）：这一拍会把同屏推过 SOFT 就**整拍跳过**。
      //   要点是"不刷"，而不是"先刷再被 MAX_ENEMIES 丢回来" —— 后者 = 静默丢怪，
      //   峰值会退化成随机截断（实测 100~220 乱跳），而前者让峰值稳定钳在 SOFT 之下。
      if (this.enemies.length + batch > ARENA.MAX_ENEMIES - ARENA.CLIMAX_SOFT_GAP) batch = 0;
      for (let i = 0; i < batch && this.enemies.length < ARENA.MAX_ENEMIES; i++) this.spawnEnemy();
      const wave = this.wave();
      let interval = wave.spawn * ARENA.SPAWN_INTERVAL_MUL;
      if (climax) interval *= ARENA.CLIMAX_MUL;
      // 阶段 4-4：Boss 在场时普通怪**继续刷**，但密度降 20%（spec 四：别堆太满）。
      // ★ 不能直接"少刷几个"—— 那样会破坏"整拍跳过"的软上限口径；调**间隔**才是同一个旋钮。
      if (this.bossRef) interval *= ARENA.BOSS_DENSITY_MUL;
      this.spawnTimer = interval * (1 - ARENA.SPAWN_JITTER / 2 + this.rng.next() * ARENA.SPAWN_JITTER);
    }

    // ── 贴身围堵（阶段 4-1.2）──
    // 与上面那条**独立**的节拍：刷怪表管"从外面涌进来"，这条管"贴脸补位"。
    // ★ 为什么必须独立：刷怪表的速率是"整场铺开"的口径，玩家一跑，那批怪全在身后排队；
    //   只有"以玩家为中心、250~350px 落一下"才能保证**任何时刻**都有人在身边。
    // ⚠ 与刷怪表共用同一条 rng 流（顺序固定：只数 → (kind/角/距/精英)×N），
    //   所以"同种子同结果"依然成立。
    this.swarmTimer -= dt;
    if (this.swarmTimer <= 0) {
      this.swarmTimer = ARENA.SWARM_EVERY;
      if (this.elapsed >= ARENA.SWARM_FROM) {
        let n = ARENA.SWARM_BATCH_MIN
          + Math.floor(this.rng.next() * (ARENA.SWARM_BATCH_MAX - ARENA.SWARM_BATCH_MIN + 1));
        // 与刷怪表同一道软上限：场子已经满了就不补（"限流"而不是"先刷再被丢"，
        // 理由见 CLIMAX_SOFT_GAP）。场子空的时候照补 —— 这正是这条存在的意义。
        if (this.enemies.length + n > ARENA.MAX_ENEMIES - ARENA.CLIMAX_SOFT_GAP) n = 0;
        for (let i = 0; i < n && this.enemies.length < ARENA.MAX_ENEMIES; i++) {
          this.spawnEnemy(ARENA.SWARM_RING_MIN, ARENA.SWARM_RING_MAX);
          this.swarmSpawned += 1;
        }
      }
    }

    // ── 阶段 4-4：Boss 出场调度（警告 → 出场；一次只活一个）──
    this._stepBossSchedule();

    // ── 阶段 4-12：局内突发事件（确定性调度，固定时间 + 固定类型循环）──
    this._stepEvents(dt);

    // ── 阶段 7：精英波调度 + 技能三选一兑现（独立 90 秒节奏，见 ARENA.ELITE_WAVE_*）──
    this._stepEliteWaves(dt);

    // ── 武器：环绕刃 / 直斩（投射物走下面的自动攻击）──
    // 三把武器**各打各的**：独立的计时器、独立的伤害、独立的结算。
    // "玩家只管走位"是这一类游戏的核心承诺，所以武器不能共享节拍。
    if (this.weapons.orbit) this.stepOrbit(dt);
    if (this.weapons.laser) this.stepLaser(dt);
    // 阶段 5：剑（第 4 把）—— 同样是独立节拍，不与上面三把共享计时器。
    if (this.weapons.sword) this.stepSword(dt);

    // ── 自动攻击（投射物：不是人人都有，重壳守卫以环绕刃开局）──
    if (this.weapons.projectile) {
      this.attackTimer -= dt;
      if (this.attackTimer <= 0) {
        if (this.fireVolley()) this.attackTimer = this.attackInterval;
        else this.attackTimer = 0.12; // 射程内无目标：很快再查，等敌人走进来
      }
    }

    // ── 阶段 4-5：螺旋弹幕（投射物进化后启用）──
    // ★ 每 SPIRAL_CD 朝四周齐射一圈，整圈每次转 SPIRAL_STEP —— 连起来看是"螺旋"而非"原地放烟花"。
    //   它走**普通弹道**的同一套更新/命中（见下方投射物段），不另写碰撞。
    if (this.evolved.projectile) {
      this.spiralCd -= dt;
      if (this.spiralCd <= 0) {
        this.spiralCd = ARENA.SPIRAL_CD;
        const px = this.player.x, py = this.player.y;
        for (let k = 0; k < ARENA.SPIRAL_N; k++) {
          const ang = this.spiralAng + (k / ARENA.SPIRAL_N) * TAU;
          this.projectiles.push({
            x: px, y: py,
            vx: Math.cos(ang) * ARENA.SPIRAL_SPEED,
            vy: Math.sin(ang) * ARENA.SPIRAL_SPEED,
            r: 3, life: 2.5, dead: false, src: 'projectile',
          });
        }
        this.spiralAng += ARENA.SPIRAL_STEP;
      }
    }

    // ── 投射物 ──
    // 致死时把**弹道方向**交给死亡动画（碎屑顺着弹道飞出去）。不传方向的话所有死亡
    // 都朝同一侧飘，一眼就能看出是"批量动画"而不是打击反馈。
    for (const p of this.projectiles) {
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.life -= dt;
      // 单位方向：原来隐含"所有人都是 PROJECTILE_SPEED"，阶段 5 起剑的弹速是自己的数，
      // 所以改成按**这条弹自己的速度**归一化（对原投射物是同一个单位向量 ⟹ 行为零变化）。
      const spd = Math.hypot(p.vx, p.vy) || 1;
      const invD = 1 / spd;
      for (const e of this.enemies) {
        // 必须跳过"本帧已被别的弹道打死、但还没被 filter 掉"的敌人：
        // 若不跳过，同一只怪会被连续两条弹道各结算一次击杀 —— 击杀数虚高、
        // 并且多掉一颗宝石（实测曾经 kills 3318 > spawned 3169，即由此产生）。
        if (e.dead) continue;
        const rr = e.r + p.r;
        const ex = p.x - e.x, ey = p.y - e.y;
        if (ex * ex + ey * ey < rr * rr) {
          // 阶段 5：穿透弹 —— 同一只怪只结算一次（p.hits 去重），然后继续找下一个目标。
          //   ★ 不去重的后果不是"多打几下"那么简单：贴身的大怪在穿过它的 3~4 帧里会被逐帧结算，
          //     等于一把秒伤翻几倍的武器，而且**这个倍率随帧率变化**（直接破坏可复现性）。
          if (p.pierce) {
            if (p.hits.indexOf(e) >= 0) continue;
            // ★ 阶段 5 · B3：穿透额度用完即消（pierceN = 还能再穿几只；剑给了 undefined = 无限）。
            if (p.pierceN != null && p.hits.length > p.pierceN) { p.dead = true; break; }
            p.hits.push(e);
            // ★ damage 优先取弹上的快照（剑每道自己带伤害），没有才读全局 this.dmg ——
            //   后者要跟着升级实时变，不能写死在创建那一刻。
            const pdmg = p.dmg != null ? p.dmg : this.dmg;
            // ★ src **必须**由发射方写死在这发弹上。原来这里硬编码 'sword'，那在
            //   B3 给流浪者也上了穿透之后就把它的击杀整个记到剑名下 —— 归因表会
            //   给出一份"看着自洽但全错"的读数（这正是阶段 5 刚开始踩过的坑）。
            this.applyHit(e, pdmg, { ux: p.vx * invD, uy: p.vy * invD, dist: ARENA.DEATH_DRIFT, live: false }, true, p.src || 'other');
            continue;
          }
          p.dead = true;
          // 阶段 4-7：走统一伤害入口（护盾吸收 / 击杀 / 命中读数一套口径）。
          // live:false ⟹ 不推活怪；死亡碎屑沿弹道方向飘 DEATH_DRIFT（保住阶段 4-3 的打击反馈）。
          this.applyHit(e, this.dmg, { ux: p.vx * invD, uy: p.vy * invD, dist: ARENA.DEATH_DRIFT, live: false }, true, 'projectile');
          break;
        }
      }
    }
    // 投射物回收：已命中 / 生命耗尽 / 飞出"还可能命中任何东西"的范围。
    // ★ 阶段 4-1 起场地无限，旧的"飞出屏幕就回收"（_inWorld）不再成立 —— 无限场里没有屏幕边。
    //   改判**与玩家的距离**。
    // ★★ 阶段 4-8：这个半径**就是"射程"本身**，因为弹道是实体、会一路命中下去 ——
    //   旧值 `2 × ATTACK_RANGE`（=600）让"击杀半径"是索敌半径的两倍，实测 60% 的击杀
    //   发生在 300px 之外（详见 PROJ_REACH_MUL 的注释）。改成 `射程 × 1.10` 之后，
    //   "怪必须走近到射程内才会挨打"这句话才真的成立 —— 也才谈得上"让怪走进屏幕再死"。
    // ★ 阶段 5：射程改成**逐弹**算 —— 剑气带自己的 maxDist(380)，
    //   沿用下面这个按 ATTACK_RANGE(240) 推出的通用值会被悄悄砍到 264，spec 的 380 就白写了。
    const reachDefault = ARENA.ATTACK_RANGE * ARENA.PROJ_REACH_MUL * this.projReachMul;
    const clipW = this.w / 2, clipH = this.h / 2;
    this.projectiles = this.projectiles.filter((p) => {
      if (p.dead || p.life <= 0) return false;
      const dx = p.x - this.player.x, dy = p.y - this.player.y;
      const reach = p.maxDist != null ? p.maxDist * ARENA.PROJ_REACH_MUL : reachDefault;
      if (dx * dx + dy * dy > reach * reach) return false;
      // §4-8 一-2：飞出视口矩形即回收。判据用 p.r 让**弹体本身**完全离开屏幕才算飞出，
      // 否则贴边的弹会在"还看得见"的时候凭空消失（那是"武器卡壳"的观感，不是"打不到"）。
      if (ARENA.WEAPON_VIEW_CLIP && (Math.abs(dx) - p.r > clipW || Math.abs(dy) - p.r > clipH)) return false;
      return true;
    });

    // ── 敌人朝玩家直线走，碰到扣血 ──
    // ★ 阶段 4-1：**同一帧最多结算一次接触伤害**。
    //   怪"撞上来就消失"的语义意味着每只怪只咬一口，但**同一帧里可能有十几只同时
    //   贴到身上**（220 同屏、末段走位空间被压满时很常见）。逐只结算等于把"一次碰撞"
    //   变成"一次碰撞 × 同帧到达的只数"，而这个倍数**依赖帧率**：帧率越高、单帧位移越小，
    //   同帧重合的概率越大 —— 同一段物理，60fps 比 30fps 疼。这不是难度，是裁定错误。
    //   实测证据：把 PLAYER_HP 从 90 抬到 130（+44%），那 1 局照样死，而全 16 局的最低血量
    //   从 63.6 涨到 101.1 ⟹ 致死伤**不是被慢慢磨出来的**，是单帧的巨额叠加。
    //   合并之后"贴脸"依然是重伤（末段单击 36~48），但不再是"必死"。
    let contactHit = false;
    for (const e of this.enemies) {
      if (e.dead) continue; // 同上的双重结算问题：已死的怪不该再啃你一口
      if (e.hitT > 0) e.hitT = Math.max(0, e.hitT - dt); // 阶段 4-3：命中闪白衰减（纯视觉）
      // 阶段 4-7.x：出生淡入推进（纯视觉，不影响判定）。appear 从 0→1，渲染层据此缩放+淡。
      if (e.appear != null && e.appear < 1) e.appear = Math.min(1, e.appear + dt / ARENA.APPEAR_T);
      if (e.touchCd > 0) e.touchCd = Math.max(0, e.touchCd - dt); // 阶段 4-4：Boss 接触伤害冷却
      const dx = this.player.x - e.x, dy = this.player.y - e.y;
      const d = Math.sqrt(dx * dx + dy * dy) || 1;
      // 阶段 4-1 回收：被甩在 1500px 之外的敌人直接移除。
      // ★ 这是**性能**措施，不是玩法惩罚 —— 所以它不走 killEnemy（不给击杀数、不掉宝石、
      //   不出死亡动画）。玩家把它甩掉的那一瞬间，它本来就已经在屏幕外 900px 了。
      //   判据用**与玩家的距离**而不是世界坐标：无限场里没有任何固定的"远"。
      // ★ 位置放在 frozen 判定之前：冻住的怪如果被甩开也得回收，否则会永久占着数组。
      if (d > ARENA.CULL_DIST) { e.dead = true; continue; }
      // 霜环：冻住的敌人不移动、也不啃你（冻住了就是冻住了，不是"减速"）。
      // 判定放在移动之前 —— 先走一步再判，会出现"冻住的怪还挪了最后一格"。
      if (e.frozen > 0) {
        e.frozen -= dt;
        // 阶段 5 · B2 寒潮（疾风行者）：解冻的**那一刻**挂上残留减速 ——
        //   "冻完了不是马上恢复"，把"拉开距离"从一次性动作变成可持续的拉扯。
        //   ★ 只在跨过 0 的那一帧赋一次值；之后再冻就是新的一条，互不叠加成越来越慢。
        if (e.frozen <= 0) this._applyChill(e);
        continue;
      }
      // 阶段 5 · B2 破阵（流浪者）：定身 —— 完全不动、也不啃你。
      // 和冻结的区别：冻结期间接触伤害直接不结算，定身同样如此，但两者**来源不同**
      // （技能 vs 技能变体），分开计时才能各自到期、不会因为互相覆盖而"提前解冻"。
      if (e.stun > 0) { e.stun = Math.max(0, e.stun - dt); continue; }
      // 阶段 5 · B2 减速：残余寒意 / 地裂减速场，统一在这一帧折算成一个系数。
      if (e.slowT > 0) { e.slowT = Math.max(0, e.slowT - dt); if (e.slowT === 0) e.slowK = 1; }
      // 阶段 4-1：远程怪走的是另一套行为（保持距离 + 绕行 + 点射），见 stepRanged。
      // 近战怪仍是"直线扑脸"——两种压力的手感必须不同，否则"远程"只是换个皮。
      if (e.kind === 'ranged') { this.stepRanged(e, dx / d, dy / d, d, dt); continue; }
      // 阶段 4-4：Boss 走自己的节拍（缓慢追踪 + 冲锋 + 召唤），普通怪仍是"直线扑脸"。
      // ★ 放在这里而不是 `continue`：Boss 也要参与**下面的接触判定**（它的接触伤害是 3 倍）。
      if (isBossKind(e.kind)) this.stepBoss(e, dx / d, dy / d, d, dt);
      else {
        const v = this._effSpeed(e) * dt;
        e.x += (dx / d) * v;
        e.y += (dy / d) * v;
      }
      if (d < this.player.r + e.r) {
        // 阶段 4-4：Boss **撞上来不自爆**（它是个血条，不是一次性的），但要加冷却 ——
        //   否则贴上玩家后每帧结算一次 3 倍接触伤害，那是判定错误而不是"高伤害"。
        if (isBossKind(e.kind)) {
          if (e.touchCd <= 0 && !contactHit) {
            this.damagePlayer(e.contact);
            contactHit = true;
            e.touchCd = ARENA.BOSS_TOUCH_CD;
          }
          continue;
        }
        if (!contactHit) { this.damagePlayer(e.contact); contactHit = true; } // 同帧合并，见循环头的注释
        // 阶段 3「反伤」被动：撞你的敌人也吃伤害。反伤致死 → 走正常击杀（给宝石/计数）；
        // 否则这只怪"撞上来"本就该消失（只给视觉死亡动画，不改经济）。两种分支互斥，
        // 避免同一只怪被 killEnemy + addDeath 各结算一次。
        // 阶段 4-7：反伤走统一伤害入口（护盾也会吸收反伤）。
        // 致死 → 正常经济；未致死 → 这只怪"撞上来本就该消失"（只给视觉死亡动画，不改经济）。
        if (this.thorn > 0) {
          const killed = this.applyHit(e, this.thorn, null, false, 'thorn');
          if (!killed) { e.dead = true; if (!this.reduced) this.addDeath(e, null); }
        } else {
          e.dead = true;
          if (!this.reduced) this.addDeath(e, null);
        }
      }
    }
    this.enemies = this.enemies.filter((e) => !e.dead);
    // 阶段 4-4：Boss 若被 CULL 掉（玩家一路狂奔把它甩出 1500px）也要放行下一个 ——
    //   否则 bossRef 会一直指着一只已经不在场上的怪，"没死不刷下一个"变成永久卡住。
    if (this.bossRef && this.bossRef.dead) this.bossRef = null;

    // ── 敌方子弹（阶段 4-1 远程精英）──
    // 世界坐标直线飞行；碰到玩家即消（不穿透），命中走 damagePlayer（所以闪现无敌期间
    // 会"穿过"子弹 —— 与近战接触完全同一口径，不额外发明规则）。
    // 回收判据与敌人一致：离玩家超过 CULL_DIST 就丢掉（无限场里它已经不可能再回来了）。
    for (const b of this.bullets) {
      b.x += b.vx * dt;
      b.y += b.vy * dt;
      const dx = b.x - this.player.x, dy = b.y - this.player.y;
      const rr = this.player.r + b.r;
      if (dx * dx + dy * dy <= rr * rr) {
        this.damagePlayer(b.dmg);
        b.dead = true;
        this.bulletHits += 1;   // 统计口径（阶段 4-1.1）：弹命中玩家的次数
      }
    }
    const bc2 = ARENA.CULL_DIST * ARENA.CULL_DIST;
    this.bullets = this.bullets.filter((b) => {
      if (b.dead) return false;
      const dx = b.x - this.player.x, dy = b.y - this.player.y;
      return dx * dx + dy * dy <= bc2;
    });

    // ── 宝箱（spec §5）──
    this.chestTimer -= dt;
    if (this.chestTimer <= 0) {
      this.spawnChest();
      this.chestTimer = ARENA.CHEST_EVERY; // 满场时也要重置计时，否则下一帧会连刷
    }
    for (const ch of this.chests) {
      ch.t += dt;
      const dx = ch.x - this.player.x, dy = ch.y - this.player.y;
      const rr = this.player.r + ch.r + 8;
      if (dx * dx + dy * dy <= rr * rr) this.openChest(ch); // 走近自动开
    }
    this.chests = this.chests.filter((ch) => !ch.dead);

    // ── 经验宝石：吸附 + 走过即捡 ── ──
    // 为什么要吸附：宝石半径 4px，玩家 150px/s、单帧位移 2.5px，要求"精确踩中"手感很差
    //（尤其触屏，指尖会挡住宝石）。进入磁吸圈后宝石自己飞向玩家，符合"走过即捡"。
    const magR = this.magnet * this.magnetMul;   // 阶段 4-13：磁暴期放大磁吸半径（纯增益）
    const mag2 = magR * magR;
    for (const g of this.gems) {
      // ★ 阶段 4-3：宝石的"弹出"是**纯视觉偏移**，不参与拾取判定（见 killEnemy 的注释）。
      //   这里只推进它的计时器 —— 下面吸附/拾取用到的 x/y 与阶段 4-1 完全一致，
      //   所以"弹出"不会削经验收入（实测：照字面把它做成真实位移会削掉一整档血量）。
      if (g.pop < ARENA.GEM_POP_T) g.pop += dt;
      let dx = this.player.x - g.x, dy = this.player.y - g.y;
      let d2 = dx * dx + dy * dy;
      if (d2 < mag2 && d2 > 1e-6) {
        const d = Math.sqrt(d2);
        const pull = Math.min(d, ARENA.GEM_PULL * dt); // dt 驱动，与帧率解耦
        g.x += (dx / d) * pull;
        g.y += (dy / d) * pull;
        dx = this.player.x - g.x; dy = this.player.y - g.y; d2 = dx * dx + dy * dy;
      }
      const rr = (this.player.r + g.r + 2) * this.magnetMul;   // 阶段 4-13：磁暴期放大拾取半径（纯增益）
      if (d2 < rr * rr) {
        this.gainXp(g.xp * this.goldMul);   // 阶段 4-12：黄金时段经验 ×GOLD_MUL（goldMul 默认 1）
        if (!this.reduced) this.burst(g.x, g.y, COLOR.gem, 4, null, 0);   // 阶段 4-10：拾取微光（legacyN=0，纯表现）
        g.dead = true;
      }
    }
    this.gems = this.gems.filter((g) => !g.dead);

    // ── 心心（阶段 4-7.x：击杀掉落，回血）──
    // 弱磁吸：只有靠近的心心会被吸过来；碰触即回血，过期消失（防塞满）。
    for (const h of this.hearts) {
      if (h.pop < ARENA.HEART_POP_T) h.pop += dt;
      h.life -= dt;
      if (h.life <= 0) { h.dead = true; continue; }
      const dx = this.player.x - h.x, dy = this.player.y - h.y;
      const d2 = dx * dx + dy * dy;
      const mag2 = ARENA.HEART_PULL * ARENA.HEART_PULL * this.magnetMul * this.magnetMul;   // 阶段 4-13：磁暴期放大磁吸半径
      if (d2 < mag2 && d2 > 1e-6) {
        const d = Math.sqrt(d2);
        const pull = Math.min(d, ARENA.HEART_PULL * dt);
        h.x += (dx / d) * pull; h.y += (dy / d) * pull;
      }
      const rr = (this.player.r + h.r) * this.magnetMul;   // 阶段 4-13：磁暴期放大拾取半径（纯增益）
      if (dx * dx + dy * dy < rr * rr) {
        this.healPlayer(ARENA.HEART_HEAL);
        if (!this.reduced) this.burst(h.x, h.y, COLOR.good, 8, null, 0);   // 阶段 4-10：回血绿光
        h.dead = true;
      }
    }
    this.hearts = this.hearts.filter((h) => !h.dead);

    // ── 粒子衰减 ──
    for (const pa of this.particles) {
      pa.x += pa.vx * dt;
      pa.y += pa.vy * dt;
      pa.vy += 320 * dt;
      pa.vx *= 0.98;
      pa.life -= dt;
    }
    this.particles = this.particles.filter((pa) => pa.life > 0);

    // ── 飘字衰减（上飘改 ease-out） ──
    // 位置由 t 直接算（y0 − rise × easeOut(p)），而不是"每帧加一个固定位移"——后者是匀速，
    // 正是本节要消掉的线性感。用 f.max 而不是 f.life 当分母：life 每帧都在减，
    // 拿它做分母会把曲线压成非单调的（末段会往回跳）。
    for (const f of this.floaters) {
      f.t += dt;
      f.y = f.y0 - ARENA.FLOAT_RISE * easeOut(f.t / f.max);
      f.life -= dt;
    }
    this.floaters = this.floaters.filter((f) => f.life > 0);

    // ── 短特效衰减（光束 / 霜环 / 残影 / 开箱；纯视觉）──
    for (const f of this.fx) f.t += dt;
    this.fx = this.fx.filter((f) => f.t < f.life);

    // ── 死亡动画衰减（纯视觉，不参与任何判定）── ──
    for (const d of this.deaths) d.t += dt;
    this.deaths = this.deaths.filter((d) => d.t < d.life);

    // ── 结算 ──
    if (this.hp <= 0) {
      this.hp = 0;
      this.done = true;
      this.survived = false;
      return;
    }
    if (this.time >= this.durationMs) {
      this.time = this.durationMs;
      this.done = true;
      this.survived = true;
      return;
    }

    // ── 阶段 7 · 精英波技能三选一兑现（每帧最多开一张，节流见 _flushEliteSkillDrop）──
    // ★ 刻意放在**两个结算判定之后**：它们各自 return，所以走到这里时 done 必为 false。
    //   放前面的话，同一帧被怪撞死（或打满 10 分钟）时会把选牌弹在"游戏已结束"之后 ——
    //   玩家看到一个点不动的弹窗，而 pendingUpgrade 又会永久卡住下一局的 fastForward。
    this._flushEliteSkillDrop();
  }

  // ── 内部辅助 ──

  /** 敌人血量随时间的成长系数（t 秒时 ×1.15^(t/60)）。抽成方法是为了让测试与模拟器
   *  能拿**同一个公式**去核对 spawnEnemy 真的把系数冻进了出生属性。 */
  // 阶段 5.3：全局经验收入倍率（**只作用于敌人掉落的经验值**）。
  //   写成纯函数（不读运行时状态）是为了能直接单测：前 3 分钟恒 1、之后线性增长。
  //   ⚠ 这是**线性**增长，而门槛是 g^lv **指数**增长 ⟹ 收入永远"追但追得吃力"，
  //   正是我们要的手感；若改成指数，后期升级会失控（1.17 那轮的教训）。
  expMulAt(sec = this.elapsed) {
    const m = sec / 60 - ARENA.EXP_GROWTH_FROM_MIN;
    return m > 0 ? 1 + ARENA.EXP_GROWTH_PER_MIN * m : 1;
  }

  hpScale(sec = this.elapsed) { return Math.pow(ARENA.HP_GROWTH_PER_MIN, sec / 60); }
  /** 接触伤害随时间的成长系数（t 秒时 ×(1 + t/120)）。 */
  contactScale(sec = this.elapsed) { return Math.pow(ARENA.CONTACT_GROWTH_MUL, sec / ARENA.CONTACT_GROWTH_SEC); }
  /** 敌人速度随时间的**追赶**系数（t 秒时 ×(1 + t/180)，见 ENEMY_SPEED_RAMP_ON）。
   *  和上面两条一样抽成方法：让测试能拿**同一个公式**核对 spawnEnemy 真的把它冻进了出生属性。
   *  ⚠ 开关默认关闭 —— 打开它会把"跑满 10 分钟"从 16/16 打下去（逐档证据见常量注释）。 */
  speedScale(sec = this.elapsed) {
    return ARENA.ENEMY_SPEED_RAMP_ON ? 1 + sec / ARENA.ENEMY_SPEED_RAMP_SEC : 1;
  }

  /**
   * 出生点相对玩家的偏移：保证落在**视口矩形之外**（阶段 4-1.2 加的几何修正）。
   *
   * 为什么需要：出生环是按"半径"定义的，而竖屏的半宽/半高差一倍多（195 vs 422）。
   * 半径 300~442 段在靠近正上/正下时其实**在屏幕内** —— 怪会在玩家眼皮底下凭空出现。
   * 做法：落在"矩形 + SPAWN_MARGIN"之内时，沿**原方向**推到矩形外。
   * ★ 不重掷 rng：方向与距离抖动全部保留，只是把长度拉长到"刚好出画"。
   *   因此"同种子同结果"不变，且这条修正不会平移任何随机流。
   * ★★ 阶段 4-8：环外径收到 420 之后，它**小于半高 442** ⟹ 竖直方向的出生点**全部**
   *   由这条修正决定，落点固定在"屏幕边缘外 20px"。这正是 spec §4-8 二想要的
   *   "怪从屏幕边缘刚能看见的地方刷"，但也意味着**环带在竖直方向不再约束距离**
   *   （详见 SPAWN_RING_MAX 的注释与 §10 的按角度不变式）。
   */
  spawnOffset(ang, dist) {
    let dx = Math.cos(ang) * dist, dy = Math.sin(ang) * dist;
    const hw = this.w / 2 + ARENA.SPAWN_MARGIN, hh = this.h / 2 + ARENA.SPAWN_MARGIN;
    if (Math.abs(dx) < hw && Math.abs(dy) < hh) {
      const kx = Math.abs(dx) > 1e-6 ? hw / Math.abs(dx) : Infinity;
      const ky = Math.abs(dy) > 1e-6 ? hh / Math.abs(dy) : Infinity;
      const k = Math.min(kx, ky);   // 取"最先出矩形"的那条边
      dx *= k; dy *= k;
    }
    return { dx, dy };
  }

  /**
   * 在玩家周围的环形上随机出生一只当前波次允许的敌人。
   * 阶段 4-1：四边 → 圆环（无限场没有边）；阶段 4-1.2：环从 750~1000 收到 380~550；
   * 阶段 4-8：再收到 **300~420**（等于把"在途"再砍掉一截，见 SPAWN_RING_MAX 的注释），
   * 并过一道 spawnOffset() 保证"在视口外"（理由见那两处常量注释）。
   * 精英判定也在这里 —— 它是**品质**，和种类（kind）正交，所以放在 kind 抽完之后。
   *
   * @param {number|null} ringMin 出生内径覆盖（null = 按种类选默认环）；围堵用它传 250
   * @param {number|null} ringMax 出生外径覆盖
   * @param {{x:number,y:number}|null} at 出生中心（null = 玩家；Boss 召唤传 Boss 自己）。
   *   ★ 给了 at 就**跳过 spawnOffset**：那条修正是"别在玩家眼皮底下凭空出现"，
   *     而召唤物本来就该出现在 Boss 身边（玩家正看着 Boss），推出视口反而就没有召唤感了。
   */
  /**
   * 构建一只敌人的完整对象（类型表 × 时间成长 × 精英品质 × 护盾）。
   * 抽成方法：spawnEnemy / 分裂 / 群冲 / 开局齐射 都共用同一套"出生时定死数值"的逻辑
   * （成长冻在出生时刻，理由见 hpScale 的注释 —— 否则同一只怪的血上限会随游戏时间漂移）。
   */
  makeEnemy(kind, x, y, sec, elite, ang = null) {
    const t = ENEMY_TYPES[kind];
    const hp = t.hp * this.hpScale(sec) * (elite ? ARENA.ELITE_HP_MUL : 1);
    return {
      kind,
      x, y,
      r: t.r * (elite ? ARENA.ELITE_SIZE_MUL : 1),
      // ★ 阶段 4-1.2：速度**开始**随时间成长（追赶走位中的玩家），封顶在 ENEMY_SPEED_CAP。
      speed: Math.min(t.speed * this.speedScale(sec), ARENA.ENEMY_SPEED_CAP),
      hp, maxHp: hp,   // maxHp 用于 sim 的"怪血硬度"曲线（与当前 hp 同步冻在出生时刻）
      contact: t.contact * this.contactScale(sec) * (elite ? ARENA.ELITE_CONTACT_MUL : 1),
      xp: t.xp * (elite ? ARENA.ELITE_XP_MUL : 1),
      elite, dead: false, frozen: 0, hitT: 0, appear: 0,
      // 阶段 5 · B2：三个技能变体共用的 debuff 字段。默认恒等（0 / 0 / 1），
      //   没配 perks 的职业一个都不会被读到 ⟹ 零行为变化。
      stun: 0, slowT: 0, slowK: 1,
      // 远程怪绕行方向 + 首发射击延迟由出生角决定（不用额外 rng，避免平移随机流）。
      spin: kind === 'ranged' ? 1 : 0,
      fireT: (kind === 'ranged' && ang != null)
        ? ARENA.RANGED_FIRE_MIN + (ang / TAU) * (ARENA.RANGED_FIRE_MAX - ARENA.RANGED_FIRE_MIN)
        : 0,
      // 阶段 4-7：护盾怪带 SHIELD_HITS 层护盾，破盾前吸收伤害（见 applyHit）。
      shield: kind === 'shield' ? ARENA.SHIELD_HITS : 0,
    };
  }

  /** 阶段 4-7：开局齐射——先放 3 只（normal×2 + fast×1），保证"前 10 秒有怪可打"。
   *  ★ 中/后期密度曲线**完全不动**（spawn 数值沿用 4-1 的已调表），只补开局这一段，
   *     既满足反馈"前期怪太少"，又不破坏"跑满 10 分钟"的存活口径。 */
  openingSalvo() {
    const kinds = ['normal', 'normal', 'fast'];
    for (const k of kinds) {
      if (this.enemies.length >= ARENA.MAX_ENEMIES) break;
      const a = this.rng.next() * TAU;
      const off = this.spawnOffset(a, ARENA.SPAWN_RING_MIN + this.rng.next() * (ARENA.SPAWN_RING_MAX - ARENA.SPAWN_RING_MIN));
      this.enemies.push(this.makeEnemy(k, this.player.x + off.dx, this.player.y + off.dy, 0, false));
      this.spawned += 1;
      this.kindCounts[k] = (this.kindCounts[k] || 0) + 1;
    }
  }

  spawnEnemy(ringMin = null, ringMax = null, at = null) {
    // ★★ 阶段 4-8：**上限守卫必须长在这里，而不是只长在调用方**。
    //   调用方的 `length < MAX_ENEMIES` 只能保证"**调用之前**没满"，而一次调用并不等于一只：
    //   群冲怪（swarm）一次权重命中就紧簇 push **3~5 只**（见下），于是"刚好卡在 219"时
    //   一次调用就能冲出上限 4 只。裂片（splitter 的死亡产物）更是完全不走这条路。
    //   实测（16 局官方 sim）：峰值同屏 **221 > 220**，而 220 是本项目写死的硬红线
    //   （见 MAX_ENEMIES 注释、以及单测里的不变量断言），且历史读数里从没越过。
    //   ⟹ 把守卫放到"入数组的门口"，任何调用路径都逃不掉（与"不刷，而不是先刷再被丢回来"
    //     同一个口径：**不生成**，不是生成了再丢）。
    if (this.enemies.length >= ARENA.MAX_ENEMIES) return null;
    const wave = this.wave();
    const kinds = Object.keys(wave.w);
    const kind = this.rng.weighted(kinds, (k) => wave.w[k]);
    const t = ENEMY_TYPES[kind];
    // ★ rng 消耗顺序是确定性的（kind → 角度 → 距离 → 精英判定），
    //   "同种子同结果"因此依然成立；改动这个顺序等于换一批种子。
    const ang = this.rng.next() * TAU;
    // 出生环按**种类**分：阶段 4-8 起远程与近战统一到同一圈（300~420），围堵可整圈覆盖。
    const rMin = ringMin ?? (kind === 'ranged' ? ARENA.RANGED_SPAWN_RING_MIN : ARENA.SPAWN_RING_MIN);
    const rMax = ringMax ?? (kind === 'ranged' ? ARENA.RANGED_SPAWN_RING_MAX : ARENA.SPAWN_RING_MAX);
    const dist = rMin + this.rng.next() * (rMax - rMin);
    // 精英判定**永远消耗一次 rng**（哪怕这一只不可能成为精英）：让"消耗几次随机数"与种类解耦。
    const roll = this.rng.next();
    // 阶段 4-7：精英只在 2 分钟后出现（spec），且只对 normal/fast/tank 生效 ——
    // ranged / splitter / shield / swarm 是"机制怪"，叠精英会让数值口径失控。
    const elite = (kind === 'ranged' || kind === 'splitter' || kind === 'shield' || kind === 'swarm')
      ? false
      : (this.elapsed >= 120 && roll < ARENA.ELITE_CHANCE);
    const sec = this.elapsed;
    const cx = at ? at.x : this.player.x;
    const cy = at ? at.y : this.player.y;
    // 阶段 4-7：群冲怪成簇刷——一次权重命中，在出生环上紧簇地放出 3~5 只（数量压迫感）。
    // 每只仍在自己的环带上（不破坏"出生点必须在视口外"的不变量），只是角度紧簇。
    if (kind === 'swarm') {
      const n = ARENA.SWARM_MIN + Math.floor(this.rng.next() * (ARENA.SWARM_MAX - ARENA.SWARM_MIN + 1));
      for (let j = 0; j < n; j++) {
        if (this.enemies.length >= ARENA.MAX_ENEMIES) break; // 簇内也要逐只判（见函数头）
        const a = ang + (this.rng.next() - 0.5) * 0.5;            // 紧簇角度（±0.25 rad）
        const dd = rMin + this.rng.next() * (rMax - rMin);        // 各自仍在环带上
        const o2 = at ? { dx: Math.cos(a) * dd, dy: Math.sin(a) * dd } : this.spawnOffset(a, dd);
        this.enemies.push(this.makeEnemy('swarm', cx + o2.dx, cy + o2.dy, sec, false));
        this.spawned += 1;
        this.kindCounts.swarm = (this.kindCounts.swarm || 0) + 1;
      }
      return kind;
    }
    const off = at ? { dx: Math.cos(ang) * dist, dy: Math.sin(ang) * dist } : this.spawnOffset(ang, dist);
    this.enemies.push(this.makeEnemy(kind, cx + off.dx, cy + off.dy, sec, elite, ang));
    this.spawned += 1;
    if (elite) this.eliteSpawned += 1;
    if (kind === 'ranged') this.rangedSpawned += 1;
    this.kindCounts[kind] = (this.kindCounts[kind] || 0) + 1;
    return kind;
  }

  /**
   * 阶段 4-1：远程精英的一拍 —— **保持距离 + 绕行 + 点射**。
   * 它不是"追着你咬"，而是"站在你打得到、又不敢让你贴近的地方点你"；
   * 于是玩家的解法从"绕后/推开"变成"主动冲上去先干掉它" —— 两种压力才真的不同。
   * 不消耗 rng 的帧（只有开火那一帧抽间隔），所以冻结/远离时它对确定性流零影响。
   */
  stepRanged(e, ux, uy, d, dt) {
    const keep = ARENA.RANGED_KEEP_DIST, band = ARENA.RANGED_BAND;
    // 径向分量：太远则进、太近则退、**在死区内为 0**（死区是防抖的关键，见常量注释）
    let rx = 0, ry = 0;
    if (d > keep + band) { rx = ux; ry = uy; }
    else if (d < keep - band) { rx = -ux; ry = -uy; }
    // 切向分量：恒定绕行。方向在出生时定死，否则一群射手各绕一半会互相穿插成"麻花"。
    const tx = -uy * e.spin, ty = ux * e.spin;
    const sv = this._effSpeed(e) * dt;   // 阶段 5 · B2：同样地吃减速/控场
    e.x += (rx + tx * ARENA.RANGED_STRAFE) * sv;
    e.y += (ry + ty * ARENA.RANGED_STRAFE) * sv;

    // 点射：每次开火后**重新抽**间隔（固定节拍会让弹幕听起来像节拍器，
    // 而且十几只同频之后会周期性聚成"弹墙"）。只在射程内开火。
    e.fireT -= dt;
    if (e.fireT <= 0) {
      e.fireT = ARENA.RANGED_FIRE_MIN + this.rng.next() * (ARENA.RANGED_FIRE_MAX - ARENA.RANGED_FIRE_MIN);
      if (d <= ARENA.RANGED_FIRE_RANGE) this.fireBullet(e, ux, uy);
    }
  }

  /** 射一颗直线弹：方向 = 朝**开火那一刻**玩家的位置（不预判）。
   *  ★ "不预判"是刻意的：预判会逼玩家做数学题，不预判则"横移就躲得开"——
   *    走位因此是唯一且直观的解法，这正是这个敌人存在的理由。 */
  fireBullet(e, ux, uy) {
    if (this.bullets.length >= ARENA.MAX_BULLETS) this.bullets.shift(); // 与粒子/宝石同策略：保最新
    this.bullets.push({
      // 从身体边缘出膛而不是从中心：从中心发射时，贴脸射手的弹会"凭空出现在玩家身上"
      x: e.x + ux * (e.r + 4), y: e.y + uy * (e.r + 4),
      vx: ux * ARENA.BULLET_SPEED, vy: uy * ARENA.BULLET_SPEED,
      r: ARENA.BULLET_R, dmg: ARENA.BULLET_DMG, dead: false,
    });
    this.bulletsFired += 1;
  }

  /**
   * 射程内最近的敌人（maxRange 省略则不限射程）。
   * ★ 阶段 4-4：**Boss 优先**。 ★★ 这不是"给玩家开挂"，而是修一个实测出来的失效：
   *   后期同屏 200 只的时候，"最近的敌人"几乎永远轮不到 Boss —— 于是 Boss 变成一个
   *   在远处散步的背景板（实测 Boss2 有 8/16 局**整局没挨过一下**，站场 90 秒后随结算消失）。
   *   让索敌优先咬住 Boss，Boss 才真的是"这一局的一个坎"，而不是多出来的一只大怪。
   */
  nearestEnemy(maxRange = Infinity) {
    let best = null, bd = Infinity, boss = null, bossD = Infinity;
    for (const e of this.enemies) {
      if (e.dead) continue;
      const d = dist(e, this.player);
      if (d > maxRange) continue;
      if (isBossKind(e.kind)) { if (d < bossD) { bossD = d; boss = e; } }
      else if (d < bd) { bd = d; best = e; }
    }
    return boss || best;
  }

  /**
   * 自动攻击一次：射出 this.shots 条弹道。
   * 分配策略是「优先各打一个不同的最近敌人，目标不够时余下的弹道围绕主目标散布」——
   * 而不是"全部朝主目标散开"。单目标时后者会让多条弹道一起打空，
   * 于是「投射物 +1」这条升级在怪少的时候反而感觉不出收益。
   * 返回是否成功开火（射程内无目标则不开火，也就不会白白消耗攻速节拍）。
   */
  fireVolley() {
    const R = ARENA.ATTACK_RANGE, R2 = R * R;
    const cand = [];
    for (const e of this.enemies) {
      if (e.dead) continue;
      const dx = e.x - this.player.x, dy = e.y - this.player.y;
      const d2 = dx * dx + dy * dy;
      if (d2 <= R2) cand.push({ e, d2 });
    }
    if (!cand.length) return false;
    // 阶段 4-4：Boss 排到最前（拿到第 1 条弹道），其余仍按距离 —— 理由见 nearestEnemy 的注释
    cand.sort((a, b) => {
      const ab = isBossKind(a.e.kind) ? 0 : 1, bb = isBossKind(b.e.kind) ? 0 : 1;
      return ab !== bb ? ab - bb : a.d2 - b.d2;
    });

    const n = Math.max(1, this.shots);
    const base = cand[0].e;
    const baseAng = Math.atan2(base.y - this.player.y, base.x - this.player.x);
    const px = this.player.x, py = this.player.y;
    const extras = Math.max(0, n - cand.length); // 目标不够分的余量弹道
    for (let k = 0; k < n; k++) {
      let ang;
      if (k < cand.length) {
        const t = cand[k].e;
        ang = Math.atan2(t.y - py, t.x - px);
      } else {
        // 余量弹道以主目标方向为中心对称铺开。`extras === 1` 时也要偏开半格 ——
        // 否则它和第 1 条弹道完全重叠，玩家会以为"投射物 +1"这条升级没生效。
        const i = k - cand.length;
        const off = extras === 1 ? ARENA.SHOT_SPREAD * 0.5 : (i - (extras - 1) / 2) * ARENA.SHOT_SPREAD;
        ang = baseAng + off;
      }
      // ★ 阶段 5 · B3：`p.src` 是伤亡归因的唯一凭据 —— 不写的话这发弹的击杀会落进
      //   'other' 兜底桶（sim 会报"有击杀绕过了具名来源"）。
      //   `pierce + pierceN` 是流浪者「连珠」的专属形态；没有这条 perks 的职业恒不开。
      const pp = {
        x: px, y: py,
        vx: Math.cos(ang) * this.projSpeed,
        vy: Math.sin(ang) * this.projSpeed,
        r: 3, life: 2.5, dead: false, src: 'projectile',
      };
      if (this.projPierce > 0) { pp.pierce = true; pp.hits = []; pp.pierceN = this.projPierce; }
      this.projectiles.push(pp);
    }
    return true;
  }

  /**
   * 击杀结算。`knock` 是**死亡动画**的外飞方向（`{ux, uy, dist}`，可省略）：
   * 投射物击杀顺着弹道飞、冲击波击杀向外炸开、撞人自爆不给方向。它只影响视觉 ——
   * 宝石落点、击杀计数与飘字完全不受它影响。
   */
  /**
   * 阶段 4-7：统一伤害入口。所有「对敌结算伤害」的调用点（投射物 / 环绕刃 / 直斩 /
   * 闪现 / 反伤 / 冲击波）都走这里，保证护盾吸收、击杀、击退、命中读数**一套口径**：
   *   · 护盾怪（e.shield > 0）先吸收一层护盾，本拍不扣血、不致死 —— 破盾前不能一波带走。
   *   · 否则扣血；致死走 killEnemy（正常给宝石 / 计数 / 碎屑），未致死给命中飘字 + 闪白。
   *   · knock：{ ux, uy, dist, live? } 立即把敌人位移 dist 像素。
   *       - live 非 false 时存活者也位移（冲击波"弹推开"的主效果）；
   *       - 致死的敌人位移 dist 后，死亡碎屑再额外沿同方向飘 DEATH_DRIFT（见 killEnemy 的 addDeath）。
   *       - 武器命中传 { ..., live: false }：碎屑方向照旧、但不推活怪（武器不是击退技能）。
   *   · hit：是否计入命中统计（投射物要，闪现/反伤不要）。
   * ★ 阶段 5：`e.hp -= amount * this.gDmgMul` —— 全局伤害系数在**这里**一次性结算，
   *   因为只有这个入口能保证"每一笔对敌伤害"都吃到它。各武器各自记着自己的伤害数
   *   （this.dmg 是投射物的、c.sword.dmg 是剑的），逐个去乘必然会漏 —— 漏的那个就是
   *   "明明点了增伤，手上这把武器却没变强"的那类 bug。默认恒为 1 ⟹ 对现有局 bit 级零影响。
   * 返回是否致死（killEnemy 已结算）。
   */
  applyHit(e, amount, knock = null, hit = false, src = 'other') {
    if (e.dead) return false;
    if (e.shield > 0) {
      e.shield -= 1;
      if (hit) this.hits += 1;
      this.flashHit(e);
      // 破盾那一刻给个明确读数（护盾环在渲染层随层数变淡，这里补一行字）。
      if (e.shield === 0 && !this.reduced) {
        this.floatText(e.x, e.y - e.r, '破盾', COLOR.shield, ARENA.FLOAT_LIFE, false);
        this.burst(e.x, e.y, COLOR.shield, 12, null, 0);   // 阶段 4-10：破盾青环碎屑（legacyN=0 ⟹ 只走 _frand，不碰主 rng）
      }
      return false; // 护盾吸收：不扣血、不致死
    }
    const _before = e.hp;
    // ── 阶段 7：伤害削减（散射/贯穿）→ 暴击（狂怒/属性树）→ 最终伤害 ──
    // ★ ★ 第一步就把 gDmgMul 乘进去：全局伤害乘区（阶段 5.1 标定）必须在**每一个**
    //   对敌伤害入口生效，漏在这里等于"点了增伤但伤害没变"——项目踩过两次的静默失效。
    //   顺序：gDmgMul → dmgCut → crit。gDmgMul 放最前是因为它是"所有来源"的公共乘区，
    //   放在削减之后会让"散射 -15%"变成"被增伤抵消掉的 -15%"（语义漂移）。
    let amount_eff = amount * this.gDmgMul * (1 - this.dmgCut);
    // ★ 确定性周期暴击（零 rng，理由见 content.js 狂怒的三条纪律）：
    //   累加"已造成的伤害"，每满 1/critRate 点触发一次 ×CRIT_DMG_MUL。
    //   critRate=0 ⟹ 整个分支恒不进入 ⟹ 与阶段 6 逐比特相同（回归护栏的前提）。
    let crit = false;
    if (this.critRate > 0) {
      this.critAcc += amount_eff;
      const every = 1 / this.critRate;      // 每多少伤害触发一次
      if (this.critAcc >= every) {
        crit = true;
        this.critAcc -= every;              // ★ 取模而不是清零：否则小额伤害会让暴击永久累积不到阈值
      }
    }
    const dmg_eff = crit ? amount_eff * this.critMul : amount_eff;
    e.hp -= dmg_eff;
    if (this.dmgDealt[src] != null) this.dmgDealt[src] += Math.min(dmg_eff, _before);
    if (hit) this.hits += 1;
    const killed = e.hp <= 0;
    // ★ 吸血（续航）的口径分工 —— **一次伤害只回一次血**，这是本条最容易写错的地方：
    //   · 目标**没死**：在这里按这一笔的实际伤害回（它不会再进 killEnemy）。
    //   · 目标**死了**：由 killEnemy 统一回（它拿得到完整的 dmg 参数，且所有来源的击杀都走那里）。
    //   ⟹ 若两处都回，等于"杀掉的怪回双倍血"，直接把生存曲线抬穿。
    //     `!killed` 这个守卫就是互斥点（早先版本把它漏了，是在 TDZ 里静默拿到 undefined）。
    if (this.lifesteal > 0 && !killed) {
      const dealt = Math.min(dmg_eff, _before);
      if (dealt > 0) this.healPlayer(dealt * this.lifesteal);
    }
    // 存活者 / 死亡者都先按 knock 位移（死亡者的碎屑再叠加 DEATH_DRIFT，见 killEnemy）。
    if (knock && knock.live !== false) { e.x += knock.ux * knock.dist; e.y += knock.uy * knock.dist; }
    if (killed) {
      this.killEnemy(e, amount, knock ? { ux: knock.ux, uy: knock.uy, dist: ARENA.DEATH_DRIFT } : null, src);
      return true;
    }
    this.floatText(e.x, e.y - e.r, `-${Math.round(dmg_eff)}`, crit ? COLOR.gold : COLOR.paper, ARENA.FLOAT_LIFE, crit || dmg_eff >= ARENA.FLOAT_BIG_DMG);
    this.flashHit(e);
    return false;
  }

  killEnemy(e, dmg = this.dmg, knock = null, src = 'other') {
    e.dead = true;
    this.kills += 1;
    // 阶段 6-4：击杀掉落「魂火」（与 gems=xperience 完全独立的货币；只喂商店消费口径，
    //   不进任何升级/成长/难度判定，所以不影响「同种子同结果」与全部平衡门禁）。
    // ★ 阶段 7：贪婪装备 → goldMul2（>1 时按比例加成）。goldMul2 默认 1 ⟹ 乘 1 等于无操作，
    //   这是"新增乘区但默认恒等"的写法—— 不需要在下游任何地方加分支。
    this.soulfire += ARENA.SOULFIRE_PER_KILL * this.goldMul2;
    // 阶段 7 · 吸血（续航）的**击杀那一份**：applyHit 里只回"没打死"的那部分伤害，
    //   打死的那一份在这里按 dmg 统一回 ⟹ 一次伤害恰好回一次（分工理由见 applyHit 的注释）。
    if (this.lifesteal > 0) this.healPlayer(dmg * this.gDmgMul * this.lifesteal);
    // 阶段 4-9：按来源记账（只统计，不参与任何判定）。未知来源落 'other' —— 而 'other'
    // 在测试里必须恒为 0，所以"新加了一条伤害路径却忘了标来源"会被当场抓到。
    this.killSrc[src] = (this.killSrc[src] || 0) + 1;
    // 阶段 4-3：连杀累加。★ 只喂显示（字号/颜色），不参与任何伤害/经济判定。
    this.combo += 1;
    this.comboT = ARENA.COMBO_WINDOW;
    if (this.combo > this.comboBest) this.comboBest = this.combo;
    this._checkMilestones();   // 击杀型里程碑（100 / 300 / 500 / 1000 只）
    // 阶段 4-1：宝石按**世界坐标**落在敌人倒下的地方，不再夹回场地。
    // ★ 旧代码夹回 6..w-6 的前提是"敌人从四边屏幕外刷出、可能刚露头就被打死，
    //   落宝会掉在玩家走不到的场外"。无限场里这个前提消失了（处处可达），
    //   夹回去反而会**改变玩法**：把远处的战利品硬拽到玩家身边，等于凭空放大磁吸。
    //   距离合理性由别处保证：射程 300 ≤ 磁吸 280 + 玩家的移动，掉落点始终可回收。
    // 精英掉 3 颗：按固定角度铺开。**不用 rng** —— 掉落物的排布是纯表现，
    // 不该消耗确定性随机流（消耗了就会让"同种子同结果"多一条隐形的耦合）。
    const nDrops = e.elite ? ARENA.ELITE_GEM_DROPS : 1;
    // 阶段 7 · 精英波怪击杀 → 兑现一次技能三选一（spec「击杀必掉技能选择」）。
    // ★ 判据是 `e.eliteWave`（这条调度刷出来的）而不是 `e.elite`：随机刷出的近战精英
    //   也带 elite 标记，若按它判定，"清场"就等于白嫖一串三选一，机制直接失效。
    if (e.eliteWave) this._grantEliteSkillDrop();

    for (let i = 0; i < nDrops; i++) {
      if (this.gems.length >= ARENA.MAX_GEMS) this.gems.shift();
      // ★ 阶段 4-3：弹出方向用**黄金角轮转**（不是 rng）—— 均匀铺开、且不消耗确定性随机流。
      //   弹出距离同样由这个角导出（frac ∈ [0,1) 均匀分布），所以距离也天然铺满 80~150px。
      // 落点本身沿用老口径（精英 3 连掉按固定角度铺开 11px；单颗就在尸体上）——
      // 这一段是**玩法**（决定宝石在哪），不是表现，所以不许跟着这次改造一起动。
      const a0 = (i / nDrops) * TAU + 0.6;
      const sp = nDrops > 1 ? 11 : 0;
      const gx = e.x + Math.cos(a0) * sp, gy = e.y + Math.sin(a0) * sp;
      // ★ 阶段 4-3：弹出方向用**黄金角轮转**（不是 rng）—— 均匀铺开、且不消耗确定性随机流。
      //   弹出距离同样由这个角导出（frac ∈ [0,1) 均匀分布），所以距离也天然铺满 80~150px。
      this._gemSpin = (this._gemSpin + 2.399963229728653) % TAU;
      const a = this._gemSpin;
      const dist = ARENA.GEM_POP_MIN + (ARENA.GEM_POP_MAX - ARENA.GEM_POP_MIN) * (a / TAU);
      let ox = Math.cos(a) * dist, oy = Math.sin(a) * dist;
      // ★★ 一条实测出来的硬修正：**"弹出"必须是视觉偏移，不能是真实位移**。
      //   第一版照字面做成了位移（且弹出期间不接磁吸）：16 局的"跑满"从 16/16 掉到 15/16、
      //   最低血量 70.7 → 39.4、最长升级空档 43.2s → 62.3s（破 45 红线）。
      //   根因：射程 340 处的击杀 + 150px 外弹 = 490px，而磁吸半径只有 280 ——
      //   那一段"弹出"把战利品直接推出了可回收范围，经验收入被削，玩家变弱后被磨死。
      //   ⟹ 弹出去的 80~150px 只写进 `ox/oy`（渲染层加成，见 _render 的宝石段），
      //     x/y 该在哪还在哪 ⟹ **吸附与拾取的口径逐字节不变**，但视觉上照样是
      //     "从尸体上蹦出来一小段，再被吸走"。
      //     偏移还会随"离玩家多近"缩回 0，所以宝石吸到身上时正好归位，不会凭空消失在旁边。
      if (ox * (e.x - this.player.x) + oy * (e.y - this.player.y) > 0) { ox = -ox; oy = -oy; }
      this.gems.push({
        x: gx, y: gy,
        ox, oy, pop: 0,
        // 阶段 5.3：敌人掉落的**经验值**乘收入倍率（只改数值，不改宝石数量）。
        //   空投 / 精英赏金走各自的 ARENA.SUPPLY_GEM_XP，不在这里，所以不受影响。
        r: 4, xp: e.xp * this.expMul, dead: false,
      });
    }
    // 阶段 4-7.x：心心掉落（回血，玩法增强）。
    // swarm/splitling 太小太密，掉了会满地心心、反而添乱 —— 这两种不掉。
    // ★ 用主 rng 决定掉不掉：killEnemy 不在 spawn 的确定性关键路径上（spawn 在 kill 之前
    //   已经把 rng 消耗完了），所以不影响"同种子同 spawn"；只改了 kill 之后的 rng 流，
    //   而 sim / 测试都不断言 kill 后的 rng 序列（见 spawnEnemy 的 rng 顺序注释）。
    if (e.kind !== 'swarm' && e.kind !== 'splitling' && this.dropRng.next() < ARENA.HEART_CHANCE) {
      if (this.hearts.length < ARENA.MAX_HEARTS) {
        this.hearts.push({ x: e.x, y: e.y, r: ARENA.HEART_R, pop: 0, life: ARENA.HEART_LIFE, dead: false });
        this.heartsDropped += 1;
      }
    }

    // 阶段 4-7：裂体怪（splitter）死亡 → 在原地裂成 SPLIT_CHILDREN 只裂片（splitling）。
    // ★ 走 makeEnemy 保证裂片也吃"出生时定死数值"的口径（与 spawnEnemy / 群冲一致），
    //   不消耗精英判定、不进 BOSS 序列、不进出生环（就在尸体处瞬间出现）。
    //   裂片小一圈、血薄、跑得快 ⟹ "越打越多、要控场"；计数进 kindCounts.splitling 供 sim 自证。
    if (e.kind === 'splitter') {
      // ★ 上限守卫同上：裂片在**尸体处**瞬间出现，不经过 spawnEnemy()，
      //   刷怪表/围堵/Boss 召唤那三处守卫一个都管不到它。
      //   用**硬上限**（不是 MAX − CLIMAX_SOFT_GAP）："越打越多"是裂体怪的识别度，
      //   不该在还没顶到硬顶时就开始打折。
      for (let s = 0; s < ARENA.SPLIT_CHILDREN; s++) {
        if (this.enemies.length >= ARENA.MAX_ENEMIES) break;
        const child = this.makeEnemy('splitling', e.x, e.y, this.elapsed, false);
        this.enemies.push(child);
        this.spawned += 1;
        this.kindCounts.splitling = (this.kindCounts.splitling || 0) + 1;
      }
    }

    // 大伤害飘字放大 1.5 倍并变色（spec 一-1）。
    // ★ 阶段 4-4：Boss 挨的每一刀都走**大字**（spec 三-2），不看伤害阈值 ——
    //   Boss 血条那么厚，玩家要靠飘字确认"我在真的打掉它"。
    const isBoss = isBossKind(e.kind);
    this.floatText(e.x, e.y - e.r, `-${dmg}`, COLOR.paper, ARENA.FLOAT_LIFE, isBoss || dmg >= ARENA.FLOAT_BIG_DMG);
    // ── 阶段 4-4：Boss 死亡结算（spec 三-3）──
    if (isBoss) {
      const b = BOSS_TYPES[e.kind];
      this.bossKills[b.idx] += 1;
      if (this.bossRef === e) this.bossRef = null;   // 放行下一个 Boss（"没死不刷下一个"靠这里）
      if (!this.reduced) this.burst(e.x, e.y, b.color, ARENA.BOSS_DEATH_PARTICLES);
      this.spawnChest({ x: e.x, y: e.y }, true);     // 必掉一个大金箱
      this.milestones.push({ text: `击杀 ${b.label}！`, t: 0, life: ARENA.MILE_FADE });
    }
    if (!this.reduced) {
      // 阶段 4-3：碎屑 4/7 → **8~12**（spec 一-2「爆 8~12 个对应颜色的粒子」）。
      // 精英固定吃满上限；普通怪在 8~12 之间抽（这一抽进 rng，但 burst 本来就在抽，
      //   所以"每只死都消耗随机数"这件事没有变化，不会平移已有的确定性口径）。
      const n = e.elite
        ? ARENA.BURST_MAX
        : ARENA.BURST_MIN + Math.floor(this._frand() * (ARENA.BURST_MAX - ARENA.BURST_MIN + 1));
      // legacyN = 老口径的粒子数（4 / 7）：让"每次击杀消耗多少主 rng"保持不变（见 burst 的注释）
      this.burst(e.x, e.y, e.elite ? ARENA.ELITE_TINT : typeOf(e.kind).color, n, null, e.elite ? 7 : 4);
      this.addDeath(e, knock);
    }
  }

  /**
   * 阶段 4-4：Boss 出场调度。
   *   · 出场前 BOSS_WARN_LEAD 秒打一次全屏警告（不暂停，spec 一-2）；
   *   · 到点出场 —— **一次只活一个**：`bossRef` 非空时压着不刷，下一个 Boss 会一直等到
   *     前一个死掉（bossRef 在 killEnemy 里被清空）才补上（spec 一-1「没死不刷下一个」）。
   * ★ 全程不消耗 rng（出场角度在 spawnBoss 里抽一次）：调度本身对确定性零影响。
   */
  _stepBossSchedule() {
    if (this.bossIdx >= BOSS_ORDER.length) return;
    const id = BOSS_ORDER[this.bossIdx];
    const b = BOSS_TYPES[id];
    const t = this.elapsed;
    if (this.bossWarned < this.bossIdx && t >= b.atSec - ARENA.BOSS_WARN_LEAD) {
      this.bossWarned = this.bossIdx;
      this.milestones.push({ text: '⚠ 强大的敌人接近 ⚠', t: 0, life: ARENA.BOSS_WARN_LIFE });
    }
    if (!this.bossRef && t >= b.atSec) {
      this.spawnBoss(id);
      this.bossIdx += 1;
    }
  }

  // ── 阶段 4-12：局内突发事件 ──
  // 调度完全确定性：固定时间表（基于 this.elapsed）+ 固定类型循环（ARENA.EVENT_SEQ），
  // 不消耗主 rng 流 ⟹ "同种子同结果"护栏天然成立。效果里：
  //   · gold 零 rng；supply/elite 用独立 srcRng 定位或选种；elite 用 makeEnemy 强制精英（纯构造、零 rng）。
  //   所以事件系统对主玩法随机序列零侵入，sim 读数与 4-9 基底逐字节可比（仅多了确定性的事件效果）。
  _stepEvents(dt) {
    // 黄金时段倍率到期回收（不显示字段，纯经济）
    if (this.goldUntil > 0 && this.elapsed >= this.goldUntil) {
      this.goldMul = 1;
      this.goldUntil = -1;
    }
    // 磁暴倍率到期回收（纯增益，不碰判定）
    if (this.magnetUntil > 0 && this.elapsed >= this.magnetUntil) {
      this.magnetMul = 1;
      this.magnetUntil = -1;
    }
    // 触发下一个事件（固定时间 + 固定类型循环，绝不随机）
    if (this.eventIdx < 999 && this.elapsed >= this.nextEventAt && this.nextEventAt <= ARENA.EVENT_LAST) {
      const type = ARENA.EVENT_SEQ[this.eventIdx % ARENA.EVENT_SEQ.length];
      this._fireEvent(type);
      this.eventIdx += 1;
      this.nextEventAt = this.elapsed + ARENA.EVENT_EVERY;
      if (this.nextEventAt > ARENA.EVENT_LAST) this.nextEventAt = 1e9; // 之后不再触发
    }
  }

  _fireEvent(type) {
    if (type === 'gold') {
      this.goldMul = ARENA.GOLD_MUL;
      this.goldUntil = this.elapsed + ARENA.GOLD_T;
      this.eventLog.gold += 1;
      this.milestones.push({ text: '★黄金时段★ 经验 ×' + ARENA.GOLD_MUL + '！', kind: 'event', t: 0, life: ARENA.EVENT_BANNER_LIFE });
    } else if (type === 'supply') {
      const px = this.player.x, py = this.player.y;
      for (let i = 0; i < ARENA.SUPPLY_HEARTS; i++) {
        if (this.hearts.length >= ARENA.MAX_HEARTS) break;
        const a = this.srcRng.next() * TAU, d = 40 + this.srcRng.next() * ARENA.SUPPLY_RING;
        this.hearts.push({ x: px + Math.cos(a) * d, y: py + Math.sin(a) * d, r: ARENA.HEART_R, pop: 0, life: ARENA.HEART_LIFE, dead: false });
      }
      for (let i = 0; i < ARENA.SUPPLY_GEMS; i++) {
        const a = this.srcRng.next() * TAU, d = 40 + this.srcRng.next() * ARENA.SUPPLY_RING;
        this.gems.push({ x: px + Math.cos(a) * d, y: py + Math.sin(a) * d, ox: 0, oy: 0, pop: 0, r: 4, xp: ARENA.SUPPLY_GEM_XP, dead: false });
      }
      this.eventLog.supply += 1;
      this.milestones.push({ text: '★补给空投★ 回血 + 经验！', kind: 'event', t: 0, life: ARENA.EVENT_BANNER_LIFE });
    } else if (type === 'elite') {
      // 阶段 4-13：威胁波（精英狩猎 = 威胁 + 即时赏金）。精英种类用独立 srcRng 选（normal/fast/ranged），确定性安全、不碰主 rng
      const ek = ['normal', 'fast', 'ranged'][Math.floor(this.srcRng.next() * 3)];
      for (let i = 0; i < ARENA.ELITE_CALL_N; i++) {
        const a = this.srcRng.next() * TAU;                 // 落点用独立 srcRng，不碰主 rng
        const d = ARENA.SPAWN_RING_MIN + this.srcRng.next() * (ARENA.SPAWN_RING_MAX - ARENA.SPAWN_RING_MIN);
        this.enemies.push(this.makeEnemy(ek, this.player.x + Math.cos(a) * d, this.player.y + Math.sin(a) * d, this.elapsed, true));
        this.eliteSpawned += 1;
      }
      // 附赠赏金：在玩家附近撒心心+经验宝石，让"打还是躲"都有回报，净难度回到增益波附近（不破坏基准存活口径）
      const px = this.player.x, py = this.player.y;
      for (let i = 0; i < ARENA.ELITE_BOON_HEARTS; i++) {
        if (this.hearts.length >= ARENA.MAX_HEARTS) break;
        const a = this.srcRng.next() * TAU, d = 40 + this.srcRng.next() * ARENA.SUPPLY_RING;
        this.hearts.push({ x: px + Math.cos(a) * d, y: py + Math.sin(a) * d, r: ARENA.HEART_R, pop: 0, life: ARENA.HEART_LIFE, dead: false });
      }
      for (let i = 0; i < ARENA.ELITE_BOON_GEMS; i++) {
        const a = this.srcRng.next() * TAU, d = 40 + this.srcRng.next() * ARENA.SUPPLY_RING;
        this.gems.push({ x: px + Math.cos(a) * d, y: py + Math.sin(a) * d, ox: 0, oy: 0, pop: 0, r: 4, xp: ARENA.SUPPLY_GEM_XP, dead: false });
      }
      this.eventLog.elite += 1;
      const tag = ek === 'ranged' ? '远程精英' : ek === 'fast' ? '疾影精英' : '近战精英';
      this.milestones.push({ text: '⚠' + tag + '降临·赏金已投⚠', kind: 'event', t: 0, life: ARENA.EVENT_BANNER_LIFE });
    } else if (type === 'magnet') {
      // 阶段 4-13：磁暴（纯增益）。临时放大经验/心心拾取半径，让玩家体验"自动收割"的爽感。
      this.magnetMul = ARENA.MAGNET_MUL;
      this.magnetUntil = this.elapsed + ARENA.MAGNET_T;
      this.eventLog.magnet += 1;
      this.milestones.push({ text: '★磁暴★ 经验自动吸！', kind: 'event', t: 0, life: ARENA.EVENT_BANNER_LIFE });
    }
  }

  // ── 阶段 7 · 精英波（spec §局内成长节奏：每 90 秒一波，击杀必掉技能选择）──
  //
  // ★ 为什么要独立于 EVENT_SEQ 另起一套调度：见 ARENA.ELITE_WAVE_ON 上方的注释块
  //   （EVENT_SEQ 的前提是"每波净增益"，塞进精英会同时毁掉节奏与历史基线）。
  // ★ 零 rng 侵入：调度基于 this.elapsed 的固定时间表（确定性），落点与种类用
  //   **已有的 srcRng**（事件落点专用流），因此主 rng 序列逐比特不变 ⟹
  //   阶段 4-9 的"同种子同结果"护栏与 16 局 sim 的归因表都不需要重标。
  _stepEliteWaves(dt) {
    if (!ARENA.ELITE_WAVE_ON) return;
    if (this.elapsed < this.nextEliteWaveAt) return;
    if (this.nextEliteWaveAt > ARENA.ELITE_WAVE_LAST) { this.nextEliteWaveAt = 1e9; return; }

    this.eliteWaveIdx += 1;
    this.nextEliteWaveAt = this.elapsed + ARENA.ELITE_WAVE_EVERY;

    // 种类：与 _fireEvent('elite') 同一组（normal/fast/ranged），共用 srcRng ⟹ 同样确定性。
    // ★ 这一波里**全部同种**：混种会让"一波"读起来像两次事件，压迫感散掉。
    const ek = ['normal', 'fast', 'ranged'][Math.floor(this.srcRng.next() * 3)];
    for (let i = 0; i < ARENA.ELITE_WAVE_N; i++) {
      if (this.enemies.length >= ARENA.MAX_ENEMIES - ARENA.CLIMAX_SOFT_GAP) break;
      const a = this.srcRng.next() * TAU;
      const d = ARENA.SPAWN_RING_MIN + this.srcRng.next() * (ARENA.SPAWN_RING_MAX - ARENA.SPAWN_RING_MIN);
      const e = this.makeEnemy(ek, this.player.x + Math.cos(a) * d, this.player.y + Math.sin(a) * d, this.elapsed, true);
      // ★ eliteWave 标记：**只有这条调度刷出来的精英才掉技能选择**。
      //   阶段 4-13 的 elite 事件（虽然当前不在 live 循环里）与随机刷出的近战精英
      //   都不带这个标记 —— 否则"击杀必掉技能选择"会退化成"清场就白嫖三选一"。
      e.eliteWave = true;
      this.enemies.push(e);
      this.eliteSpawned += 1;
    }
    // 赏金：与 ELITE_BOON 同一套口径（心心 + 经验），让净难度不因这只精英单向上升。
    const px = this.player.x, py = this.player.y;
    for (let i = 0; i < ARENA.ELITE_WAVE_HEARTS; i++) {
      if (this.hearts.length >= ARENA.MAX_HEARTS) break;
      const a = this.srcRng.next() * TAU, d = 40 + this.srcRng.next() * ARENA.SUPPLY_RING;
      this.hearts.push({ x: px + Math.cos(a) * d, y: py + Math.sin(a) * d, r: ARENA.HEART_R, pop: 0, life: ARENA.HEART_LIFE, dead: false });
    }
    for (let i = 0; i < ARENA.ELITE_WAVE_GEMS; i++) {
      const a = this.srcRng.next() * TAU, d = 40 + this.srcRng.next() * ARENA.SUPPLY_RING;
      this.gems.push({ x: px + Math.cos(a) * d, y: py + Math.sin(a) * d, ox: 0, oy: 0, pop: 0, r: 4, xp: ARENA.SUPPLY_GEM_XP, dead: false });
    }
    const tag = ek === 'ranged' ? '远程精英' : ek === 'fast' ? '疾影精英' : '近战精英';
    this.eventLog.eliteWave += 1;
    this.milestones.push({ text: `⚠ ${tag}×${ARENA.ELITE_WAVE_N}·击杀必掉技能⚠`, kind: 'event', t: 0, life: ARENA.EVENT_BANNER_LIFE });
  }

  /**
   * 精英波怪死亡 → 兑现一次技能三选一（spec「击杀必掉技能选择」）。
   *
   * ★ 为什么**排队**而不是立刻 openUpgrade()：
   *   ① 同一帧可能连杀两只精英（剑/散射的范围伤害），第二个 openUpgrade 会直接覆盖
   *      pendingUpgrade —— 玩家刚看到的三张牌被换掉，等于吞掉一次选择。
   *   ② 击杀瞬间几乎必然正挂着升级弹窗（精英给的经验够升一级），gainXp 里的
   *      `if (this.xp >= this.xpToLevel && !this.pendingUpgrade)` 也会互相打架。
   *   排队 + 每帧只出一张 ⟹ 任何顺序下玩家一共拿到 N 次选择，一次不少。
   */
  _grantEliteSkillDrop() {
    this.eliteWaveKills += 1;
    this.eliteSkillDrops += 1;
  }

  /**
   * 兑现排队中的精英技能三选一。
   * 门禁三条（缺一不可）：① 没有升级弹窗 ② 没结束 ③ 确实有待兑现的次数。
   * 用 `pendingUpgrade` 独占而不是叠加，所以永远不会出现"一次击杀给两张弹窗"。
   */
  _flushEliteSkillDrop() {
    if (this.eliteSkillDrops <= 0) return false;
    if (this.pendingUpgrade || this.done) return false;
    this.eliteSkillDrops -= 1;
    this.eliteSkillGiven += 1;
    this.openUpgrade({ skillFlavored: true, reason: 'elite' });
    return true;
  }

  /** 阶段 4-4：刷一个 Boss。血量 = **同期普通怪**血量 × hpMul（spec 四），冻在出生那一刻。 */
  spawnBoss(id) {
    const b = BOSS_TYPES[id];
    const sec = this.elapsed;
    const ang = this.rng.next() * TAU;
    const off = this.spawnOffset(ang, ARENA.BOSS_SPAWN_DIST);
    const base = ENEMY_TYPES.normal;                 // ★ 锚点是**普通怪**（spec 四的口径）
    const hp = base.hp * this.hpScale(sec) * b.hpMul;
    const e = {
      kind: id,
      x: this.player.x + off.dx, y: this.player.y + off.dy,
      r: b.r,
      speed: b.speed,                                // 比普通怪慢（spec 二-1）
      hp, maxHp: hp,
      contact: base.contact * this.contactScale(sec) * ARENA.BOSS_CONTACT_MUL,
      xp: 25 + 15 * b.idx,
      elite: false, dead: false, hitT: 0, spin: 0, fireT: 0, appear: 0,
      // ── Boss 专属运行时（形状统一初始化：热路径上不必再判 undefined）──
      cycT: ARENA.BOSS_CYCLE, cycN: 0,               // 攻击循环
      phase: 'idle', bossT: 0,                       // idle / windup / charge
      aimX: 0, aimY: 0, cvx: 0, cvy: 0,              // 冲锋方向 / 速度
      touchCd: 0,
    };
    this.enemies.push(e);
    this.bossRef = e;
    this.bossSpawned[b.idx] += 1;
    this.spawned += 1;
    this.bossFlashT = ARENA.BOSS_ENTER_FLASH_T;   // 阶段 4-11：Boss 出场红场脉冲（纯显示，不碰判定）
    return e;
  }

  /**
   * 阶段 4-4：Boss 的一拍。
   * 三态机：idle（缓慢追踪）→ windup（0.5s 前摇，**站住不动** + 方向提示）→ charge（高速冲一次）。
   * ★ 前摇期间不动是刻意的：动起来的话"朝哪冲"就变成要猜的事，预兆形同不存在。
   * 攻击选择不消耗 rng（按 cycN 轮转）：Boss1 冲锋/召唤各半；Boss2 每 3 轮才召一次（更频繁地冲）。
   */
  stepBoss(e, ux, uy, d, dt) {
    if (e.phase === 'windup') {
      e.bossT -= dt;
      if (e.bossT <= 0) {
        e.phase = 'charge';
        e.bossT = ARENA.BOSS_CHARGE_T;
        e.cvx = e.aimX * ARENA.BOSS_CHARGE_SPEED;
        e.cvy = e.aimY * ARENA.BOSS_CHARGE_SPEED;
      }
      return;
    }
    if (e.phase === 'charge') {
      e.bossT -= dt;
      e.x += e.cvx * dt;
      e.y += e.cvy * dt;
      if (e.bossT <= 0) { e.phase = 'idle'; e.cvx = 0; e.cvy = 0; }
      return;
    }
    // idle：缓慢追踪（威胁来自血厚 + 攻击，不是速度）
    const bv = this._effSpeed(e) * dt;   // 阶段 5 · B2：同样地吃减速/控场
    e.x += ux * bv;
    e.y += uy * bv;
    e.cycT -= dt;
    if (e.cycT > 0) return;
    e.cycT = ARENA.BOSS_CYCLE;
    e.cycN += 1;
    // ★ 冲锋频率是 Boss 唯一的"进场手段"：它追踪得比玩家慢（spec 二-1），
    //   单靠走位永远追不上 150px/s 的玩家 —— 实测 Boss1 平均站场 45s 里大半时间都在
    //   射程（340px）外"散步"，Boss2 更是有 6~9/16 局**整局没被打死**（它变成了背景板）。
    //   所以让冲锋承担"拉近"这件事：Boss1 每 3 轮召一次（2/3 在冲），Boss2 每 4 轮召一次
    //   （3/4 在冲，spec 二-2「Boss2 冲锋更频繁」）。每次冲锋净拉近 ≈147px。
    const idx = BOSS_TYPES[e.kind].idx;
    const summon = idx === 0 ? (e.cycN % 2 === 0) : (e.cycN % 3 === 2);
    if (summon) this.bossSummon(e, BOSS_TYPES[e.kind].summon);
    else { e.phase = 'windup'; e.bossT = ARENA.BOSS_WINDUP; e.aimX = ux; e.aimY = uy; }
  }

  /** 阶段 4-4：召唤 —— 在自己周围召 N 只普通怪（spec 二-2）。走 spawnEnemy，所以数值口径一致。 */
  bossSummon(e, n) {
    const at = { x: e.x, y: e.y };
    for (let i = 0; i < n; i++) {
      // 与刷怪表同一道软上限：场子满了就不补（"限流"，不是"先刷再被丢"）
      if (this.enemies.length >= ARENA.MAX_ENEMIES - ARENA.CLIMAX_SOFT_GAP) break;
      this.spawnEnemy(ARENA.BOSS_SUMMON_R * 0.5, ARENA.BOSS_SUMMON_R, at);
    }
  }

  /**
   * 阶段 4-3：局内里程碑（撑过 1/3/5 分钟、杀 100/300/500/1000 只）。
   * ★ 只往 `this.milestones` 里 push 一行待显示文本 —— 不暂停、不弹窗、不改任何玩法状态
   *   （spec 二-3 明文"不暂停"）。渲染层取走后自己计时淡出。
   *   幂等由 mileFlags 保证：每条只会 push 一次。
   */
  _checkMilestones() {
    const M = ARENA.MILESTONES;
    for (let i = 0; i < M.length; i++) {
      if (this.mileFlags[i]) continue;
      const m = M[i];
      const v = m.kind === 'sec' ? this.elapsed : this.kills;
      if (v < m.at) continue;
      this.mileFlags[i] = true;
      this.milestones.push({ text: m.text, t: 0 });
    }
  }

  /**
   * 死亡动画：留一个**纯视觉替身**，在 0.15s 内「爆裂放大 → 缩小」+ 白闪。
   * 逻辑上的敌人此刻已经从 this.enemies 里移除（见 this.deaths 的注释），
   * 位移与缩放都由 t 直接算、全部走 ease-out：不积分、不消耗 rng。
   */
  addDeath(e, knock = null) {
    if (this.deaths.length >= ARENA.MAX_DEATHS) this.deaths.shift(); // 与 burst 同一策略：保最新
    this.deaths.push({
      kind: e.kind, elite: !!e.elite, x: e.x, y: e.y, r: e.r, t: 0, life: ARENA.DEATH_ANIM,
      dx: knock ? knock.ux * knock.dist : 0,
      dy: knock ? knock.uy * knock.dist : 0,
    });
  }

  /** 飘字：小字、快出快隐。硬上限 MAX_FLOATERS（fillText 是 Canvas2D 最贵的调用之一）。 */
  floatText(x, y, text, color = COLOR.ink, life = ARENA.FLOAT_LIFE, big = false) {
    if (this.floaters.length >= ARENA.MAX_FLOATERS) this.floaters.shift(); // 超出丢**最旧的**
    // 记 `max`（总寿命）：上飘位置要按 t/max 走 ease-out，而 life 每帧都在减，拿它当分母曲线会变形。
    // ★ 阶段 4-3：`big` = 大伤害/暴击 —— 字号 ×FLOAT_BIG_MUL、颜色换金（spec 一-1）。
    //   颜色也跟着换（不只是变大）是因为满屏两百只怪时"更大一点"读不出来，换个色才抓眼。
    this.floaters.push({ x, y, y0: y, text, color: big ? COLOR.gold : color, t: 0, life, max: life, big: !!big });
  }

  /** 阶段 4-3：命中闪白（spec 一-5「打中敌人的闪白更明显一档」）。
   *  只写一个**纯视觉**的倒计时字段，不改 hp / 不改判定 —— 打死的那一下走死亡动画，不需要它。 */
  flashHit(e) {
    if (e) e.hitT = ARENA.HIT_FLASH;
  }

  damagePlayer(amount) {
    if (this.dashInvuln > 0) return; // 闪现途中无敌（spec §3）
    // ── 阶段 7 · 荆棘装备：受击时反弹**比例**伤害给**周围**敌人 ──
    // ★ 位置在这一行的最前面（扣血之前）而不是之后：反弹是"被打"的补偿，
    //   若放在扣血之后，一旦这一击把玩家打死就会漏掉反弹 —— 而"被打死的那一下也反打"
    //   恰恰是荆棘最该兑现的一刻。
    // ★ 走 applyHit(e, ..., src='thorn')：归因表里 thorn 是**已存在**的键（阶段 3 反伤在用），
    //   所以不会新增来源、Σ来源 == 总击杀 这条护栏依然成立。
    if (this.thorns > 0) this._reflectThorns(amount);
    // ── 阶段 7 · 护盾装备：每层抵挡 1 次伤害 ──
    // ★ 判定放在磐石/减伤**之前**：护盾是"整次免疫"，被它吃掉的这一下不应该再吃磐石的 30% 减免
    //   （否则两层护盾的收益会低于一层，玩家会看不懂）。有层 ⟹ 直接消掉并返回。
    if (this.shieldLayers > 0) {
      this.shieldLayers -= 1;
      this.floatText(this.player.x, this.player.y - this.player.r, '格挡', COLOR.shield);
      return;
    }
    // 阶段 5 · B1 磐石：受伤**之后**开一个短窗，窗内的后续伤害再减 30%。
    //   ★ 顺序是有意的：窗由"这一下"点亮，所以第一下永远不打折 —— 它治的是"连续挨第二下开始滚雪球"，
    //     不是"把角色整体变硬"（那是「减伤」被动的事）。
    const after = this.stoneT > 0 ? amount * (1 - this._stoneDr()) : amount;
    this.stoneT = this._stoneWindow();
    // 阶段 3「减伤」被动：接触伤害先扣 armor，但至少留 1 点（否则满减伤=无敌，比"抗揍"过头）。
    const dmg = Math.max(1, after - this.armor);
    this.hp = Math.max(0, this.hp - dmg);
    this.hurtT = ARENA.HURT_FLASH;   // 阶段 4-10：受击红屏脉冲（复活另有 flashT 白闪，二者叠加不冲突）
    // 阶段 3 元进度「不屈」：hp 归零但还有复活次数 → 兜底一次半血复活 + 短暂无敌。
    // 默认 revivesLeft === 0 → 此分支永不进入，行为等同阶段 2 末。
    if (this.hp <= 0 && this.revivesLeft > 0) {
      this.revivesLeft -= 1;
      this.hp = Math.ceil(this.maxHp * 0.5);
      this.dashInvuln = 1.2;        // 复活无敌 1.2s，给一拍喘气
      this.flashT = 0.25;
      this.floatText(this.player.x, this.player.y, '复活', COLOR.good);
    }
  }

  /** 回血（「回复 +2」升级项的唯一入口，不超上限） */
  healPlayer(amount) {
    this.hp = Math.min(this.maxHp, this.hp + amount);
  }

  /**
   * 阶段 7 · 荆棘装备：把 `amount × thorns` 的伤害打给**周围** THORNS_RADIUS 内的敌人。
   *
   * ★ 三条设计纪律（与本项目既有的质量约束一致）：
   *   ① **零 rng**：遍历用 for 循环取前 N 个最近目标，不用"随机抽目标"。
   *   ② **单次封顶**（ARENA.THORNS_CAP）：不封顶的话，在贴脸被 200 只怪围住时
   *      一次受击会把周围全部打成 AOE —— 荆棘就从"防御装"变成了"第二输出源"，
   *      而阶段 4-9 刚刚把技能从输出主力降回保命定位，不能让一件装备把它顶回去。
   *   ③ **不递归**：反弹伤害走 applyHit，若反弹又触发"击杀 → 吸血 → 回血"是期望内的，
   *      但反弹**不会**再次进入 damagePlayer（敌人打不到玩家），所以不存在无限链。
   */
  _reflectThorns(amount) {
    const R = ARENA.THORNS_RADIUS, R2 = R * R;
    const dmg = Math.min(ARENA.THORNS_CAP, amount * this.thorns);
    if (dmg <= 0) return;
    // 收集半径内的活怪，按距离升序（确定性：同距时按数组序，不引入比较器的不稳定性）
    const near = [];
    for (const e of this.enemies) {
      if (e.dead) continue;
      const dx = e.x - this.player.x, dy = e.y - this.player.y;
      const d2 = dx * dx + dy * dy;
      if (d2 <= R2) near.push({ e, d2 });
    }
    near.sort((a, b) => a.d2 - b.d2);
    const n = Math.min(ARENA.THORNS_MAX_TARGETS, near.length);
    for (let i = 0; i < n; i++) {
      this.applyHit(near[i].e, dmg, null, false, 'thorn');
    }
  }

  /**
   * 阶段 7 · 护盾充能（每 `shieldEvery` 秒一层，层数封顶 ARENA.SHIELD_LAYERS_MAX）。
   * ★ 计时器归零即**重新充满**而不是只 +1 层：这样"停手"不会让层数慢慢攒满
   *   （一个永不被消耗的护盾池 = 免费无敌）。开局立刻给一层（shieldT = 周期）。
   */
  _tickShield(dt) {
    if (this.shieldEvery <= 0) return;
    this.shieldT -= dt;
    if (this.shieldT > 0) return;
    this.shieldT += this.shieldEvery;      // 用 += 而不是 = ：防止大 dt 一步跨过整个周期
    this.shieldLayers = ARENA.SHIELD_LAYERS_MAX;
  }

  // ───────── 阶段 5 · B1 职业专属被动：三个小状态机 ─────────
  // ★ 全部**确定性**（零 rng）、全部作用在既有字段上。读值一律兜一层 Helper：
  //   未装备该被动的职业 ⟹ 恒等（0 / 1），把所有"别的职业为什么会有这个加成"的问题
  //   归并到这一处判断题，而不是散落在 step / damagePlayer 里。
  /** 磐石：当前是否强减伤窗内 → 减伤比例（未装备恒为 0）。 */
  _stoneDr() { return this.classPassive && this.classPassive.stoneDr ? this.classPassive.stoneDr : 0; }
  /** 磐石：窗口时长（未装备恒为 0）。 */
  _stoneWindow() { return this.classPassive && this.classPassive.stoneWindow ? this.classPassive.stoneWindow : 0; }

  // ───────── 阶段 5 · B2 的公共 debuff 基础设施 ─────────
  // 三个变体共用同一套字段（e.stun / e.slowT+slowK / this.slowZones），而不是各自一套。
  // ★ 理由很实在：三套各自的新 container 意味着三处衰减、三处判空，漏衰减一处就是"永久
  //   减速"这种查不出来的 bug；共用一个出口则任何一条没有配 perks 的职业 ⟹ 全是空/0 ⟹
  //   两个函数都返回恒等值（1 / 原速），行为与前作逐比特相同。
  /** 本帧这只怪的移速倍率（1 = 未受影响）。多个来源取**最强**的那条，不叠乘成定身。 */
  _speedMul(e) {
    let k = 1;
    if (e.slowT > 0 && e.slowK < k) k = e.slowK;
    for (const z of this.slowZones) {
      if (z.t <= 0) continue;
      const dx = e.x - z.x, dy = e.y - z.y;
      if (dx * dx + dy * dy <= z.r * z.r && z.k < k) k = z.k;
    }
    return k;
  }
  /** 本帧这只怪的实际移速。 */
  _effSpeed(e) { return e.speed * this._speedMul(e); }
  /** 是否处于"被控"状态（被任一方式减速/定身）—— 重壳守卫「重刃」的增伤判据。 */
  _isCrowdControlled(e) { return e.stun > 0 || e.frozen > 0 || this._speedMul(e) < 1; }
  /** B2 破阵的定身时长（没这条变体恒为 0）。 */
  _perkStun() {
    const S = this.classPerk && this.classPerk.skill;
    return S && S.stun ? S.stun : 0;
  }
  /** 寒潮：解冻的一刻挂上残留减速。已有更强的减速时不去冲淡它。 */
  _applyChill(e) {
    const S = this.classPerk && this.classPerk.skill;
    if (!S || !S.chillDur) return;
    if (e.slowT > 0 && e.slowK <= S.chillK) return;
    e.slowT = S.chillDur;
    e.slowK = S.chillK;
  }

  /** 猎风：位移积分攒层 / 站定掉层。 */
  _stepWind(moved, wantsMove, dt) {
    const P = this.classPassive;
    if (!P || !P.windPer) return;
    this.windDist += moved;
    while (this.windDist >= P.windPer && this.windStacks < P.windMax) {
      this.windDist -= P.windPer;
      this.windStacks += 1;
      this._refreshClassBuffs();
    }
    if (this.windDist > P.windPer) this.windDist = 0;   // 已满层：余量不再攒（避免"满层溢出后猛涨"）
    // 站定 windHold 之后开始掉层，每 windDecay 秒掉一层。
    if (!wantsMove) this.windIdleT += dt; else this.windIdleT = 0;
    if (this.windIdleT >= P.windHold && this.windStacks > 0) {
      this.windDecayT += dt;
      if (this.windDecayT >= P.windDecay) {
        this.windDecayT = 0;
        this.windStacks -= 1;
        this._refreshClassBuffs();
      }
    } else this.windDecayT = 0;
  }

  /**
   * 阶段 5：把"所有进入伤害/移速的永久 + 临时来源"重新折合成两个数。
   * ★ 为什么不直接改字段：本作现在有三处各自在乘移速（英雄倍率 / 「移速 +15%」被动 / 猎风），
   *   各自乘各自的、顺序一变结果就漂。既然要支持多来源，就必须有一个"重新算一遍"的出口。
   */
  _refreshClassBuffs() {
    const P = this.classPassive;
    const perLv = P && P.dmgPerLevel ? P.dmgPerLevel : 0;
    const wind = P && P.windMove ? this.windStacks * P.windMove : 0;
    const windD = P && P.windDmg ? this.windStacks * P.windDmg : 0;
    // dmgBase 是给阶段 5 的长期成长（属性树）留的口子，gUpMul 是伤害类升级/被动的全局乘区。
    this.gDmgMul = this.dmgBase * this.gUpMul * (1 + perLv * this.level) * (1 + windD);
    // (基础 × 临时倍率 + 永久加算) × 永久乘算 —— 三个通道互不擦除。
    this.moveSpeed = (this.moveBase * (1 + wind) + this.moveFlat) * this.moveMulP;
  }

  /** 升到下一级所需经验。**几何增长** —— 形状的依据见 ARENA.XP_BASE 的注释块。
   *  门槛是**由 level 算出来的**，不是存在字段里被反复累加的量：
   *  存字段的写法一旦在某条分支上漏了更新，曲线会静默错位而没有任何报错。 */
  xpNeed(level = this.level) {
    return ARENA.XP_BASE * Math.pow(ARENA.XP_GROWTH, level);
  }

  gainXp(n) {
    this.xp += n * this.xpMul;       // 阶段 3「经验 +%」被动
    this.gemsCollected += n;
    if (this.xp >= this.xpToLevel && !this.pendingUpgrade) this.openUpgrade();
  }

  /** 打开三选一：从 6 项里抽 3 个**不重复**的（spec §1）。用 rng 抽 ⟹ 同种子同结果。
   *
   *  ★ 先滤掉**已经封顶**的项。攻速下限 0.2s、弹道上限 7 条都是 spec 定的硬上限，
   *    到顶之后选中它等于什么都没发生 —— 实测结算页上出现过 `atk×6`，而后 2 次全是空转。
   *    让三选一里出现"选了没反应"的选项，是在骗玩家的一次选择。
   *    · `regen` **不滤**：满血时它同样加不上去，但那是**玩家自己的时机判断**
   *      （该留到受伤时拿），不是"这项已经作废"。滤掉反而会抽掉一个合法决策。
   *    · 若可选项不足 3 个，退回完整池子 —— 三选一必须**永远是 3 个**，
   *      宁可给一个已封顶的项，也不能让弹窗只剩 1~2 个选项。 */
  openUpgrade(opts = {}) {
    const pool = OFFERS.filter((o) => o.avail(this));
    const picks = [];

    // ★ 阶段 7 · 精英波的技能三选一（spec「击杀必掉技能选择」）。
    //   口径：**三个名额全部**优先给技能向牌（主动技能强化 or 特殊效果），
    //   而不是像每 3 级保底那样"只塞一张"。两者的体验目标不同：
    //   · 每 3 级保底 = "别让玩家连着三张纯数值"（防止三选一变得无趣）
    //   · 精英奖励= "这是我对打了一只精英的回报"（应当明显更值）
    //   技能向牌池若不足 3 张，退回"能填几张填几张 + 其余按普通池补"，
    //   但**保底至少 1 张**（否则"必掉技能"这句话就是假的）。
    if (opts.skillFlavored) {
      const flavored = pool.filter((o) => isSkillFlavored(o.id));
      for (const o of flavored) {
        if (picks.length >= ARENA.ELITE_WAVE_SKILL) break;
        picks.push(o);
      }
    }

    // ★ 前期保底（spec §4）：前 EARLY_GUARD_SEC 秒内若还没拿到过任何"新东西"，
    //   强行塞一件进三选一。否则开局连抽几个纯数值项，玩家会觉得"这局没有内容"
    //   —— 而"有没有新东西"恰恰是这类游戏前两分钟唯一的兴奋点。
    //   ★ 必须判上限：opts.skillFlavored 可能已经把 3 个名额占满了，
    //   无脑 push 会让弹窗变成 4 个选项（UI 按 UPGRADE_CHOICES 渲染，多的那张直接看不见）。
    if (this.elapsed <= ARENA.EARLY_GUARD_SEC && this.newThings === 0
        && picks.length < ARENA.UPGRADE_CHOICES) {
      const news = pool.filter((o) => o.unlock);
      if (news.length) picks.push(this.rng.weighted(news, (o) => o.weight));
    }

    // ★ 阶段 7 · 每 3 级的"技能向保底"（spec「每 3 级提供一次技能选择」的执行方式，
    //   口径冲突的完整裁决见 content.js SKILL_TIER_CADENCE 上方的注释块）：
    //   逢 3 的倍数那一级，必定在弹窗里塞进一张「主动技能强化」或「特殊效果」牌。
    //   ⟹ 这样玩家每~3 次决策就一定碰到一次"机制型"选项（而不是连着三张纯数值），
    //     而**不改动**每级一次的节奏本身 —— 那条节奏的护栏（首次升级 <20s /
    //     最长空档 ≤45s）是 16 局 sim 反复扫出来的，动它要整套重标。
    const isMilestone = this.level % SKILL_TIER_CADENCE === 0;
    if (isMilestone && !picks.some((o) => isSkillFlavored(o.id))) {
      const flavored = pool.filter((o) => isSkillFlavored(o.id));
      if (flavored.length) {
        const f = this.rng.weighted(flavored, (o) => o.weight);
        // 若这张技能牌已经占了一个名额，替换掉名单里最后抽到的那张（保持 3 个选项）
        if (picks.length >= ARENA.UPGRADE_CHOICES) picks.pop();
        picks.push(f);
      }
    }

    // 其余名额按权重**不放回**抽（权重见 content.js：新东西 > 强化 > 被动单项）
    const rest = pool.filter((o) => !picks.includes(o));
    while (picks.length < ARENA.UPGRADE_CHOICES && rest.length) {
      const o = this.rng.weighted(rest, (x) => x.weight);
      picks.push(o);
      rest.splice(rest.indexOf(o), 1);
    }
    // 兜底：极端封顶下可选项不足 3 个 → 退回完整池子补足。
    // 三选一**必须永远是 3 个**：宁可给一个已封顶的项，也不能让弹窗只剩 1~2 个选项。
    if (picks.length < ARENA.UPGRADE_CHOICES) {
      const all = OFFERS.slice();
      while (picks.length < ARENA.UPGRADE_CHOICES && all.length) {
        const o = this.rng.weighted(all, (x) => x.weight);
        all.splice(all.indexOf(o), 1);
        if (picks.includes(o)) continue;
        picks.push(o);
      }
    }
    this.pendingUpgrade = picks;
    // 阶段 7：这张弹窗的**来路**。'level' = 升级弹出（给经验、给等级）；
    // 'elite' = 精英波奖励（只给牌，**不给等级也不吃经验**）。
    // ★ 一定要显式记：chooseUpgrade 里 `level += 1` / `xp -= xpToLevel` 这两行
    //   对 'elite' 来说是错的 —— 精英波每 90 秒掉一张，若按升级结算，
    //   一局会凭空多出 6~7 级（10 分钟才 40 级的曲线被直接抬平），而且玩家
    //   会看到"我没升经验但等级涨了"。这属于只在跑满局里才显形的静默 bug。
    this.pendingUpgradeKind = opts.reason || 'level';
  }

  /** 选择第 i 个选项（0..UPGRADE_CHOICES-1）。选完若仍有富余经验则连开下一级。 */
  chooseUpgrade(i) {
    const up = this.pendingUpgrade && this.pendingUpgrade[i];
    if (!up) return false;
    this.applyUpgrade(up.id);
    const kind = this.pendingUpgradeKind;
    this.pendingUpgrade = null;
    this.pendingUpgradeKind = null;
    // 阶段 7 · 精英波奖励：只结算牌面，不动等级/经验（理由见 openUpgrade 末尾的注释）。
    if (kind === 'elite') return true;
    this.level += 1;
    this.levelFlashT = ARENA.LEVEL_FLASH_T;   // 阶段 4-11：升级暖光脉冲（纯显示，不碰任何数值）
    this._refreshClassBuffs();   // 阶段 5 · B1 剑意：伤害随等级成长（有这条被动才真的会变）
    this.xp -= this.xpToLevel;
    this.xpToLevel = this.xpNeed(); // 下一级门槛随等级上移
    if (this.xp >= this.xpToLevel) this.openUpgrade(); // 连升
    return true;
  }

  /** 应用一个升级项 / 宝箱奖品（按 id）。与 UI 解耦，测试可直接调用。返回是否识别该 id。
   *  查表而不是 switch：31 个 id 写成分支的话，每加一件内容就要改这里，
   *  而"忘了改这里"的表现是静默的 —— 选中了但什么都没发生。 */
  applyUpgrade(id) {
    const o = offerById(id);
    if (!o) return false;
    o.apply(this);
    this.upgradesTaken.push(id);
    if (o.unlock) this.newThings += 1;
    // ── 阶段 4-5：武器等级 / 被动计数 / 进化自证 ──
    // ★ 进化后不再累加武器等级（spec「进化后不能再强化」）；`more` 早已挡掉该武器强化项，
    //   这里再保险一次，防任何漏网路径把已进化武器的等级推过满级。
    const w = WEAPON_OF_UP[id];
    // ★ 没持有该武器 ⟹ 这条"武器强化"对它无意义（重壳守卫没有投射物，不该被塞 wp_dmg、
    //   更不该凭空触发螺旋进化）。正常池子靠 `more` 已挡掉，这里再兜一层直接吞掉。
    if (w && !this.weapons[w]) return true;
    // ★ wlvlUp 是唯一的闸门：剑可以在 C1→C2 之后再爬一次等级去够 C3，
    //   所以不能写死"进化过就不再加等级" —— 那会把 C3 这条线彻底堵死。
    if (w && this.wlvlUp(w)) {
      this.wLvl[w] = (this.wLvl[w] || 0) + 1;
      if (this.wLvl[w] > ARENA.W_LEVEL_MAX[w]) this.wLvl[w] = ARENA.W_LEVEL_MAX[w];
    }
    // 被动按 id 计数（进化需要的被动走这里）
    if (o.cat === 'passive') this.passiveTaken[id] = (this.passiveTaken[id] || 0) + 1;
    this._checkEvolution();
    // 阶段 5.1：任何可能改动 gUpMul / moveMulP 等派生源的升级，落定后统一重折 gDmgMul / moveSpeed。
    // （原来只有 `move` 被动自己调；现在伤害升级也走 gUpMul，统一在这里收口最稳。）
    this._refreshClassBuffs();
    return true;
  }

  /** 阶段 4-5：某武器是否还能继续拿强化（offer 的 `more` 判据用）。
   *  ★ 纯谓词，绝不改状态：进化后或已满级 ⟹ false（该武器强化项从池子消失）。 */
  wlvlUp(w) {
    return (this.evolved[w] || 0) < ARENA.W_STAGE_MAX[w] && (this.wLvl[w] || 0) < ARENA.W_LEVEL_MAX[w];
  }

  /** 阶段 4-5：检查所有进化线是否达成（满级 + 凑齐指定被动）。每条线只套一次。
   *
   *  ★ 阶段 5：支持**多阶链**。每条进化线写自己要跃迁到哪一阶（`stage`，默认 1）：
   *    · 只有"当前阶 = stage-1"时才可能跃迁 ⟹ 同武器的两条线天然按次序逐个兑现，
   *      不会出现"一帧里连跳两级"（那样第二阶的形态就被跳过、进化提示也只会播一次）。
   *    · 跃迁之后若还没到顶，把 wLvl 归零 —— 新形态必须**重新爬满级**才能再进化，
   *      否则第二阶会在达成第一条的同一瞬间就达成（等级已经满着）。
   */
  _checkEvolution() {
    for (const evo of EVOLUTIONS) {
      const toStage = evo.stage || 1;
      if ((this.evolved[evo.weapon] || 0) !== toStage - 1) continue;
      const lvOk = (this.wLvl[evo.weapon] || 0) >= ARENA.W_LEVEL_MAX[evo.weapon];
      const paOk = (this.passiveTaken[evo.passive] || 0) >= evo.need;
      if (lvOk && paOk) {
        this.evolved[evo.weapon] = toStage;
        this._applyEvolution(evo.weapon);
        // 未到顶 ⟹ 等级归零：给下一阶留出"再爬一次"的空间（见上面注释）。
        if (toStage < ARENA.W_STAGE_MAX[evo.weapon]) this.wLvl[evo.weapon] = 0;
        // 大字横幅复用 milestones 队列（渲染层按 kind 上金色），纯视觉、不消耗 rng
        this.milestones.push({ text: `★武器进化★ ${evo.label}`, kind: 'evo', t: 0, life: ARENA.EVO_BANNER_LIFE });
        if (typeof Sfx !== 'undefined' && typeof Sfx.evolve === 'function') Sfx.evolve();
      }
    }
  }

  /** 阶段 4-5：进化后的效果落地（只跑一次）。 */
  _applyEvolution(w) {
    if (w === 'orbit') {
      const o = this.orbit;
      // ★ spec 明文「刃数翻倍、旋转加速、范围加大」—— 刻意不加伤害（见 ARENA 常量注释）。
      o.count = Math.min(ARENA.STORM_COUNT_MAX, o.count * ARENA.STORM_COUNT_MUL);
      o.r *= ARENA.STORM_R_MUL;
      o.spin *= ARENA.STORM_SPIN_MUL;
    } else if (w === 'laser') {
      this.laser.cleave = true;   // 直斩 → 裂光（stepLaser 读这个标记）
    } else if (w === 'sword') {
      // ★ 阶段 5：剑有两阶，各自改**形态参数**，伤害/数量/间隔的强化轴不动
      //   （那些是 ws_dmg / ws_count / ws_cd 的地盘，进化不该把它们抹掉）。
      const S = this.sword;
      if (this.evolved.sword === 1) {
        // C2 扇形扫射：一次张开 100°（至少 3 道；此前若拿过 ws_count 已到 3，就保持原值）
        S.count = Math.max(S.count, ARENA.SWORD_C2_COUNT);
      } else if (this.evolved.sword === 2) {
        // C3 环绕：不再"对着最近的那只斩" —— 由 stepSwordRing 接管整圈。
        // 直线/扇形的 cd 留在原处无害（那一支不再被调用），不额外重置以免引入二态。
        this.swordRing = { ang: 0, tick: 0 };
      }
    }
    // projectile → 螺旋弹幕：靠 this.evolved.projectile 开关（step 里每 SPIRAL_CD 齐射一圈），无需改对象
  }

  /** 主动技能「冲击波」—— 调用即"按下"：先进入蓄力（视觉上是向外收拢的蓄力圈），
   *  蓄力结束由 step() 调 detonateShockwave() 结算伤害 + 击退 + 爆发环。
   *  冷却**从按下起算** —— 否则玩家会为动画白等 0.15s，那不是"有过程"而是"加延迟"。
   *  返回是否成功起手（冷却中 / 已在蓄力 / 暂停 / 已结束则失败）。 */
  shockwave() {
    if (this.done || this.pendingUpgrade || this.shockwaveCd > 0 || this.shockChargeT >= 0) return false;
    this.shockChargeT = 0;
    this.shockwaveCd = this.skShock.cdBase * this.cdMul;
    return true;
  }

  /** 蓄力结束的那一拍：一次性结算伤害 + 击退，并点亮白闪与爆发环。 */
  detonateShockwave() {
    const R = this.skShock.radius;
    for (const e of this.enemies) {
      if (e.dead) continue; // 同上的双重结算问题
      const dx = e.x - this.player.x, dy = e.y - this.player.y;
      const d = Math.sqrt(dx * dx + dy * dy);
      if (d > R + e.r) continue;
      const ux = d > 0.001 ? dx / d : 1, uy = d > 0.001 ? dy / d : 0; // 由玩家指向敌人
      // 阶段 4-7：冲击波**降格**为保命解围工具 —— 主效果是**击退**（把近身一圈弹推开），
      // 伤害只是副效果（砍半到 15，不再一个波秒光）。统一走 applyHit：
      //   · 护盾怪吸收一层、本拍不动血（破盾前不能靠一波扫清）；
      //   · 存活者：被推 SHOCKWAVE_KNOCK(×knockMul) 像素，真的"扫开一片"；
      //   · 致死：先位移再结算死亡（碎屑沿同方向外飞），"扫开"手感保留。
      const killed = this.applyHit(e, this.skShock.dmg,
        { ux, uy, dist: this.skShock.knock * this.knockMul }, false, 'shockwave');
      if (!this.reduced && killed) this.burst(e.x, e.y, COLOR.gem, 3, { x: ux, y: uy });
      // 阶段 5 · B2 破阵（流浪者）：被推开的再多冻一会 —— 位移已经把眼前的空间清出来了，
      //   定身负责让这片空间**真的可持续**（不然下一帧它们又贴回来，一波推开等于白推）。
      //   ★ 只对存活者有意义：applyHit 返回 true 说明这只已经死了，不必再控。
      if (!killed) { const st = this._perkStun(); if (st) e.stun = Math.max(e.stun || 0, st); }
    }
    // 阶段 5 · B2 地裂（重壳守卫）：在**玩家所在位置**留一块减速场。
    //   ★ 为什么是"留在原地"而不是"跟着玩家走"：重装该占住的是"我已经站住的这块地"，
    //     跟着走的减速场会变成常驻光环，那和"被动减伤"没区别，读不出开技能这个动作。
    const Z = this.classPerk && this.classPerk.skill;
    if (Z && Z.zoneDur) {
      this.slowZones.push({ x: this.player.x, y: this.player.y, r: R * Z.zoneR,
        t: Z.zoneDur, k: Z.zoneK });
    }
    this.enemies = this.enemies.filter((e) => !e.dead);
    this.shockwaveCastT = 0;
    this.flashT = ARENA.SHOCKWAVE_FLASH;
    this.shockCasts += 1;
  }

  // ───────── 阶段 2：武器 · 技能 · 宝箱 ─────────

  /** 某个 id 被拿过几次（封顶判据）。 */
  taken(id) {
    let k = 0;
    for (const x of this.upgradesTaken) if (x === id) k++;
    return k;
  }

  /** 武器/技能的初始化（解锁时调用一次）。放在 core 上而不是 content.js 里，
   *  是因为默认值住在 ARENA —— 让 content.js 自己 new 一份就会口径漂移。 */
  /**
   * 阶段 5 · B3：把"本命武器的专属强化"落到具体字段上（每人一条，互不重叠）。
   * ★ 为什么在这里一次性改字段、而不是在 step 里分支判断：
   *   这三条改的都是"这把武器本来就是什么样"，不是"这一帧该怎么算"。
   *   写成每帧分支的话，任何一处漏判都会得到一个"少了点什么"的职业 ——
   *   而它没有报错、没有崩溃，只是弱了一圈，是最难查的那类失效。
   */
  _applyClassPerks() {
    const K = this.classPerk;
    const W = K && K.weapon;
    if (!W) return;
    if (W.pierceN) this.projPierce = W.pierceN;      // 流浪者：投射物可穿透目标后再飞一段
    if (W.speedMul) this.projSpeed *= W.speedMul;    // 疾风行者：更快
    if (W.reachMul) this.projReachMul = W.reachMul;  // 疾风行者：更远
    if (W.ctrlBonus) this.orbitCtrlBonus = W.ctrlBonus; // 重壳守卫：对被控目标增伤
  }

  initWeapon(id) {
    if (id === 'orbit') this.orbit = { count: ARENA.ORBIT_COUNT, dmg: ARENA.ORBIT_DMG, r: ARENA.ORBIT_R, ang: 0, spin: ARENA.ORBIT_SPIN };
    else if (id === 'laser') this.laser = { dmg: ARENA.LASER_DMG, w: ARENA.LASER_W, interval: ARENA.LASER_CD, cd: 0, cleave: false };
    // 阶段 5：剑。解锁时把对象装起来（"获得即持有"）；形态始终读 this.evolved.sword（不存第二份）。
    else if (id === 'sword') this.sword = { dmg: ARENA.SWORD_DMG, count: ARENA.SWORD_COUNT, interval: ARENA.SWORD_INTERVAL, cd: 0, speed: ARENA.SWORD_SPEED };
  }
  initSkill(id) {
    if (id === 'shockwave') this.skShock = { radius: ARENA.SHOCKWAVE_RADIUS, dmg: ARENA.SHOCKWAVE_DMG,
      cdBase: ARENA.SHOCKWAVE_CD, knock: ARENA.SHOCKWAVE_KNOCK };
    else if (id === 'dash') this.skDash = { dist: ARENA.DASH_DIST, dmg: ARENA.DASH_DMG,
      cdBase: ARENA.DASH_CD, invuln: ARENA.DASH_INVULN };
    else if (id === 'frost') this.skFrost = { r: ARENA.FROST_R, dur: ARENA.FROST_DUR, cdBase: ARENA.FROST_CD };
  }

  /** 环绕刃：剑尖绕玩家转，碰到敌人扣血。命中节流见 ARENA.ORBIT_TICK 的注释。 */
  stepOrbit(dt) {
    const o = this.orbit;
    o.ang = (o.ang + o.spin * dt) % TAU;
    const n = o.count;
    const outer = o.r + ARENA.ORBIT_W + 30; // 先按半径预筛：绝大多数敌人根本不在环上
    for (const e of this.enemies) {
      if (e.dead) continue;
      if (e.oCd > 0) { e.oCd -= dt; continue; }
      const dx = e.x - this.player.x, dy = e.y - this.player.y;
      if (dx * dx + dy * dy > outer * outer) continue;
      for (let i = 0; i < n; i++) {
        const a = o.ang + (i / n) * TAU;
        const tx = this.player.x + Math.cos(a) * o.r;
        const ty = this.player.y + Math.sin(a) * o.r;
        const ex = e.x - tx, ey = e.y - ty;
        const rr = ARENA.ORBIT_W + e.r;
        if (ex * ex + ey * ey > rr * rr) continue;
        e.oCd = ARENA.ORBIT_TICK;
        // 阶段 5 · B3 重刃（重壳守卫）：被控住的敌人吃更高伤害 —— 与它自己的
        //   B2「地裂」减速场合成一条完整链路（先踩住地面，再磨）。
        //   ★ 走**倍率**而不是额外一次 applyHit：多一次调用就等于多一个伤害来源，
        //     归因表会多出一栏，而"技能 vs 武器占比"那两条 spec 断言依赖分母干净。
        const odmg = this.orbitCtrlBonus && this._isCrowdControlled(e)
          ? o.dmg * (1 + this.orbitCtrlBonus) : o.dmg;
        // 阶段 4-7：走统一伤害入口（护盾吸收 / 击杀 / 命中读数一套口径）。
        this.applyHit(e, odmg, { ux: Math.cos(a), uy: Math.sin(a), dist: ARENA.DEATH_DRIFT, live: false }, false, 'orbit');
        break;
      }
    }
    this.enemies = this.enemies.filter((e) => !e.dead);
  }

  /** 直斩：朝最近敌人扫一道穿透光束。命中判定 = 到射线段的垂距，全程不消耗 rng。
   *  ★ 阶段 4-5「裂光」：进化后一道变三道扇形（相邻夹角 CLEAVE_FAN）。 */
  stepLaser(dt) {
    const L = this.laser;
    if (L.cd > 0) L.cd -= dt;
    if (L.cd > 0) return;
    const tgt = this.nearestEnemy(ARENA.LASER_RANGE);
    // §4-8 一-2：直斩也不许隔空打屏幕外的怪 —— 目标本身必须在视口矩形内
    // （否则它会朝着屏幕外"砍"一道谁也看不见的光，节拍白耗）。
    if (tgt && ARENA.WEAPON_VIEW_CLIP
      && (Math.abs(tgt.x - this.player.x) - tgt.r > this.w / 2
        || Math.abs(tgt.y - this.player.y) - tgt.r > this.h / 2)) return;
    if (!tgt) return; // 射程内无目标：不消耗节拍，等敌人走近（与自动攻击同一口径）
    L.cd = L.interval;
    const px = this.player.x, py = this.player.y;
    const baseAng = Math.atan2(tgt.y - py, tgt.x - px);
    const beams = L.cleave ? ARENA.CLEAVE_BEAMS : 1;
    const half = L.w * 0.5;
    for (let bI = 0; bI < beams; bI++) {
      const off = beams === 1 ? 0 : (bI - (beams - 1) / 2) * ARENA.CLEAVE_FAN;
      const ang = baseAng + off;
      const ux = Math.cos(ang), uy = Math.sin(ang);
      for (const e of this.enemies) {
        if (e.dead) continue;
        const rx = e.x - px, ry = e.y - py;
        const proj = rx * ux + ry * uy;              // 沿光束的投影长度
        if (proj < 0 || proj > ARENA.LASER_RANGE) continue;
        // §4-8 一-2：光束不许打到屏幕外的怪。横向才是约束（半宽 195 < 射程 240），
        // 竖向 422 > 240 永远够不着边 —— 但两条都写上，免得哪天视口变成横屏就漏了。
        if (ARENA.WEAPON_VIEW_CLIP
          && (Math.abs(rx) - e.r > this.w / 2 || Math.abs(ry) - e.r > this.h / 2)) continue;
        const perp = Math.abs(-rx * uy + ry * ux);   // 到光束中轴的垂距
        if (perp > half + e.r) continue;
        // 阶段 4-7：走统一伤害入口（护盾吸收 / 击杀 / 命中读数一套口径）。
        this.applyHit(e, L.dmg, { ux, uy, dist: ARENA.DEATH_DRIFT, live: false }, false, 'laser');
      }
      this.pushFx({ kind: 'beam', x: px, y: py, ang, len: ARENA.LASER_RANGE, w: L.w, t: 0, life: ARENA.LASER_FX });
    }
    this.enemies = this.enemies.filter((e) => !e.dead);
    this.laserCasts += 1;
  }

  /**
   * 阶段 5 · 剑（C1 直线斩击）：每 SWORD_INTERVAL 秒朝最近敌人斩出 count 道**穿透剑气**。
   *
   * ★ 与直斩（stepLaser）的根本区别：直斩是"扫出去那一瞬间就结算完"的即时光束，
   *   而**剑气是飞行实体** —— 有弹速、有射程、飞行途中穿透多个敌人。所以它进 projectiles，
   *   额外带三个字段（per-projectile，见下方 update/filter 的改动）：
   *     pierce   —— 穿透（每只怪只结算一次，靠 p.hits 去重）
   *     maxDist  —— 自己的射程 380（通用回收是按 ATTACK_RANGE 240 算的，沿用会被砍成 264）
   *     dmg      —— 自己的伤害（this.dmg 是**投射物**那条轴的数，不能拿来结算剑）
   * 本方法覆盖 C1（直线）与 C2（扇形）—— 两者只是"几道、张多开"的区别，共用同一段飞出去的逻辑；
   * C3（环绕）形态见 stepSwordRing —— 它不再是"斩出去"这件事，所以在方法头上就分流走了。
   */
  stepSword(dt) {
    // ★ C3 是"整圈绕在身上"，不再有"对着最近的那只斩一发"这件事 ⟹ 整支交给 stepSwordRing。
    if ((this.evolved.sword || 0) >= 2) { this.stepSwordRing(dt); return; }
    const S = this.sword;
    if (S.cd > 0) S.cd -= dt;
    if (S.cd > 0) return;
    const tgt = this.nearestEnemy(ARENA.SWORD_RANGE);
    // §4-8 一-2 同款闸门：不许隔空砍屏幕外的怪（否则对着空气"唰"一下，节拍白耗）。
    if (tgt && ARENA.WEAPON_VIEW_CLIP
      && (Math.abs(tgt.x - this.player.x) - tgt.r > this.w / 2
        || Math.abs(tgt.y - this.player.y) - tgt.r > this.h / 2)) return;
    if (!tgt) return;   // 射程内无目标：不消耗节拍，等敌人走近
    S.cd = S.interval;
    const px = this.player.x, py = this.player.y;
    const baseAng = Math.atan2(tgt.y - py, tgt.x - px);
    const n = S.count;
    // C1 用 SWORD_SPREAD 那点夹角（≈16°，读起来是"一道厚斩"而不是三条平行线）；
    // C2 进化后换成整整 100° 的平均分布 —— 同一个"多道"的数字，两种完全不同的画面。
    const spread = (this.evolved.sword || 0) >= 1
      ? ARENA.SWORD_C2_SPREAD / Math.max(1, n - 1)
      : ARENA.SWORD_SPREAD;
    for (let i = 0; i < n; i++) {
      const off = n === 1 ? 0 : (i - (n - 1) / 2) * spread;
      const ang = baseAng + off;
      this.projectiles.push({
        x: px, y: py,
        vx: Math.cos(ang) * S.speed, vy: Math.sin(ang) * S.speed,
        r: ARENA.SWORD_R, life: ARENA.SWORD_LIFE, dead: false,
        dmg: S.dmg, pierce: true, maxDist: ARENA.SWORD_RANGE, sword: true, src: 'sword', ang, hits: [],
      });
    }
    this.swordCasts += 1;
  }

  /**
   * 阶段 5 · C3 环绕剑气：SWORD_C3_N 把刀锁在玩家周围一圈持续旋转，擦到的敌人按 tick 结算。
   *
   * ★ 三个必须这么写的点：
   *   1) **按 tick 节流**（SWORD_C3_TICK），不是逐帧 —— 否则同一只怪贴着刀时被逐帧磨，
   *      实际 DPS 随帧率浮动（60fps 和 30fps 不是同一把武器），直接违反"可复现"这条冻结项。
   *      同一 tick 里一只怪也只挨一刀（break），和环绕刃同一个口径：多把刀提升的是**覆盖**、
   *      不是单体秒伤 —— 否则 SWORD_C3_N=12 会把它变成一把无解的近身绞肉机。
   *   2) **每帧从玩家坐标重算**：刀跟着人走，位置不能存（玩家一直在移动）。
   *   3) **不进 projectiles**：那一套是有初速/有寿命/会飞出去的实体（还要按 reach 回收），
   *      环绕刀三样都不成立，硬塞进去只会给通用那条链添一堆 `if (p.orb)` 的特例。
   */
  stepSwordRing(dt) {
    const S = this.sword, R = this.swordRing;
    R.ang = (R.ang + ARENA.SWORD_C3_SPIN * dt) % TAU;
    const n = ARENA.SWORD_C3_N;
    const px = this.player.x, py = this.player.y;
    const blades = this.swordBlades;
    blades.length = 0;
    for (let i = 0; i < n; i++) {
      const a = R.ang + (i / n) * TAU;
      // 刀锋**垂直于半径**（切线方向）—— 绕圈的刀是"横着剐过去"，不是"尖对着外面扎"。
      blades.push({ x: px + Math.cos(a) * ARENA.SWORD_C3_R, y: py + Math.sin(a) * ARENA.SWORD_C3_R,
        ang: a + Math.PI / 2, r: ARENA.SWORD_R });
    }
    R.tick -= dt;
    if (R.tick > 0) { this.enemies = this.enemies.filter((e) => !e.dead); return; }
    R.tick = ARENA.SWORD_C3_TICK;
    // 预筛：只有"卡在环带厚度里"的怪才可能挨刀 —— 绝大多数敌人（包括所有在途的）离这条环很远。
    const band = ARENA.SWORD_R + ARENA.SWORD_C3_R;
    for (const e of this.enemies) {
      if (e.dead) continue;
      const dx = e.x - px, dy = e.y - py;
      const dd = Math.sqrt(dx * dx + dy * dy);
      if (dd > band + e.r || dd < ARENA.SWORD_C3_R - ARENA.SWORD_R - e.r) continue;
      for (const b of blades) {
        const ex = b.x - e.x, ey = b.y - e.y;
        const rr = ARENA.SWORD_R + e.r;
        if (ex * ex + ey * ey > rr * rr) continue;
        const ux = dd > 0.001 ? dx / dd : 1, uy = dd > 0.001 ? dy / dd : 0; // 由玩家指向敌人（往外剐）
        this.applyHit(e, S.dmg, { ux, uy, dist: ARENA.DEATH_DRIFT, live: false }, false, 'sword');
        break;
      }
    }
    this.enemies = this.enemies.filter((e) => !e.dead);
  }

  // ── 技能：一个键/一个按钮循环释放（spec §3 允许的最简方案）──

  /** 当前持有的技能，按 SKILL_ORDER 排好（循环释放的次序）。 */
  skillOrder() { return SKILL_ORDER.filter((k) => this.skills[k]); }
  skillReady(k) {
    if (k === 'shockwave') return this.shockwaveCd <= 0 && this.shockChargeT < 0;
    if (k === 'dash') return this.dashCd <= 0;
    if (k === 'frost') return this.frostCd <= 0;
    return false;
  }
  skillCd(k) {
    if (k === 'shockwave') return this.shockwaveCd;
    if (k === 'dash') return this.dashCd;
    if (k === 'frost') return this.frostCd;
    return 0;
  }
  /** 循环指针当前指向的技能（按钮上显示的那个，不管冷却）。 */
  cursorSkill() {
    const ks = this.skillOrder();
    return ks.length ? ks[this.skillCursor % ks.length] : null;
  }
  /** 按一下会放出哪个（从指针往后第一个就绪的）。 */
  nextSkill() {
    const ks = this.skillOrder();
    for (let i = 0; i < ks.length; i++) {
      const k = ks[(this.skillCursor + i) % ks.length];
      if (this.skillReady(k)) return k;
    }
    return null;
  }
  /**
   * 放技能。阶段 3 起支持两种入口：
   *  · castSkill(id) —— 放**指定**技能（空格/Q/E 三槽各自绑一个固定技能）。
   *    未持有或冷却中 → 直接 no-op，绝不偷偷放别的技能。
   *  · castSkill()  —— 不传 id，从循环指针往后找第一个就绪的放出去（驾驶员 / 旧"一个键打天下"口径）。
   * ★ 为什么还要"循环"：冲击波 CD 最短，写死优先级的话它一好就抢先，dash / frost 会因为
   *   CD 更长而**永远轮不到**。指针前移保证三个技能轮流上场。
   */
  castSkill(id) {
    if (this.done || this.pendingUpgrade) return false;
    if (id) {
      if (!this.skills[id] || !this.skillReady(id)) return false;
      const ok = id === 'shockwave' ? this.shockwave() : id === 'dash' ? this.dashCast() : this.frostCast();
      if (ok) { this.skillCasts += 1; return true; }
      return false;
    }
    const ks = this.skillOrder();
    for (let i = 0; i < ks.length; i++) {
      const idx = (this.skillCursor + i) % ks.length;
      const k = ks[idx];
      if (!this.skillReady(k)) continue;
      const ok = k === 'shockwave' ? this.shockwave() : k === 'dash' ? this.dashCast() : this.frostCast();
      if (ok) { this.skillCursor = (idx + 1) % ks.length; this.skillCasts += 1; return true; }
    }
    return false;
  }

  /** 闪现冲刺（spec §3）：朝移动方向瞬移，途中无敌并撞伤沿途敌人。 */
  dashCast() {
    const d = this.skDash;
    let ux = this.lastDir.x, uy = this.lastDir.y;
    if (ux === 0 && uy === 0) { ux = this.player.vx; uy = this.player.vy; }
    let m = Math.sqrt(ux * ux + uy * uy);
    if (m < 1e-6) { ux = 0; uy = -1; m = 1; }  // 站定不动也要放得出来（默认朝上）
    ux /= m; uy /= m;
    const p = this.player;
    // 阶段 4-1：闪现不再被墙截断（无限场），位移严格等于 DASH_DIST ——
    // 旧口径下贴着边按 Q 会"闪不动"，那是边界造成的、不是技能本身。
    const nx = p.x + ux * d.dist;
    const ny = p.y + uy * d.dist;

    // 沿途伤害：点到线段的距离 < 半宽 + 敌人半径
    const half = ARENA.DASH_W * 0.5;
    const sx = nx - p.x, sy = ny - p.y;
    const len2 = sx * sx + sy * sy || 1;
    for (const e of this.enemies) {
      if (e.dead) continue;
      let t = ((e.x - p.x) * sx + (e.y - p.y) * sy) / len2;
      t = t < 0 ? 0 : t > 1 ? 1 : t;
      const cx = p.x + sx * t, cy = p.y + sy * t;
      const dx = e.x - cx, dy = e.y - cy;
      if (dx * dx + dy * dy > (half + e.r) * (half + e.r)) continue;
      // 阶段 4-7：走统一伤害入口（护盾吸收 / 击杀 / 命中读数一套口径）。
      this.applyHit(e, d.dmg, { ux, uy, dist: ARENA.DEATH_DRIFT, live: false }, false, 'dash');
    }
    this.enemies = this.enemies.filter((e) => !e.dead);

    this.pushFx({ kind: 'dash', x0: p.x, y0: p.y, x1: nx, y1: ny, r: p.r, t: 0, life: ARENA.DASH_FX });
    p.x = nx; p.y = ny;
    this.dashInvuln = d.invuln;   // 阶段 4-9：读运行时值，`kd_invuln` 升级才落得下去
    this.dashCd = d.cdBase * this.cdMul;
    return true;
  }

  /** 霜环（spec §3）：冻住范围内的敌人。冻结期间既不移动也不啃你。 */
  frostCast() {
    const f = this.skFrost;
    let k = 0;
    for (const e of this.enemies) {
      if (e.dead) continue;
      const dx = e.x - this.player.x, dy = e.y - this.player.y;
      if (dx * dx + dy * dy > (f.r + e.r) * (f.r + e.r)) continue;
      // 阶段 4-4：Boss 的冻结时长减半（spec 四「不能被霜环定到死」）。
      // ★ 是"减半"而不是"免疫"：完全免疫会让霜环对 Boss 毫无意义，减半则仍是有效的喘息窗口。
      e.frozen = f.dur * (isBossKind(e.kind) ? ARENA.BOSS_FROST_MUL : 1);
      k += 1;
    }
    this.pushFx({ kind: 'frost', x: this.player.x, y: this.player.y, r: f.r, t: 0, life: ARENA.FROST_FX });
    this.frostCd = f.cdBase * this.cdMul;
    this.frostCasts += 1;
    if (k) this.floatText(this.player.x, this.player.y - 34, `冻结 ${k}`, COLOR.frost);
    return true;
  }

  /** 短特效入队（容量满时淘汰最旧的 —— 与 burst 同一策略：保住最新的一次） */
  pushFx(f) {
    if (this.fx.length >= ARENA.MAX_FX) this.fx.shift();
    this.fx.push(f);
    return f;
  }

  /** 宝箱落点（spec §5）：玩家附近**最空**的位置。
   *  ★ "安全位置"不是装饰：宝箱若刷在敌堆里，走近就开 = 走近就吃伤害，
   *    玩家会学会"放弃宝箱"，那这个系统等于没做。所以这里真的去数敌人。 */
  spawnChest(at = null, gold = false) {
    if (this.chests.length >= ARENA.MAX_CHESTS) return null;
    const p = this.player;
    let best = null, bestN = Infinity;
    // 阶段 4-4：Boss 掉的是**大金箱**，直接落它倒下的地方（不走"挑最空的候选点"采样）——
    //   玩家刚打死 Boss，位置就在眼前，把奖励扔到别处等于没给。
    if (at) {
      best = { x: at.x, y: at.y };
    }
    // ★ 给了落点就不再采样 —— 采样会白抽 2~28 个随机数，而 Boss 金箱的落点是**确定的**。
    for (let i = 0; !at && i < ARENA.CHEST_TRIES; i++) {
      const a = this.rng.next() * TAU;
      const d = ARENA.CHEST_MIN_D + this.rng.next() * (ARENA.CHEST_MAX_D - ARENA.CHEST_MIN_D);
      // 阶段 4-1：以玩家为极坐标直接取值，不再夹回场地（无限场）。
      // "离玩家 110~250px" 本来就是这条落点规则的全部意图，夹回场地反而是**反意图**的：
      // 玩家贴近旧场边时，夹取会把一串候选点压到同一条边上，"挑最空的一个"退化成"挑边上最左的一个"。
      const x = p.x + Math.cos(a) * d;
      const y = p.y + Math.sin(a) * d;
      let k = 0;
      for (const e of this.enemies) {
        const dx = e.x - x, dy = e.y - y;
        if (dx * dx + dy * dy <= ARENA.CHEST_SAFE_R * ARENA.CHEST_SAFE_R) k += 1;
      }
      if (k < bestN) { bestN = k; best = { x, y }; }
      if (k === 0) break; // 已经够空，没必要再采样
    }
    const ch = { x: best.x, y: best.y, r: ARENA.CHEST_R, t: 0, dead: false, gold: !!gold };
    this.chests.push(ch);
    return ch;
  }

  /** 开箱（spec §5）：直接给一件稀有货，**不弹选择**。
   *  优先级：未拥有的新武器/新技能 → 高品被动 → 任意未封顶被动 → 兜底 regen。 */
  openChest(ch) {
    let from = OFFERS.filter((o) => o.unlock && o.avail(this));
    if (!from.length) from = OFFERS.filter((o) => o.cat === 'passive' && o.avail(this) && RARE_PASSIVES.includes(o.id));
    if (!from.length) from = OFFERS.filter((o) => o.cat === 'passive' && o.avail(this));
    const o = from.length ? this.rng.weighted(from, (x) => x.weight) : offerById('regen');
    if (!o) return null;
    this.applyUpgrade(o.id);
    this.chestsOpened += 1;
    // 阶段 4-4：金箱开出来的动静更大（碎屑更多 + 横幅写出拿到了什么 —— 那是"打完 Boss 的奖励"）
    if (!this.reduced) {
      this.burst(ch.x, ch.y, COLOR.gold, ch.gold ? 22 : 14);
      if (ch.gold) this.milestones.push({ text: `获得 ${o.label}`, t: 0, life: ARENA.MILE_FADE });
    }
    this.pushFx({ kind: 'chest', x: ch.x, y: ch.y, r: ch.r, t: 0, life: ARENA.CHEST_OPEN });
    this.floatText(ch.x, ch.y - 20, o.label, COLOR.gold);
    ch.dead = true;
    return o;
  }

  /**
   * 阶段 4-3：**不消耗 rng 的伪随机**（粒子 / 碎屑这类纯表现专用）。
   *
   * ★★ 为什么必须另起一条：burst() 原来每个粒子抽 3 次 rng（角度/速度/生命），
   *   于是"每只怪死时消耗多少个随机数"**被粒子数绑死了**。阶段 4-3 把碎屑从 4 提到 8~12，
   *   相当于每次击杀多消耗 12~24 个随机数 —— 整条**主随机流被整体平移**，
   *   而"跑满 10 分钟 / 最低血量 70.7 / 空档 43.2s"这组已标定的读数全部是在
   *   旧流上测出来的。实测后果：16 局里冒出 minHp 0~5 的濒死局（不是难度变了，
   *   是同一批种子抽到了完全不同的升级序列）。
   *   ⟹ 表现层的随机**一律不碰主 rng**（与宝石掉落、里程碑同一条纪律）：
   *      这样以后调粒子数、调碎屑密度都不会再动到平衡口径。
   *   用的是整数哈希（murmur3 finalizer）：无状态、可复现、比 rng.next() 还快。
   */
  _frand() {
    const k = (this._fxSpin = (this._fxSpin + 1) | 0);
    let x = Math.imul(k ^ 0x9e3779b9, 0x85ebca6b);
    x ^= x >>> 13; x = Math.imul(x, 0xc2b2ae35); x ^= x >>> 16;
    return (x >>> 0) / 4294967296;
  }

  /**
   * 粒子爆。dir 非空时朝该方向飞散（冲击波"扫开"用），否则全向散开。
   * 容量满时**淘汰最旧的**而不是丢弃新的：密度上来后碎屑会瞬间填满上限，
   * 若"满了就丢新的"，之后每次击杀的粒子都看不见（而"最新的效果"恰恰最该被看到）。
   *
   * @param {number} legacyN 前多少颗粒子**继续消耗主 rng**（默认 = n，即全部消耗）。
   *   ★★ 阶段 4-3 加这个参数，是为了把"粒子数"与"主随机流的消耗量"**解耦**：
   *     老口径是普通怪 4 颗 / 精英 7 颗，每颗抽 4 次 rng ⟹ 每次击杀固定消耗 16 / 28 个随机数。
   *     把碎屑提到 8~12 之后若每颗都抽 rng，每次击杀会多消耗 16~32 个 —— **主随机流被整体平移**，
   *     而"跑满 16/16 / 最低血 70.7 / 空档 43.2s"这组读数全是在旧流上标定的。
   *     实测过（不这么做的话）：16 局里冒出 minHp 0~5 的濒死局，而难度参数一个字没动。
   *     ⟹ 前 legacyN 颗照旧用 rng（消耗量逐字节不变），多出来的走 _frand（表现层伪随机）。
   */
  burst(x, y, color, n = 8, dir = null, legacyN = n) {
    const base = dir ? Math.atan2(dir.y, dir.x) : 0;
    for (let i = 0; i < n; i++) {
      if (this.particles.length >= ARENA.MAX_PARTICLES) this.particles.shift();
      const useRng = i < legacyN;
      const r1 = useRng ? this.rng.next() : this._frand();
      const r2 = useRng ? this.rng.next() : this._frand();
      const r3 = useRng ? this.rng.next() : this._frand();
      const r4 = useRng ? this.rng.next() : this._frand();
      const a = dir ? base + (r1 - 0.5) * 1.1 : r1 * TAU;
      const sp = (dir ? 120 : 40) + r2 * 120;
      this.particles.push({
        x, y, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp - 30,
        color, r: 1.5 + r3 * 2,
        life: ARENA.PARTICLE_LIFE_MIN + r4 * (ARENA.PARTICLE_LIFE_MAX - ARENA.PARTICLE_LIFE_MIN),
      });
    }
  }

  /** 结算读数（spec §1：存活时间 + 总击杀数；其余是复盘用的附加读数） */
  result() {
    return {
      survived: this.survived,
      survivalMs: Math.min(this.time, this.durationMs),
      survivalSec: Math.round(Math.min(this.time, this.durationMs) / 1000),
      kills: this.kills,
      level: this.level,
      gems: this.gemsCollected,
      casts: this.shockCasts,
      // 阶段 4-9：击杀来源归因（arena-sim 的「技能 <15% / 武器 >80%」硬断言读它）
      killSrc: Object.assign({}, this.killSrc),
      spawned: this.spawned,
      upgrades: this.upgradesTaken.slice(),
      // 阶段 2 复盘读数
      weapons: Object.keys(this.weapons).filter((k) => this.weapons[k]),
      skills: Object.keys(this.skills).filter((k) => this.skills[k]),
      chests: this.chestsOpened,
      skillCasts: this.skillCasts,   // casts 仍是冲击波次数（阶段 1 的口径不动）
      // 阶段 4-1 复盘读数（不影响任何判定）
      elites: this.eliteSpawned,
      bullets: this.bulletsFired,
      // 阶段 4-1.1：远程怪自证（spec 要求 arena-sim 直接报这三个数）
      ranged: this.rangedSpawned,
      bulletHits: this.bulletHits,
      // 阶段 4-1.2：贴身围堵自证（"每 8 秒补 3~4 只"有没有真的发生）
      swarm: this.swarmSpawned,
      // 阶段 4-7.x：心心掉落计数（arena-sim 自证"回血掉落真的在发生"）
      hearts: this.heartsDropped,
      // 阶段 4-12：事件触发计数（arena-sim 自证"突发事件真的在按时间表发生"）
      events: Object.assign({}, this.eventLog),
      // 阶段 4-7：各怪类型出场计数（arena-sim 自证"新机制怪真的在刷"）
      kindCounts: Object.assign({}, this.kindCounts),
      // 阶段 4-3：连杀（纯显示，不参与任何数值判定；这里只是给结算页一个读数）
      comboBest: this.comboBest,
      // 阶段 4-3：里程碑达成情况（结算页用来回看"这局走到过哪几步"）
      milestones: ARENA.MILESTONES.filter((m, i) => this.mileFlags[i]).map((m) => m.text),
      // 阶段 4-4：Boss 自证（spec 的验收要 arena-sim 报"8 局里 Boss1/Boss2 各打死几只"）
      bossSpawned: this.bossSpawned.slice(),
      bossKills: this.bossKills.slice(),
      // 阶段 4-5：本局用的是哪个英雄（账号系统累计"各角色最高纪录"用）
      hero: this.heroId,
      // 阶段 6-4：魂火商栈复盘读数（arena-sim 自证「商店真的开了 3 次、货币在涨」）
      soulfire: this.soulfire,
      shopVisits: this.shopVisits,
      shopSpend: this.shopSpend,
      shopBought: this.shopBought.slice(),
    };
  }

  /** 给无头测试用的快照（断言不出 NaN / 不卡死 / 不越界） */
  snapshot() {
    const finite = (v) => typeof v === 'number' && isFinite(v);
    const speed = Math.sqrt(this.player.vx * this.player.vx + this.player.vy * this.player.vy);
    const ok =
      finite(this.player.x) && finite(this.player.y) && finite(speed) &&
      finite(this.hp) && finite(this.time) && finite(this.magnet) &&
      finite(this.dmg) && finite(this.moveSpeed) && finite(this.attackInterval) &&
      this.enemies.every((e) => finite(e.x) && finite(e.y) && finite(e.hp)) &&
      this.projectiles.every((p) => finite(p.x) && finite(p.y)) &&
      this.bullets.every((b) => finite(b.x) && finite(b.y) && finite(b.vx) && finite(b.vy)) &&
      this.gems.every((g) => finite(g.x) && finite(g.y)) &&
      this.floaters.every((f) => finite(f.x) && finite(f.y)) &&
      this.deaths.every((d) => finite(d.x) && finite(d.y)) &&
      this.chests.every((ch) => finite(ch.x) && finite(ch.y)) &&
      this.fx.every((f) => finite(f.t)) &&
      finite(this.orbit.ang) && finite(this.orbit.count) && finite(this.laser.cd) &&
      finite(this.projSpeed) && finite(this.cdMul) && finite(this.knockMul) &&
      finite(this.dashCd) && finite(this.frostCd) && finite(this.dashInvuln)
      && finite(this.soulfire);
    return {
      time: this.time, hp: this.hp, done: this.done, survived: this.survived,
      level: this.level, enemies: this.enemies.length, particles: this.particles.length,
      bullets: this.bullets.length,
      gems: this.gems.length, floaters: this.floaters.length, deaths: this.deaths.length,
      kills: this.kills, gemsCollected: this.gemsCollected, casts: this.shockCasts,
      spawned: this.spawned, shots: this.shots, magnet: this.magnet,
      chests: this.chests.length, fx: this.fx.length, chestsOpened: this.chestsOpened,
      skillCasts: this.skillCasts,
      weapons: Object.keys(this.weapons).filter((k) => this.weapons[k]).length,
      skills: Object.keys(this.skills).filter((k) => this.skills[k]).length,
      // 手感层的可观测面（测试靠这几项断言"不瞬移、不瞬停、动画没走完不消失"）
      speed, charging: this.shockChargeT >= 0,
      finite: ok,
    };
  }
}

/**
 * DOM 包装层：canvas 渲染 + 双端操控（悬浮摇杆 / WASD·方向键）+ rAF 循环 + 三选一弹窗。
 * 仅在浏览器中实例化（依赖 document / window / requestAnimationFrame）。
 */
export class Arena {
  constructor({ stage, rng, reducedMotion = false, onDone, meta = {} }) {
    this.stage = stage;
    this.rng = rng;
    this.reduced = reducedMotion;
    this.onDone = onDone;
    this.meta = meta || {}; // 阶段 3 元进度：透传给 ArenaCore 开局套用
    this.skin = skinById(this.meta.skin || DEFAULT_SKIN).id;  // 阶段 6-2：皮肤（纯渲染，乱 id 归一到默认）
    this.core = null;
    this.raf = 0;
    this.ended = false;
    this.last = 0;
    this.input = { x: 0, y: 0 };
    this.joy = { x: 0, y: 0, active: false, ox: 0, oy: 0, vx: 0, vy: 0, pid: null };
    this.keys = new Set();
    // 自动驾驶员接缝：非 null 时**接管**输入 / 技能 / 三选一（消费点见 _loop）。
    // 契约：driver.tick(core) → { input:{x,y}, shock:boolean, pick:index }
    //   · input  已归一化的方向向量（不与键盘相加，见 _loop 的理由）
    //   · shock  true 则本帧尝试放冲击波（由 core 自己判冷却）
    //   · pick   三选一的下标。**无人值守时没人点弹窗，必须由它代选** ——
    //           否则 pendingUpgrade 不清，游戏会永远停在那一帧。
    // 由 main.js（?pilot=1）或 tools/record-demo.mjs 从外部赋值；null = 纯真人操作。
    this.driver = null;
    // 离屏精灵缓存：形状是静态的，没有理由每帧重新光栅化一条 20 点的路径。
    // key = `${kind}:${flashLevel}`，惰性构建（只画得到的类型才会被烘焙）。
    this._sprites = new Map();
    this._paths = new Map();
    this._flash = new Map();
    this._boxes = new Map(); // 每类型的剪影包围盒缓存
    // 渲染/输入侧的小状态（避免每帧重复写 DOM / 重复解析字体）
    this._needsPaint = true;
    this._skillTxt = '';
    this._f1 = ''; this._f2 = '';
    this._fps = 0;
    // 阶段 6-1：渲染剖析开关。只在 ?dbg=1 下建表（关掉时 _pmark/_pdone 各只做一次空判断）。
    this.prof = DBG ? {} : null;
    this._pT0 = 0;
    // 阶段 3 精灵缓存：id → Image（懒加载）。_loaded/_failed 在 onload/onerror 里置位。
    // 未加载完或加载失败 → 渲染时回退剪影（见 _drawEntity）。
    this._imgs = {};
    this._imgFailed = {};
    this._whiteMask = {};   // id → 白闪蒙版离屏 canvas（死亡闪白用，只烘焙一次）
    this._eliteMask = {};   // id → 精英红蒙版离屏 canvas（"颜色更红"，同样只烘焙一次）
    this._skinMasks = {};   // 阶段 6-2：皮肤 id → 英雄色调蒙版离屏 canvas（只烘焙一次）
    // ── 阶段 4-1：相机 ──
    // cam 是渲染层的**私有**状态，core 一无所知（core 不该知道有相机这回事）。
    // 初值 (0,0) 就是世界原点，也是玩家的出生点；_camReady=false 让第一帧直接"咔"到位，
    // 而不是从某个角落里滑过去。
    this.cam = { x: 0, y: 0 };
    this._camReady = false;
    this._dpr = 1;          // _resize 里更新；_render 每帧用它重置基准变换
    // ── 阶段 4-3：屏震（相机偏移）与中央横幅 ──
    // ★ 两者都是**纯渲染层**状态：core 一无所知，也不会被它们反写。
    this._shakeT = 0;       // 剩余屏震时长 s
    this._shakeAmp = 0;     // 本次屏震的峰值幅度 px（≤ SHAKE_AMP）
    this._shakeClock = 0;   // 抖动用的一路时钟（正弦取相位，不消耗 rng，也不依赖帧号）
    this._shakeX = 0; this._shakeY = 0;
    // 中央横幅（里程碑 / 后一阶段的 Boss 警告）：渲染层自己计时淡出，core 只负责 push。
    this._banners = [];
    // 阶段 3 音效：每帧比对 core 状态增量来触发声音，这里存"上一帧的快照"
    this._sfx = { level: 0, hits: 0, kills: 0, chests: 0, casts: 0, hp: ARENA.PLAYER_HP, over: false };
    this._muteBtn = null;
  }

  start() {
    const w = this.stage.clientWidth || 360;
    const h = this.stage.clientHeight || 640;
    this.core = new ArenaCore({ rng: this.rng, width: w, height: h, reducedMotion: this.reduced, meta: this.meta });

    // ── 构建 DOM ──
    const root = document.createElement('div');
    root.className = 'arena-root';
    root.innerHTML = `
      <canvas class="arena-canvas"></canvas>
      <div class="arena-inventory"></div>
      <button class="arena-mute" type="button" aria-label="音效开关"><span>音</span></button>
      <div class="arena-hint">拖动屏幕移动 · WASD/方向键亦可 · 空格/Q/E 放技能</div>
      <div class="arena-skillbar">
        <button class="skill-slot" data-k="shockwave" aria-label="冲击波（空格）"><b>空格</b><span>波</span></button>
        <button class="skill-slot" data-k="dash" aria-label="闪现（Q）"><b>Q</b><span>闪</span></button>
        <button class="skill-slot" data-k="frost" aria-label="霜环（E）"><b>E</b><span>霜</span></button>
      </div>
      <div class="arena-levelup" hidden>
        <div class="alu-title">升级！三选一</div>
        <div class="alu-choices"></div>
      </div>
      <div class="arena-shop" hidden>
        <div class="shop-title">魂火商栈</div>
        <div class="shop-balance"></div>
        <div class="shop-choices"></div>
        <button class="shop-skip" type="button">下次再来</button>
      </div>`;
    this.root = root;
    this.canvas = root.querySelector('.arena-canvas');
    this.ctx = this.canvas.getContext('2d');
    this.levelupEl = root.querySelector('.arena-levelup');
    this.choicesEl = root.querySelector('.alu-choices');
    // 阶段 6-4：魂火商栈覆盖层（局内商店；driver 在场时由 _loop 自动跳过，不弹这个）
    this.shopEl = root.querySelector('.arena-shop');
    this.shopChoicesEl = root.querySelector('.shop-choices');
    this.shopBalanceEl = root.querySelector('.shop-balance');
    this.shopEl.querySelector('.shop-skip').onclick = () => {
      this.core?.resolveShop([]);
      this.shopEl.hidden = true;
      this._needsPaint = true; // 恢复后补一帧，避免暂停期间跳过的重绘留下旧画面
    };
    this.invEl = root.querySelector('.arena-inventory');   // 阶段 3：持有物图标栏
    this._invSig = '';                                      // 仅当持有签名变化时才重写 DOM
    // 阶段 3：音效静音开关（持久化在 localStorage，见 sfx.js）
    this._muteBtn = root.querySelector('.arena-mute');
    const syncMute = () => {
      const m = Sfx.isMuted();
      if (this._muteBtn) {
        this._muteBtn.querySelector('span').textContent = m ? '静' : '音';
        this._muteBtn.classList.toggle('muted', m);
      }
    };
    syncMute();
    this._muteBtn.onclick = () => { Sfx.setMuted(!Sfx.isMuted()); syncMute(); };
    // 阶段 3：三个主动技能槽（空格=冲击波 / Q=闪现 / E=霜环），各自独立释放
    this.skillBar = root.querySelector('.arena-skillbar');
    this.skillSlots = {};
    for (const el of root.querySelectorAll('.skill-slot')) {
      const k = el.getAttribute('data-k');
      this.skillSlots[k] = el;
      // 阶段 4-6：用 pointerdown 而非 onclick —— 触屏上点技能能**即时**释放，且 stopPropagation
      // 不让这一指的事件冒泡到 window 的摇杆 move/up（即使没按 pid 过滤也是双保险）。
      // preventDefault 阻止浏览器合成 click，避免「点一下放两次」。
      el.addEventListener('pointerdown', (e) => {
        e.preventDefault();
        e.stopPropagation();
        this.core?.castSkill(k);   // 移动端：点槽位 = 放对应技能（与端游空格/Q/E 等价）
      });
    }
    this.stage.appendChild(root);
    this._resize();

    // ── 输入：悬浮摇杆（指针事件，触屏/鼠标统一） + 键盘 ──
    // 坑：joy.ox/oy 必须是**画布坐标**（_render 直接拿它们画圈），而 clientX/Y 是视口坐标。
    // 第一版把视口坐标直接当画布坐标用 → 画出来的摇杆比手指低一个 HUD 的高度（实测偏移 86px）。
    // 移动方向仍然正确（方向来自位移差，平移量会抵消），但视觉完全对不上，用户会以为摇杆坏了。
    // 因此分开存两套：vx/vy 视口坐标（只用于算位移差）、ox/oy 画布坐标（只用于绘制）。
    // ── 阶段 4-6：多指触屏 ──
    // 摇杆只认「启动它的那一指」（pid）。window 上的 pointermove/up 是全局的，
    // 如果不按 pid 过滤，另一根手指（比如去点技能槽的那根）移动/抬起时也会改摇杆、甚至把摇杆关掉——
    // 这正是「拖摇杆时按不了技能」的根因。按 pid 过滤后，两根手指各干各的、互不干扰。
    this._onPointerDown = (e) => {
      const r = this.canvas.getBoundingClientRect();
      Sfx.resume();   // 阶段 3：首次手势里解锁 AudioContext（浏览器自动播放策略）
      this.joy.active = true;
      this.joy.pid = e.pointerId;
      this.joy.vx = e.clientX; this.joy.vy = e.clientY;
      this.joy.ox = e.clientX - r.left; this.joy.oy = e.clientY - r.top;
      this.joy.x = 0; this.joy.y = 0;
      this.canvas.setPointerCapture?.(e.pointerId);
    };
    this._onPointerMove = (e) => {
      if (!this.joy.active || e.pointerId !== this.joy.pid) return;
      const dx = e.clientX - this.joy.vx, dy = e.clientY - this.joy.vy;
      const max = 48;
      const m = Math.sqrt(dx * dx + dy * dy);
      const k = m > max ? max / m : 1;
      this.joy.x = (dx * k) / max;
      this.joy.y = (dy * k) / max;
    };
    this._onPointerUp = (e) => {
      if (e.pointerId !== this.joy.pid) return;   // 只有启动摇杆的那根手指抬起才松摇杆
      this.joy.active = false;
      this.joy.pid = null;
      this.joy.x = 0; this.joy.y = 0;
    };
    this.canvas.addEventListener('pointerdown', this._onPointerDown);
    window.addEventListener('pointermove', this._onPointerMove);
    window.addEventListener('pointerup', this._onPointerUp);
    window.addEventListener('pointercancel', this._onPointerUp);

    // 防「卡键 / 卡摇杆」：失焦或页面切走时 keyup / pointerup 可能收不到，
    // 残留状态会让输入恒偏一个方向。**这正是「某个方向完全走不动」的典型成因** ——
    // 左右两键同时残留时，−1 与 +1 相加恰好抵消成 0（摇杆残留同理）。
    this._resetInput = () => {
      this.keys.clear();
      this.joy.active = false;
      this.joy.pid = null;
      this.joy.x = 0; this.joy.y = 0;
    };
    window.addEventListener('blur', this._resetInput);
    document.addEventListener('visibilitychange', this._resetInput);

    this._onKeyDown = (e) => {
      Sfx.resume();   // 阶段 3：键盘手势同样解锁音频
      // ★ 体检（中文输入法 / 文本输入框）：焦点在输入框里，或正处于输入法组字（IME）过程中，
      //   **一律不劫持按键**。否则在起名框里打中文时，组字用的字母会被当成游戏键吃掉：
      //   例：打「张」= z h a n g，其中的 a 命中 WASD 移动键 → 被 add 进 keys 且 preventDefault，
      //   IME 收不到这次按键 ⟹ 表现为「首键丢失 / 打不出字」。
      //   e.isComposing 是标准标志；keyCode 229 是 IME 组字期间的老浏览器兜底。
      const tgt = e.target;
      const inField = !!tgt && (tgt.tagName === 'INPUT' || tgt.tagName === 'TEXTAREA' || tgt.isContentEditable === true);
      if (inField || e.isComposing || e.keyCode === 229) return;
      if (ARENA_KEYS.has(e.key)) { this.keys.add(e.key); e.preventDefault(); }
      // 阶段 3：空格/Q/E 各自放一个固定技能（slot 绑定见 SKILL_SLOT_KEYS）。
      // 未拥有的槽按下是 no-op（core.castSkill(id) 会先判持有），不会误放别的技能。
      else if (e.code === 'Space' || e.key === ' ') { e.preventDefault(); this.core?.castSkill('shockwave'); }
      else if (e.key === 'q' || e.key === 'Q') { e.preventDefault(); this.core?.castSkill('dash'); }
      else if (e.key === 'e' || e.key === 'E') { e.preventDefault(); this.core?.castSkill('frost'); }
    };
    this._onKeyUp = (e) => { this.keys.delete(e.key); };
    window.addEventListener('keydown', this._onKeyDown);
    window.addEventListener('keyup', this._onKeyUp);
    this._onResize = () => this._resize();
    window.addEventListener('resize', this._onResize);

    // 主动技能：端游空格/Q/E（见 _onKeyDown）/ 手游点技能槽（见 start 里 skillSlots 绑定）

    this.last = performance.now();
    this._preloadAssets();    // 阶段 3：图片异步加载；加载完前渲染层自动回退剪影
    this.raf = requestAnimationFrame((t) => this._loop(t));
  }

  /** 阶段 3：预加载精灵 PNG（Image 对象）。加载完再画真图，期间画剪影兜底，绝不白屏。
   *  onerror 置 _failed → 永远回退剪影（素材缺失也不崩）。
   *  URL 用 document.baseURI 解析：server.mjs 从项目根起服，assets/ 在根下，相对路径稳定。 */
  _preloadAssets() {
    if (typeof document === 'undefined') return; // 非浏览器环境（Node 单测不会进来，这里只是双保险）
    for (const id of Object.keys(SPRITE_FILE)) {
      let url;
      try { url = new URL('assets/' + SPRITE_FILE[id], document.baseURI).href; }
      catch { this._imgFailed[id] = true; continue; }
      if (OPTIONAL_SPRITES.has(id)) {
        // 可选素材：先探一次，文件在就正常加载，文件不在就**当作加载失败**（→ 用剪影）。
        fetch(url, { method: 'HEAD' })
          .then((r) => { if (r.ok) this._loadSprite(id, url); else this._imgFailed[id] = true; })
          .catch(() => { this._imgFailed[id] = true; });
      } else {
        this._loadSprite(id, url);
      }
    }
  }

  /** 真的建 Image 并挂 onload/onerror。加载完再烘两张蒙版（白闪 / 精英红），只做一次。 */
  _loadSprite(id, url) {
    const img = new Image();
    img._loaded = false;
    img._failed = false;
    img.onload = () => {
      img._loaded = true;
      this._buildMask(id, img, '#ffffff', this._whiteMask);          // 死亡闪白
      this._buildMask(id, img, ARENA.ELITE_TINT, this._eliteMask);   // 阶段 4-1 精英"更红"
      // 阶段 6-2：英雄皮肤蒙版（只有 hero 需要；color=null 的默认皮肤不烘）。
      if (id === 'hero') {
        for (const s of SKINS) if (s.color) this._buildMask(s.id, img, s.color, this._skinMasks);
      }
      this._needsPaint = true; // 加载完成补一帧，避免"先剪影后真图"之间卡旧画面
    };
    img.onerror = () => { img._failed = true; this._imgFailed[id] = true; };
    img.src = url;
    this._imgs[id] = img;
  }

  /** 烘焙一张"纯色蒙版"：保留原图的 alpha 形状，把颜色整个填成 color。
   *  用途有两个，都是"整张图换个颜色但形状不变"：死亡白闪（白）、精英品质（红）。
   *  用离屏 canvas 一次性烘好，绘制时只多一次 drawImage —— 不必每帧重光栅化，也不必改素材。
   *  `source-in` 是这里的关键：它按**目标已有像素的 alpha** 保留新填充，等于"按形状裁剪纯色块"。 */
  _buildMask(id, img, color, store) {
    if (!img.naturalWidth) return;
    const cv = document.createElement('canvas');
    cv.width = img.naturalWidth;
    cv.height = img.naturalHeight;
    const g = cv.getContext('2d');
    g.drawImage(img, 0, 0);
    g.globalCompositeOperation = 'source-in';
    g.fillStyle = color;
    g.fillRect(0, 0, cv.width, cv.height);
    store[id] = cv;
  }

  /** 按 r 与 SPRITE_FIT 算实体的绘制尺寸（居中绘制用）。返回 { dw, dh }。 */
  _entitySize(id, r) {
    const fit = SPRITE_FIT[id];
    const img = this._imgs[id];
    const ar = (img && img.naturalWidth) ? img.naturalWidth / img.naturalHeight : 1;
    if (fit.axis === 'w') { const dw = r * fit.k; return { dw, dh: dw / ar }; }
    const dh = r * fit.k; return { dw: dh * ar, dh };
  }

  /** 把某素材居中画到 (x, y)。成功返回 { dw, dh }，失败（未加载/失败）返回 null —— 调用方据此回退剪影。
   *  scaleMul 用于死亡动画的爆裂缩放；flip 水平翻转（朝向）。
   *  elite = true 时在真图之上再叠一层同形状的红蒙版（"颜色更红"），形状细节仍然透得出来。
   *  drawImage 外层自带 save/restore。 */
  _drawEntity(ctx, id, x, y, r, scaleMul = 1, flip = false, elite = false) {
    const img = this._imgs[id];
    if (!img || !img._loaded || img._failed || !img.naturalWidth) return null;
    const { dw, dh } = this._entitySize(id, r);
    const W = dw * scaleMul, H = dh * scaleMul;
    ctx.save();
    if (flip) { ctx.translate(x, y); ctx.scale(-1, 1); ctx.translate(-x, -y); }
    ctx.drawImage(img, x - W / 2, y - H / 2, W, H);
    if (elite && this._eliteMask[id]) {
      // 0.55 而不是 1.0：纯红会压掉素材的明暗层次，看起来像"被涂了一块色"。
      ctx.globalAlpha = 0.55;
      ctx.drawImage(this._eliteMask[id], x - W / 2, y - H / 2, W, H);
      ctx.globalAlpha = 1;
    }
    ctx.restore();
    return { dw: W, dh: H };
  }

  _resize() {
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    this._dpr = dpr;
    const w = this.stage.clientWidth || 360;
    const h = this.stage.clientHeight || 640;
    this.canvas.width = Math.round(w * dpr);
    this.canvas.height = Math.round(h * dpr);
    this.canvas.style.width = w + 'px';
    this.canvas.style.height = h + 'px';
    this.ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    if (this.core) this.core.setBounds(w, h);
  }

  _keyVec() {
    let x = 0, y = 0;
    if (this.keys.has('ArrowLeft') || this.keys.has('a') || this.keys.has('A')) x -= 1;
    if (this.keys.has('ArrowRight') || this.keys.has('d') || this.keys.has('D')) x += 1;
    if (this.keys.has('ArrowUp') || this.keys.has('w') || this.keys.has('W')) y -= 1;
    if (this.keys.has('ArrowDown') || this.keys.has('s') || this.keys.has('S')) y += 1;
    return { x, y };
  }

  _loop(now) {
    if (this.ended) return;
    const dt = Math.min(0.05, (now - this.last) / 1000);
    this.last = now;
    if (dt > 0) this._fps = Math.round(1 / dt);
    this._pmark();

    // 合成输入：**键盘优先于摇杆，而不是两者相加**。
    // 相加时「摇杆残留 + 反向按键」会互相抵消成 0，屏幕表现就是「左右都推不动」，
    // 与「根本没收到按键」完全一样，极难排查。互斥后任何一路输入都不会被另一路吃掉。
    const k = this._keyVec();
    const usingKeys = k.x !== 0 || k.y !== 0;
    let ix = usingKeys ? k.x : this.joy.x;
    let iy = usingKeys ? k.y : this.joy.y;
    const m = Math.sqrt(ix * ix + iy * iy);
    if (m > 1) { ix /= m; iy /= m; }
    this.input = { x: ix, y: iy };

    // 驾驶员一旦挂上就**接管**输入与技能，而不是与键盘/摇杆相加 ——
    // 相加会让残留按键把驾驶员规划好的走位拽偏（这正是"互斥而非相加"的同一条理由）。
    // 顺序有讲究：必须在上面合成完 this.input 之后、step 之前。
    const drive = this.driver ? this.driver.tick(this.core) : null;
    if (drive && drive.input) this.input = { x: drive.input.x, y: drive.input.y };
    if (drive && drive.cast) this.core.castSkill();
    if (this.core.pendingUpgrade && drive) {
      this.core.chooseUpgrade(drive.pick);
      this.levelupEl.hidden = true; // 驾驶员在场时不弹三选一：弹窗是给真人看的
      this._needsPaint = true;
    }
    // 阶段 6-4：魂火商栈。driver 在场时自动「下次再来」（不购买、不弹窗）——
    //   保持无人值守口径 = sim（resolveShop([])）；真人则由下方 _showShop 弹窗购买。
    if (this.core.shopOpen && drive) {
      this.core.resolveShop([]);
      this.shopEl.hidden = true;
      this._needsPaint = true;
    }

    const paused = !!this.core.pendingUpgrade || !!this.core.shopOpen;
    if (!this.core.done && !paused) {
      // 快进档（仅 ?speed=N 开发用）：同一帧内补跑多个子步，而不是放大 dt。
      // 放大 dt 会让惯性/死亡动画的时长口径随之失真、还可能隧穿过敌人；补步长则物理口径不变。
      const steps = this.fastForwardSteps || 1;
      for (let i = 0; i < steps && !this.core.done && !this.core.pendingUpgrade && !this.core.shopOpen; i++) {
        this.core.step(dt, this.input);
      }
      this._needsPaint = true;
    }

    this._pdone('step');
    // 阶段 4-1：相机跟随。放在 step **之后**、绘制**之前** ——
    // 这样"这一帧的画面"用的是"这一帧的脚步位置"，而不是上一帧的（差一帧的滞后肉眼看不出来，
    // 但它会让快速移动时中心偏一格，正好落在"人手最敏感"的尺度上）。
    this._updateCam(dt);

    // 阶段 4-3：中央横幅（里程碑）—— 从 core 搬过来并自己走淡出计时。
    // 放在这里而不是 _render 里：暂停（三选一）时 _render 不跑，横幅不该趁暂停偷偷计时。
    this._drainBanners();
    for (const b of this._banners) b.t += dt;
    this._banners = this._banners.filter((b) => b.t < (b.life || ARENA.MILE_FADE));

    // 阶段 3 音效：比对 core 状态增量触发对应声音（射击/命中/升级/技能/开箱/死亡/受伤）。
    this._syncSfx(this.core);

    // 暂停时不再每帧重绘：弹窗是全屏半透明遮罩，底下重绘既看不见又白烧 CPU/GPU
    if (this._needsPaint) {
    this._pdone('misc');
      this._render();
      this._needsPaint = false;
    }

    // ★ 用 pendingUpgrade 显式判断，不能用 paused（paused 现在还含 shopOpen，
    //   商店开着时 pendingUpgrade 是 null，_showUpgrade 会读 null.length 抛错、掐死 rAF）。
    if (this.core.pendingUpgrade && this.levelupEl.hidden) this._showUpgrade();
    // 阶段 6-4：魂火商栈 —— 真人游戏开门时弹商栈窗（driver 已由上面分支自动跳过）。
    if (this.core.shopOpen && this.shopEl.hidden) this._showShop();
    if (this.core.done) { this._end(); return; }
    this.raf = requestAnimationFrame((t) => this._loop(t));
  }

  /**
   * 阶段 3 音效：每帧比对 core 状态增量，触发对应合成音。
   * 所有判定都只读 core 的"计数/血量"字段，不反写任何逻辑；core 保持无头可测。
   * 高频事件（射击/命中/受伤/死亡）的内部节流在 Sfx 里，这里只管"事件是否发生"。
   */
  _syncSfx(c) {
    const s = this._sfx;
    if (c.level > s.level) { Sfx.levelUp(); s.level = c.level; }
    if (c.hits > s.hits) { Sfx.hit(); s.hits = c.hits; }
    if (c.kills > s.kills) { Sfx.death(); s.kills = c.kills; }
    if (c.chestsOpened > s.chests) { Sfx.chest(); s.chests = c.chestsOpened; this._shakeBy(ARENA.SHAKE_AMP); }
    // 技能释放总数（循环释放 + 三槽各自释放都走 skillCasts）
    const casts = c.skillCasts;
    // ★ 阶段 4-3：放技能 ⟹ 屏震（spec 一-4 三个触发点之一）。
    //   与音效同源同口径：都是"比对 core 增量"，不再另设一套事件通道。
    if (casts > s.casts) { Sfx.skill(); s.casts = casts; this._shakeBy(ARENA.SHAKE_AMP); }
    // 受伤：血量比上一帧低（且不是复活那一下填回去的）
    if (c.hp < s.hp - 0.5 && !c.pendingUpgrade) Sfx.hurt();
    s.hp = c.hp;
    // 倒下：一次性下行长音
    if (c.done && !c.survived && !s.over) { Sfx.over(); s.over = true; }
  }

  _showUpgrade() {
    this.levelupEl.hidden = false;
    this.choicesEl.innerHTML = '';
    for (let i = 0; i < this.core.pendingUpgrade.length; i++) {
      const up = this.core.pendingUpgrade[i];
      const btn = document.createElement('button');
      btn.className = 'alu-choice';
      btn.innerHTML = `<span class="alu-tag">${CAT_LABEL[up.cat] || ''}</span><span class="alu-name">${up.label}</span><span class="alu-desc">${up.desc}</span>`;
      btn.onclick = () => {
        this.core.chooseUpgrade(i);
        this.levelupEl.hidden = true;
        this._needsPaint = true; // 恢复后补一帧，避免暂停期间跳过的重绘留下旧画面
      };
      this.choicesEl.appendChild(btn);
    }
  }

  // 阶段 6-4：魂火商栈弹窗。渲染 3 件货物（买不起的置灰），点击 = resolveShop([id])。
  //   跳过按钮在 start() 里已接线（resolveShop([])）。
  _showShop() {
    this.shopEl.hidden = false;
    this.shopBalanceEl.textContent = `魂火：${Math.floor(this.core.soulfire)}`;
    this.shopChoicesEl.innerHTML = '';
    for (const g of (this.core.shopGoods || [])) {
      const afford = this.core.soulfire >= g.cost;
      const btn = document.createElement('button');
      btn.className = 'shop-choice' + (afford ? '' : ' cant');
      btn.innerHTML = `<span class="shop-name">${g.name}</span>`
        + `<span class="shop-desc">${g.desc}</span>`
        + `<span class="shop-cost">${g.cost} 魂火</span>`;
      btn.disabled = !afford;
      btn.onclick = () => {
        this.core.resolveShop([g.id]);
        this.shopEl.hidden = true;
        this._needsPaint = true; // 恢复后补一帧，避免暂停期间跳过的重绘留下旧画面
      };
      this.shopChoicesEl.appendChild(btn);
    }
  }

  // ── 精灵烘焙 ──
  _pathOf(kind) {
    let p = this._paths.get(kind);
    if (!p) {
      const t = typeOf(kind);   // 阶段 4-4：Boss 走自己的类型表（剪影种子不同 ⟹ 形象不同）
      p = new Path2D(silhouette(t.shape, t.spikes));
      this._paths.set(kind, p);
    }
    return p;
  }

  /** 白闪调色板（按 类型 × 是否精英 分开缓存 —— 精英是红的，闪白档也得从红往白插值）。 */
  _paletteOf(kind, elite) {
    const key = elite ? `${kind}:e` : kind;
    let f = this._flash.get(key);
    if (!f) {
      f = flashPalette(elite ? ARENA.ELITE_TINT : typeOf(kind).color, ARENA.DEATH_LEVELS);
      this._flash.set(key, f);
    }
    return f;
  }

  /** 剪影的真实包围盒（路径坐标）。**烘焙必须用它当范围**，不能用固定的 0~100 ——
   *  silhouette() 生成的点 y 范围是 46±66，塞进 0~100 会把上下各裁掉一截，
   *  而且裁切是**静默**的：不报错，敌人只是看起来像被削平了。 */
  _boxOf(kind) {
    let b = this._boxes.get(kind);
    if (!b) {
      const t = typeOf(kind);
      b = silhouetteBox(t.shape, t.spikes);
      this._boxes.set(kind, b);
    }
    return b;
  }

  /** 把某个类型的剪影在某个白闪档位下烘焙成离屏 canvas（只做一次）。
   *  画布尺寸按包围盒比例走，宽度基准 SPRITE_RES（>绘制尺寸，靠降采样拿平滑边缘）。 */
  _sprite(kind, flashLevel, elite = false) {
    const key = `${kind}:${flashLevel}:${elite ? 'e' : ''}`;
    let cv = this._sprites.get(key);
    if (cv) return cv;
    const b = this._boxOf(kind);
    const k = SPRITE_RES / b.w;
    cv = document.createElement('canvas');
    cv.width = SPRITE_RES;
    cv.height = Math.max(1, Math.round(b.h * k));
    const g = cv.getContext('2d');
    g.setTransform(k, 0, 0, k, -b.x * k, -b.y * k); // 平移量把包围盒左上角对到 (0,0)
    g.fillStyle = this._paletteOf(kind, elite)[flashLevel] || (elite ? ARENA.ELITE_TINT : typeOf(kind).color);
    g.fill(this._pathOf(kind));
    this._sprites.set(key, cv);
    return cv;
  }

  /** 把某类型的剪影画到 (x, y)：锚点 = 剪影参考点，视觉尺寸与碰撞半径挂钩（100 路径单位 ↔ 2r）。
   *  活体与死亡动画共用这一个入口 —— 否则两处各写一遍对齐公式，迟早各飘一次。 */
  _drawSil(ctx, kind, x, y, r, scale, flashLevel, elite = false) {
    const b = this._boxOf(kind);
    const u = (r * 2) / 100 * scale;
    ctx.drawImage(
      this._sprite(kind, flashLevel, elite),
      x - (SILHOUETTE_ANCHOR.x - b.x) * u,
      y - (SILHOUETTE_ANCHOR.y - b.y) * u,
      b.w * u, b.h * u,
    );
  }

  /** 相机平滑跟随玩家（纯渲染层状态，**绝不写回 core** —— core 保持无头可测）。
   *  指数趋近：k = 1 − e^(−dt/τ)，与帧率无关；τ = CAM_TAU。
   *  ★ 为什么要平滑而不是硬跟：硬跟时玩家的每一帧位移都会整体推给画面，
   *    满屏敌人跟着一起抖 —— 玩家会晕。相机滞后一点点，人物在屏幕上"微微领先自己的移动"，
   *    这正是横版/俯视动作游戏里"跑起来有惯性"的观感来源。
   *  ★ τ 不能大：相机滞后 = 屏幕中心偏离真身，敌人从边缘冒出的位置会不对。
   *    0.10s 是"几乎贴着人、又消掉了逐帧抖动"的量级（60fps 下每帧走 15% 的余差）。 */
  _updateCam(dt) {
    const c = this.core;
    if (!c) return;
    const p = c.player;
    if (!this._camReady) { this.cam.x = p.x; this.cam.y = p.y; this._camReady = true; return; }
    const k = 1 - Math.exp(-Math.max(dt, 0) / ARENA.CAM_TAU);
    this.cam.x += (p.x - this.cam.x) * k;
    this.cam.y += (p.y - this.cam.y) * k;
    this._updateShake(dt);
  }

  /**
   * 阶段 4-3：屏震（spec 一-4：≤6px、≤150ms）。
   * ★ 只给**相机偏移**，不缩放画面 —— 缩放式屏震会让整个世界一起抖，前庭敏感用户立刻不适。
   *   抖动用两路不同频率的正弦（纯随机每帧跳看起来是"噪点"，正弦才是"撞了一下"），
   *   幅度按剩余时长线性衰减到 0，所以单次屏震的**时长恒 ≤ SHAKE_T**。
   * ⚠ 触发点在 _syncSfx（放技能 / 开箱）与本函数末尾（同屏 > 30）。
   */
  _shakeBy(amp) {
    const a = Math.min(ARENA.SHAKE_AMP, amp);
    if (a > this._shakeAmp) this._shakeAmp = a;   // 取较大值而不是叠加：不许把幅度堆过上限
    this._shakeT = ARENA.SHAKE_T;
  }

  _updateShake(dt) {
    const s = this._shakeClock += dt;
    if (this._shakeT > 0) {
      this._shakeT = Math.max(0, this._shakeT - dt);
      const k = this._shakeT / ARENA.SHAKE_T;
      const a = this._shakeAmp * k;
      this._shakeX = Math.sin(s * 62) * a;
      this._shakeY = Math.cos(s * 47) * a * 0.8;
      if (this._shakeT <= 0) this._shakeAmp = 0;
      return;
    }
    // 同屏敌人 > 30：持续轻微震（"场面已经失控"）。
    // 幅度刻意只有 SHAKE_ENEMY_AMP（2.5px）—— 它是**背景压力**，不能盖过技能那一下的主反馈。
    if (this.core && this.core.enemies.length > ARENA.SHAKE_ENEMIES) {
      this._shakeX = Math.sin(s * 38) * ARENA.SHAKE_ENEMY_AMP;
      this._shakeY = Math.cos(s * 31) * ARENA.SHAKE_ENEMY_AMP;
      return;
    }
    this._shakeX = 0; this._shakeY = 0;
  }

  /** 阶段 4-3：把 core 里待显示的横幅（里程碑）搬到渲染层，各自独立计时淡出。 */
  _drainBanners() {
    const c = this.core;
    if (!c || !c.milestones) return;
    // ★ `life` 是**每条横幅自己的**停留时长：里程碑 2s、Boss 警告 3s（spec 一-2）。
    while (c.milestones.length) {
      const m = c.milestones.shift();
      this._banners.push({ text: m.text, evo: m.kind === 'evo', event: m.kind === 'event', t: 0, life: m.life || ARENA.MILE_FADE });
    }
  }

  /** 无限地面：随相机滚动的淡色点阵。
   *  存在的理由不是装饰 —— 无限场里如果地面是纯色，玩家移动时**画面完全没有位移参照**，
   *  走起来像"世界在后退"的错觉，方向感会崩。
   *  ★ 只画视口覆盖到的那几格（竖屏 360×640 / 96 ≈ 4×7 条线），成本可以忽略；
   *    世界坐标取整到网格倍数，所以滚动的是一条**连续**的网，不会有接缝跳变。 */
  _renderGround(ctx, w, h) {
    const g = ARENA.GROUND_GRID;
    const left = this.cam.x - w / 2, top = this.cam.y - h / 2;
    const right = left + w, bottom = top + h;
    const x0 = Math.floor(left / g) * g, y0 = Math.floor(top / g) * g;
    ctx.strokeStyle = 'rgba(232,227,218,0.045)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    for (let x = x0; x <= right; x += g) { ctx.moveTo(x, top); ctx.lineTo(x, bottom); }
    for (let y = y0; y <= bottom; y += g) { ctx.moveTo(left, y); ctx.lineTo(right, y); }
    ctx.stroke();
    // 阶段 4-7.x：地面碎片地标（按世界格哈希，确定性、随相机滚动）—— 给无限场一点"地形"，
    // 移动时画面有固定参照物，纵深感更强（点阵太规则，读不出位移）。只画 1/8 的格子，避免太密。
    const CELL = ARENA.GROUND_GRID * 3;
    const gx0 = Math.floor(left / CELL) * CELL, gy0 = Math.floor(top / CELL) * CELL;
    ctx.fillStyle = 'rgba(232,227,218,0.05)';
    for (let gx = gx0; gx <= right; gx += CELL) {
      for (let gy = gy0; gy <= bottom; gy += CELL) {
        const hsh = ((gx * 73856093) ^ (gy * 19349663)) >>> 0;
        if ((hsh & 7) !== 0) continue;            // 只画 1/8 格
        const jx = ((hsh >> 3) % 100) / 100, jy = ((hsh >> 10) % 100) / 100;
        const rx = 6 + (hsh % 9), ry = rx * 0.6;
        ctx.beginPath();
        ctx.ellipse(gx + jx * CELL, gy + jy * CELL, rx, ry, (hsh >> 5) % 6, 0, TAU);
        ctx.fill();
      }
    }
  }

  /** 阶段 4-7.x：心心（回血掉落）的形状。居中于 (x,y)，半尺寸 s。 */
  _drawHeart(ctx, x, y, s) {
    ctx.save();
    ctx.translate(x, y);
    ctx.fillStyle = COLOR.heart;
    ctx.shadowColor = 'rgba(224,88,107,0.5)';
    ctx.shadowBlur = 6;
    ctx.beginPath();
    ctx.moveTo(0, s * 0.35);
    ctx.bezierCurveTo(-s * 0.55, -s * 0.15, -s * 0.6, -s * 0.7, 0, -s * 0.3);
    ctx.bezierCurveTo(s * 0.6, -s * 0.7, s * 0.55, -s * 0.15, 0, s * 0.35);
    ctx.closePath();
    ctx.fill();
    ctx.shadowBlur = 0;
    ctx.fillStyle = 'rgba(255,255,255,0.5)';   // 高光点
    ctx.beginPath();
    ctx.arc(-s * 0.22, -s * 0.32, s * 0.12, 0, TAU);
    ctx.fill();
    ctx.restore();
  }

  // ── 阶段 6-1：帧耗时剖析（只在 ?dbg=1 下启用）──────────────────────────────────
  // 为什么必须先剖析再优化：34.2fps 是**整帧**的读数，它不告诉你是哪一段在烧时间。
  //   逐类别打点才能区分"是 220 次 drawImage" / "是 fillText 飘字" / "是逻辑层 step"。
  // ★ 打点用**边界戳**而不是包函数：只在每个绘制块的边界插一行 _pdone，
  //   对已有绘制代码零改动（包函数会把 730 行的 _render 整体重排，风险不可控）。
  _pmark() { if (this.prof) this._pT0 = performance.now(); }
  _pdone(k) {
    if (!this.prof) return;
    const t = performance.now();
    const b = this.prof[k] || (this.prof[k] = { ms: 0, n: 0 });
    b.ms += t - this._pT0; b.n++;
    this._pT0 = t;
  }
  /** 归一化成「每帧毫秒 / 占整帧 %」，按耗时降序。给调试面板与探针读。 */
  _profTop() {
    if (!this.prof) return [];
    const frames = Math.max(1, this.prof.ui?.n || 1);
    const all = Object.entries(this.prof).map(([k, v]) => [k, v.ms / frames]);
    const sum = all.reduce((a, [, ms]) => a + ms, 0) || 1;
    return all.sort((a, b) => b[1] - a[1]).map(([k, ms]) => ({ k, ms, pc: (ms / sum) * 100 }));
  }

  _render() {
    this._pmark();
    const ctx = this.ctx;

    const c = this.core;
    const w = c.w, h = c.h;
    // 每帧显式重置基准变换：下面的世界层用了 save/translate/restore，万一某一帧提前返回
    // 或 restore 配错，变换会**静默累积**（画面越跑越偏，且完全不报错）。从 dpr 重新开始最安全。
    ctx.setTransform(this._dpr, 0, 0, this._dpr, 0, 0);

    // 底色：铺满视口，属屏幕层（不参与相机）。
    // ★ 阶段 4-1 去掉了旧的"暗场边框"—— 场地不再有边，画一个框等于朝玩家撒谎。
    ctx.fillStyle = COLOR.field;
    ctx.fillRect(0, 0, w, h);
    this._pdone('clear');

    // ══════════ 世界层 ══════════ 从这里到 ctx.restore() 之间一律按**世界坐标**绘制。
    // 相机把玩家对到屏幕中心：屏幕 = 世界 − cam + 视口中心。
    // ★ 偏移只在这一个地方做。任何一处漏减相机，那个东西就会"跟着世界漂"（一移动就露馅）。
    ctx.save();
    // ★ 阶段 4-3：屏震 = 相机偏移。它只作用在世界层 —— HUD 不跟着抖
    //  （数字跟着抖就没法读了，而"我还有多少血"恰恰是最不能读错的那个数）。
    ctx.translate(w / 2 - this.cam.x + this._shakeX, h / 2 - this.cam.y + this._shakeY);
    this._renderGround(ctx, w, h);
    this._pdone('ground');

    // 经验宝石（合批：一次 fill 画完所有宝石，而不是 N 次 beginPath+arc+fill。
    // 实测宝石是单项最贵的绘制之一，合批后 subpath 共用一次光栅化）
    if (c.gems.length) {
      ctx.fillStyle = COLOR.gem;
      ctx.strokeStyle = 'rgba(214,255,250,0.55)';   // 阶段 4-7.x：宝石描边高光（更像宝石、有微光）
      ctx.lineWidth = 1;
      ctx.beginPath();
      const magR = c.magnet;   // 阶段 4-3：弹出偏移的**收回**判据（见 killEnemy 的注释）
      for (const g of c.gems) {
        // ★ 阶段 4-3：弹出的视觉偏移。k 由两段合成：
        //   ① pop 进度（0→1，GEM_POP_T 内 ease-out 走完）—— "从尸体上蹦出来"；
        //   ② 离玩家的远近（越近越收回）—— 被吸到身上的那一刻偏移正好归 0，
        //      于是宝石是"落进玩家身上"而不是"在旁边 100px 处凭空消失"。
        let vx = g.x, vy = g.y;
        if (g.ox || g.oy) {
          const d = Math.sqrt((g.x - c.player.x) ** 2 + (g.y - c.player.y) ** 2);
          const k = easeOut(clamp(g.pop / ARENA.GEM_POP_T, 0, 1)) * clamp(1 - d / magR, 0, 1);
          vx += g.ox * k; vy += g.oy * k;
        }
        ctx.moveTo(vx, vy - g.r);   // 阶段 4-7.x：菱形（旋转 45° 的方）取代圆 —— 更像"宝石"
        ctx.lineTo(vx + g.r, vy);
        ctx.lineTo(vx, vy + g.r);
        ctx.lineTo(vx - g.r, vy);
        ctx.closePath();
      }
      ctx.fill();
      ctx.stroke();
    }

    this._pdone('gems');
    // 心心（阶段 4-7.x：击杀掉落，回血）。菱形心形 + 轻微跳动，粉红。
    if (c.hearts.length) {
      const pulse = 1 + 0.09 * Math.sin(c.time / 170);
      for (const h of c.hearts) {
        const k = h.pop < 1 ? easeOut(h.pop) : 1;
        const s = h.r * (0.55 + 0.45 * k) * pulse;
        this._drawHeart(ctx, h.x, h.y, s);
      }
    }

    this._pdone('hearts');
    // 宝箱（spec §5）：金色小箱，走近自动开。
    // 阶段 4-4：Boss 掉的**大金箱**更大一号 + 外面套一圈呼吸光环（"这箱不一样"）。
    for (const ch of c.chests) {
      const s = ch.r * (ch.gold ? 1.5 : 1);
      if (ch.gold) {
        const pulse = 0.5 + 0.5 * Math.sin(ch.t * 5);
        ctx.strokeStyle = `rgba(240,199,94,${0.35 + 0.4 * pulse})`;
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.arc(ch.x, ch.y, s + 12 + 5 * pulse, 0, TAU);
        ctx.stroke();
      }
      ctx.fillStyle = ch.gold ? '#f0c75e' : COLOR.gold;
      ctx.fillRect(ch.x - s, ch.y - s * 0.72, s * 2, s * 1.44);
      ctx.fillStyle = 'rgba(13,12,11,0.55)';       // 箱盖缝
      ctx.fillRect(ch.x - s, ch.y - s * 0.10, s * 2, s * 0.20);
      ctx.strokeStyle = COLOR.paper;
      ctx.lineWidth = 1.5;
      ctx.strokeRect(ch.x - s, ch.y - s * 0.72, s * 2, s * 1.44);
    }

    this._pdone('chests');
    // 敌人（阶段 3：优先画 PNG 精灵；没加载好/加载失败回退剪影）
    // ★ 阶段 4-1 加了视口剔除：同屏上限提到 220，而其中一大截是 750~1000px 外的**在途**怪，
    //   它们根本不在画面里 —— 每帧对它们调一次 drawImage（或画一条路径）是纯浪费。
    //   边距取 80：给死亡爆裂的外扩、以及"精灵比碰撞圈大一圈"留余量。
    const vx0 = this.cam.x - w / 2 - 80, vx1 = this.cam.x + w / 2 + 80;
    const vy0 = this.cam.y - h / 2 - 80, vy1 = this.cam.y + h / 2 + 80;
    for (const e of c.enemies) {
      if (e.x < vx0 || e.x > vx1 || e.y < vy0 || e.y > vy1) continue;
      // 阶段 4-7.x：出生淡入（纯视觉）。ap<1 时整体缩放+淡出，从 0 长成满尺寸。
      const ap = e.appear != null ? e.appear : 1;
      const wrap = ap < 1;
      if (wrap) {
        ctx.save();
        ctx.globalAlpha = ap;
        ctx.translate(e.x, e.y); ctx.scale(ap, ap); ctx.translate(-e.x, -e.y);
      }
      const sz = this._drawEntity(ctx, e.kind, e.x, e.y, e.r, 1, false, e.elite);
      if (!sz) this._drawSil(ctx, e.kind, e.x, e.y, e.r, 1, 0, e.elite);
      // 阶段 4-3：命中闪白（spec 一-5「更明显一档」）。
      // 真图：叠一层烘焙好的白蒙版（alpha ∝ 剩余时间）；剪影：直接换成高档闪白。
      // ★ 满屏两百只时"打中了"这件事唯一贴着敌人的读数就是这一下，所以它必须够亮。
      if (e.hitT > 0) {
        const k = clamp(e.hitT / ARENA.HIT_FLASH, 0, 1);
        if (sz && this._whiteMask[e.kind]) {
          ctx.save();
          ctx.globalAlpha = k * 0.8;
          ctx.drawImage(this._whiteMask[e.kind], e.x - sz.dw / 2, e.y - sz.dh / 2, sz.dw, sz.dh);
          ctx.restore();
        } else {
          this._drawSil(ctx, e.kind, e.x, e.y, e.r, 1, Math.round(k * (ARENA.DEATH_LEVELS - 1)), e.elite);
        }
      }
      if (wrap) ctx.restore();
      // 阶段 4-11：精英 / 远程精英**脉冲光环** —— 一眼识别"优先目标"（纯视觉，不碰判定）。
      // 近战精英红、远程精英橙；出生淡入中(ap<1)不画，避免从 0 突然冒出光环。
      if ((e.elite || e.kind === 'ranged') && ap >= 1) {
        const col = e.elite ? ARENA.ELITE_TINT : ARENA.RANGED_RING;
        const pl = 0.5 + 0.5 * Math.sin(c.time / 220);
        ctx.save();
        ctx.globalAlpha = 0.30 + 0.38 * pl;
        ctx.strokeStyle = col;
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.arc(e.x, e.y, e.r + 5 + 3 * pl, 0, TAU);
        ctx.stroke();
        ctx.restore();
      }
      // 阶段 4-11：接触威胁高亮 —— 怪逼近到即将咬玩家的距离时描一圈红脉冲，
      // 给玩家"谁在威胁我"的读数（纯视觉；判据与接触伤害触发距离 player.r+e.r 对齐 + 余量）。
      {
        const dxp = e.x - c.player.x, dyp = e.y - c.player.y;
        const dp = Math.hypot(dxp, dyp);
        const warn = c.player.r + e.r + ARENA.TOUCH_WARN;
        if (dp < warn) {
          const urg = clamp(1 - dp / warn, 0, 1);     // 越近越红越粗
          const pl = 0.5 + 0.5 * Math.sin(c.time / 90);
          ctx.save();
          ctx.globalAlpha = 0.35 + 0.5 * urg;
          ctx.strokeStyle = `rgba(224,60,55,${0.6 + 0.4 * urg})`;
          ctx.lineWidth = 2 + 2 * urg;
          ctx.beginPath();
          ctx.arc(e.x, e.y, e.r + 3 + 2 * pl, 0, TAU);
          ctx.stroke();
          ctx.restore();
        }
      }
    }
    this._pdone('enemies');
    // 阶段 4-8 三：护盾怪的**壳**（spec 原文「护盾怪外圈画个壳」）。
    // 阶段 4-7 只画了一条 3px 细圈 —— 满屏两百只时它和"冻结标记 / 精英描边 / 命中闪白"
    // 混在一起，玩家读不出"这只打不动"。改成两层可读的壳：
    //   ① 半透明**厚环** = "壳"的实体感（有厚度，不是一条线），层数越少越淡；
    //   ② **分段亮弧**：剩几层盾就画几段 —— 层数变成**可数的**，而不是只能靠亮度猜。
    // 性能：只有带盾的怪进这个循环（护盾权重 3~5 / 总权重约 100 ⟹ 同屏十来只），
    //   每只 1 + 层数(≤3) 次 stroke，相对每只一次的 drawImage 可以忽略。
    for (const e of c.enemies) {
      if (!(e.shield > 0)) continue;
      const R = e.r + 6;
      const k = e.shield / ARENA.SHIELD_HITS;         // 1 = 满盾
      ctx.save();
      ctx.strokeStyle = `rgba(63,208,200,${0.34 + 0.30 * k})`;   // ① 壳身
      ctx.lineWidth = 6;
      ctx.beginPath();
      ctx.arc(e.x, e.y, R - 1, 0, TAU);
      ctx.stroke();
      ctx.strokeStyle = 'rgba(214,255,250,0.95)';                // ② 层数刻度
      ctx.lineWidth = 3;
      const step = TAU / ARENA.SHIELD_HITS, seg = step * 0.62;
      for (let i = 0; i < e.shield; i++) {
        const a0 = -Math.PI / 2 + step * i;
        ctx.beginPath();
        ctx.arc(e.x, e.y, R + 2, a0, a0 + seg);
        ctx.stroke();
      }
      ctx.restore();
    }
    this._pdone('shield');
    // 冻结标记：淡蓝圈画在剪影之上 —— 一眼能看出"这只不动了"
    if (c.skills.frost) {
      let any = false;
      ctx.beginPath();
      for (const e of c.enemies) {
        if (!(e.frozen > 0)) continue;
        ctx.moveTo(e.x + e.r + 4, e.y);
        ctx.arc(e.x, e.y, e.r + 4, 0, TAU);
        any = true;
      }
      if (any) { ctx.strokeStyle = 'rgba(91,147,214,0.75)'; ctx.lineWidth = 2; ctx.stroke(); }
    }

    this._pdone('frost');
    // ── 阶段 4-4：Boss 冲锋的**方向提示**（0.5s 前摇期间画出）──
    // ★ 为什么必须画：spec 二-2 说"有 0.5 秒前摇停顿 + 方向提示"。少了这条线，
    //   那 0.5 秒在满屏怪里就是"它卡住了"，玩家读不到"要冲了、往哪冲" ——
    //   前摇的意义（可规避）也就没了。用金色而不是怪自己的颜色：它是**警告**，不是这只怪的配色。
    for (const e of c.enemies) {
      if (!isBossKind(e.kind) || e.phase !== 'windup') continue;
      const len = 240;
      const tx = e.x + e.aimX * len, ty = e.y + e.aimY * len;
      ctx.save();
      ctx.strokeStyle = 'rgba(240,199,94,0.70)';
      ctx.lineWidth = 6;
      ctx.setLineDash([14, 10]);
      ctx.beginPath();
      ctx.moveTo(e.x, e.y);
      ctx.lineTo(tx, ty);
      ctx.stroke();
      ctx.restore();
      ctx.strokeStyle = 'rgba(240,199,94,0.95)';
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.arc(tx, ty, e.r * 1.15, 0, TAU);
      ctx.stroke();
    }

    this._pdone('bossAim');
    // 敌人死亡动画：0.15s 爆裂缩小 + 闪白，不再瞬切
    for (const d of c.deaths) {
      const p = clamp(d.t / d.life, 0, 1);
      // 两段式：0~30% 放大到 1+DEATH_POP（"炸开"），30%~100% 收到 0（"碎掉"）。
      // 单段纯缩小看起来像漏气，不像被打碎 —— 这就是 squash & stretch 在死亡上的用法。
      const at = ARENA.DEATH_POP_AT;
      const k = p < at
        ? lerp(1, 1 + ARENA.DEATH_POP, easeOut(p / at))
        : lerp(1 + ARENA.DEATH_POP, 0, easeOut((p - at) / (1 - at)));
      if (k < 0.02) continue; // 缩到看不见就别画了（scale≈0 的图只是白烧光栅化）
      const eo = easeOut(p);                       // 外飞位移同样走 ease-out：先窜出去再停住
      const x = d.x + d.dx * eo, y = d.y + d.dy * eo;
      // 白闪：前 DEATH_FLASH_AT 保持全白，之后退回本色（档数由 DEATH_LEVELS 决定，预生成）
      const flash = p < ARENA.DEATH_FLASH_AT ? 1 : 1 - (p - ARENA.DEATH_FLASH_AT) / (1 - ARENA.DEATH_FLASH_AT);
      const lv = Math.round(clamp(flash, 0, 1) * (ARENA.DEATH_LEVELS - 1));
      // 阶段 3：优先画真图；白闪通过"在真图之上叠一层烘焙好的白色蒙版"实现
      // （globalAlpha 决定染白程度，0 = 全本色 / 满 = 全白）。图没就绪则回退剪影（自带闪白档）。
      const sz = this._drawEntity(ctx, d.kind, x, y, d.r, k, false, d.elite);
      if (sz && lv > 0) {
        ctx.save();
        ctx.globalAlpha = (lv / (ARENA.DEATH_LEVELS - 1)) * 0.85;
        if (this._whiteMask[d.kind]) ctx.drawImage(this._whiteMask[d.kind], x - sz.dw / 2, y - sz.dh / 2, sz.dw, sz.dh);
        else ctx.globalAlpha = 0; // 蒙版缺失（理论上不会，onload 内必烘焙）时静默跳过
        ctx.restore();
      }
      if (!sz) this._drawSil(ctx, d.kind, x, y, d.r, k, lv, d.elite);
    }

    this._pdone('deaths');
    // 环绕刃（spec §7）：剑 + 旋转残影。
    // 残影不需要历史缓冲 —— 它就是"同一个形状在过去几个角度上的淡影"，
    // 角度是可以由当前角度直接算出来的，所以零额外内存。
    if (c.weapons.orbit) {
      const o = c.orbit;
      const bx = c.player.x, by = c.player.y;
      ctx.lineCap = 'round';
      for (let g = ARENA.ORBIT_GHOST_LEVELS; g >= 0; g--) {
        const back = ARENA.ORBIT_GHOST * g;
        ctx.strokeStyle = `rgba(209,84,74,${g === 0 ? 0.95 : 0.22 / g})`;
        ctx.lineWidth = g === 0 ? 4 : 3;
        ctx.beginPath();
        for (let i = 0; i < o.count; i++) {
          const a = o.ang - back + (i / o.count) * TAU;
          const ca = Math.cos(a), sa = Math.sin(a);
          ctx.moveTo(bx + ca * o.r * 0.70, by + sa * o.r * 0.70);
          ctx.lineTo(bx + ca * o.r, by + sa * o.r);
        }
        ctx.stroke();
      }
      ctx.lineCap = 'butt';
    }

    this._pdone('orbit');
    // 投射物拖尾：一个孤立的点在满屏敌人里几乎读不出弹道。
    // 投射物是直线飞行，所以"残影"就是它身后的一小段线段，**不需要历史位置缓冲**：
    // 既省掉每帧每弹的 push/shift，也没有额外分配。两层描边（宽而淡 + 细而亮）
    // 共用同一个 path，多 2 次 draw call 就做出了渐隐感。
    if (c.projectiles.length) {
      const back = ARENA.PROJECTILE_TRAIL / ARENA.PROJECTILE_SPEED;
      ctx.lineCap = 'round';
      ctx.beginPath();
      for (const p of c.projectiles) {
        if (p.sword) continue;   // 阶段 5：剑气画下面的"月牙斩光"，不走这条通用拖尾
        ctx.moveTo(p.x - p.vx * back, p.y - p.vy * back);
        ctx.lineTo(p.x, p.y);
      }
      ctx.strokeStyle = 'rgba(232,227,218,0.16)';
      ctx.lineWidth = 5;
      ctx.stroke();
      ctx.strokeStyle = 'rgba(232,227,218,0.42)';
      ctx.lineWidth = 1.6;
      ctx.stroke();
      ctx.lineCap = 'butt'; // 复位：后面还有开弧描边（冲击波环），圆头会多出一个小圆点

      // 弹头（合批：一次 fill 画完所有弹头）
      ctx.fillStyle = COLOR.projectile;
      ctx.beginPath();
      for (const p of c.projectiles) {
        if (p.sword) continue;   // 阶段 5：同上，剑气没有"弹头"这个小圆点
        ctx.moveTo(p.x + p.r, p.y);
        ctx.arc(p.x, p.y, p.r, 0, TAU);
      }
      ctx.fill();
    }

    this._pdone('proj');
    // ── 阶段 5：剑气 = **弧形斩光**（一眼区别于另外两种直线的东西）──
    //   投射物是"点 + 一段拖尾"，直斩是"整条持续光束"，剑气必须是第三种读法：
    //   一段**月牙**（跨约 ±66° 的圆弧），弓身朝飞行方向鼓出去 —— "唰"一下挥出去的那一下。
    //   两层同心弧共用一个 path（宽而淡 + 细而亮的刃锋），和上面拖尾那两层的做法一致。
    if (c.projectiles.length) {
      for (const p of c.projectiles) {
        if (!p.sword) continue;
        const fade = clamp(p.life / ARENA.SWORD_LIFE, 0, 1);
        drawSwordQi(ctx, p.x, p.y, p.ang, p.r, fade);
      }
    }
    // C3 环绕：同一套月牙，恒亮（它是常驻的，没有"寿命淡出"这回事）。
    if (c.swordBlades.length) {
      for (const b of c.swordBlades) drawSwordQi(ctx, b.x, b.y, b.ang, b.r, 1);
      // 底下一圈极淡的引导环：不给的话，12 把独立月牙在乱战里读作"一堆碎屑"而不是"一个域"。
      ctx.beginPath();
      ctx.arc(c.player.x, c.player.y, ARENA.SWORD_C3_R, 0, TAU);
      ctx.strokeStyle = 'rgba(232,227,218,0.06)';
      ctx.lineWidth = 1;
      ctx.stroke();
    }

    this._pdone('swordQi');
    // 敌方子弹（阶段 4-1 远程精英）：短光痕 + 弹头，**紫色**。
    // ★ 配色是功能性的：玩家的弹道是暖白、宝石是浅紫，敌方子弹必须是另一种紫，
    //   在两百只怪的场面里"哪条线是朝我来的"要能零思考地读出来。
    //   与投射物同一套做法（直线飞行 ⟹ 残影就是身后一小段线段，不需要位置缓冲）。
    if (c.bullets.length) {
      const back = 14 / ARENA.BULLET_SPEED;   // 14px 的拖尾长度
      ctx.lineCap = 'round';
      ctx.beginPath();
      for (const b of c.bullets) {
        ctx.moveTo(b.x - b.vx * back, b.y - b.vy * back);
        ctx.lineTo(b.x, b.y);
      }
      ctx.strokeStyle = 'rgba(168,154,230,0.40)';
      ctx.lineWidth = 4.5;
      ctx.stroke();
      ctx.lineCap = 'butt';

      ctx.fillStyle = '#cfc0ff';
      ctx.beginPath();
      for (const b of c.bullets) {
        ctx.moveTo(b.x + b.r, b.y);
        ctx.arc(b.x, b.y, b.r, 0, TAU);
      }
      ctx.fill();
    }

    this._pdone('bullets');
    // 粒子
    for (const pa of c.particles) {
      ctx.globalAlpha = Math.max(0, pa.life * 3.3);
      ctx.fillStyle = pa.color;
      ctx.beginPath();
      ctx.arc(pa.x, pa.y, pa.r, 0, TAU);
      ctx.fill();
    }
    ctx.globalAlpha = 1;

    this._pdone('particles');
    // 玩家 —— 阶段 3：优先画 hero.png（居中 + 倾斜/挤压作用在图片上，手感不变）；
    // 图片没就绪则回退剪影（_playerPath）。
    // ① 惯性：速度由 ArenaCore 插值（vx/vy），这里只读它换算表现量；
    // ② 侧倾：按横向速度倾斜；
    // ③ squash & stretch：沿**运动方向**拉伸、垂直方向压扁。必须先转到运动坐标系再缩放：
    //    直接在屏幕轴上缩放的话，斜向移动会得到"沿屏幕轴拉长"，看起来像被压扁的球。
    // 幅度全部走 ARENA 常量（小、不夸张），位移/旋转都以 p 为唯一真源，不写回状态。
    const p = c.player, pr = p.r;
    const maxSpd = c.moveSpeed || ARENA.BASE_MOVE;
    const spdK = clamp(Math.sqrt(p.vx * p.vx + p.vy * p.vy) / maxSpd, 0, 1);
    const lean = clamp(p.vx / maxSpd, -1, 1) * ARENA.PLAYER_LEAN;
    // 同一套变换，两种画法共用 —— 否则回退剪影和真图的倾斜会各飘一次。
    const withPlayerTransform = (fn) => {
      ctx.save();
      ctx.translate(p.x, p.y);            // 支点 = 碰撞中心（图片居中绘制）
      ctx.rotate(lean);
      if (spdK > 0.01) {
        const a = Math.atan2(p.vy, p.vx);
        ctx.rotate(a);
        ctx.scale(1 + ARENA.PLAYER_STRETCH * spdK, 1 - ARENA.PLAYER_SQUASH * spdK);
        ctx.rotate(-a);
      }
      fn();
      ctx.restore();
    };
    let sz = null;
    withPlayerTransform(() => {
      sz = this._drawEntity(ctx, 'hero', 0, 0, pr);
      // 阶段 6-2：皮肤蒙版叠在英雄真图之上（半透明，保留素材层次；默认皮肤不叠）。
      if (sz && this.skin !== DEFAULT_SKIN && this._skinMasks[this.skin]) {
        const { dw, dh } = this._entitySize('hero', pr);
        ctx.globalAlpha = SKIN_TINT_ALPHA;
        ctx.drawImage(this._skinMasks[this.skin], -dw / 2, -dh / 2, dw, dh);
        ctx.globalAlpha = 1;
      }
    });
    if (!sz) withPlayerTransform(() => this._playerPath(ctx, pr));

    this._pdone('player');
    // ── 阶段 4-14：增益激活期光环 ──
    // 为什么需要：黄金时段/磁暴都是**限时 buff**，横幅淡出后玩家完全读不出"增益还在不在"
    //   （典型困惑："宝石为什么在飞？"、"刚才那个 ×2 还有吗？"）。
    // 按颜色区分两个 buff：磁暴 = 青色虚线大圈（半径取**当前生效拾取半径**，直接读出"能吸多远"，
    //   再叠一层缓慢自转表达"场在工作"）；黄金时段 = 贴身金色呼吸环。
    // ★ reducedMotion 下**保留静态环**而不是整块跳过：这批是**信息**（增益是否生效），
    //   可读性优先于动效，只是把呼吸/自转的振幅压成定值。
    const bPulse = this.reduced ? 0.5 : 0.5 + 0.5 * Math.sin(c.time / 190);
    // 余量联动：环随 buff 剩余时间收束（快到期时变淡），玩家能预判"增益快没了"而不是凭空消失。
    const magRem = c.magnetUntil > 0 ? clamp((c.magnetUntil - c.elapsed) / ARENA.MAGNET_T, 0, 1) : 1;
    const goldRem = c.goldUntil > 0 ? clamp((c.goldUntil - c.elapsed) / ARENA.GOLD_T, 0, 1) : 1;
    if (c.magnetMul > 1) {
      const rMag = (pr + 6) * c.magnetMul;   // ≈ 生效中的 gem 拾取半径
      ctx.save();
      ctx.translate(p.x, p.y);
      if (!this.reduced) ctx.rotate((c.time / 900) % TAU);
      ctx.setLineDash([10, 8]);
      ctx.strokeStyle = `rgba(95,208,200,${(0.30 + 0.30 * bPulse) * (0.35 + 0.65 * magRem)})`;
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(0, 0, rMag, 0, TAU);
      ctx.stroke();
      ctx.setLineDash([]);
      ctx.restore();
    }
    if (c.goldMul > 1) {
      ctx.strokeStyle = `rgba(232,196,90,${(0.35 + 0.35 * bPulse) * (0.35 + 0.65 * goldRem)})`;
      ctx.lineWidth = 2 + 1.5 * bPulse;
      ctx.beginPath();
      ctx.arc(p.x, p.y, (pr + 14) * (1 + 0.04 * bPulse), 0, TAU);
      ctx.stroke();
    }

    this._pdone('buffs');
    // 飘伤害数字：小字、快出快隐、ease-out 上飘。
    // 阶段 4-3：大数字（≥FLOAT_BIG_DMG）换成 18px 粗体 + 金色（spec 一-1）。
    if (c.floaters.length) {
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      for (const f of c.floaters) {
        const font = f.big ? FONT_FLOAT_BIG : FONT_SMALL;
        if (this._f2 !== font) { this._f2 = font; ctx.font = font; }
        ctx.globalAlpha = clamp(1 - f.t / f.max, 0, 1);
        ctx.fillStyle = f.color;
        ctx.fillText(f.text, f.x, f.y);
      }
      ctx.globalAlpha = 1;
    }

    this._pdone('floaters');
    // 冲击波视觉：蓄力 → 爆发两拍
    const px = c.player.x, py = c.player.y;
    // ── 蓄力圈：由外向内收拢、逐渐变亮、线越来越粗 ──
    // 这一拍的意义不只是好看：0.15s 的蓄力如果画面没变化，玩家读到的只是"卡了一下"。
    // 收拢方向刻意与爆发环**相反**（内收 vs 外扩），一眼就能分清"准备"和"炸了"。
    if (c.shockChargeT >= 0) {
      const cp = clamp(c.shockChargeT / ARENA.SHOCKWAVE_CHARGE, 0, 1);
      const eo = easeOut(cp);
      const r = ARENA.SHOCKWAVE_RADIUS * (1 - 0.78 * eo);
      ctx.fillStyle = `rgba(168,154,230,${0.06 + 0.16 * eo})`;
      ctx.beginPath();
      ctx.arc(px, py, r * 0.5, 0, TAU);
      ctx.fill();
      ctx.strokeStyle = `rgba(168,154,230,${0.35 + 0.55 * eo})`;
      ctx.lineWidth = 2 + 4 * eo;
      ctx.beginPath();
      ctx.arc(px, py, r, 0, TAU);
      ctx.stroke();
    }
    // ── 爆发环：三层错相波纹向外扩散（单环看起来只是"画了个圈"，多层才有"冲出去"的动感） ──
    if (c.shockwaveCastT >= 0) {
      const prog = clamp(c.shockwaveCastT / ARENA.SHOCKWAVE_FX, 0, 1);
      for (let i = 0; i < 3; i++) {
        const q = clamp(prog * 1.35 - i * 0.18, 0, 1);
        if (q <= 0) continue;
        ctx.strokeStyle = `rgba(168,154,230,${Math.max(0, (1 - q) * (i === 0 ? 0.95 : 0.45))})`;
        ctx.lineWidth = i === 0 ? 5 : 2.5;
        ctx.beginPath();
        // 半径走 ease-out（先窜出去、再减速）：线性扩张看起来像匀速推开的圈，不像"炸"。
        ctx.arc(px, py, easeOut(q) * ARENA.SHOCKWAVE_RADIUS, 0, TAU);
        ctx.stroke();
      }
    }

    this._pdone('shock');
    // ── 阶段 2 特效（spec §7）：直斩光束 / 霜环 / 闪现残影 / 开箱金光。
    //    全部走 ease-out、全部 ≤ ANIM_MAX，与阶段 1 的动画共用同一条口径。
    for (const f of c.fx) {
      const pr = clamp(f.t / f.life, 0, 1);
      const eo = easeOut(pr);
      const fade = 1 - pr;
      if (f.kind === 'beam') {
        ctx.save();
        ctx.translate(f.x, f.y);
        ctx.rotate(f.ang);
        // 两层：宽而淡的外晕 + 细而亮的内芯（比单根线更像"一道光"）
        ctx.strokeStyle = `rgba(232,227,218,${0.16 * fade})`;
        ctx.lineWidth = f.w * (1 + 0.6 * fade);
        ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(f.len, 0); ctx.stroke();
        ctx.strokeStyle = `rgba(232,227,218,${0.9 * fade})`;
        ctx.lineWidth = Math.max(1, f.w * 0.5 * fade);
        ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(f.len, 0); ctx.stroke();
        ctx.restore();
      } else if (f.kind === 'frost') {
        ctx.strokeStyle = `rgba(91,147,214,${fade * 0.8})`;
        ctx.lineWidth = 4 - 2 * eo;
        ctx.beginPath();
        ctx.arc(f.x, f.y, f.r * (0.35 + 0.65 * eo), 0, TAU);
        ctx.stroke();
        ctx.fillStyle = `rgba(91,147,214,${fade * 0.10})`;
        ctx.beginPath(); ctx.arc(f.x, f.y, f.r, 0, TAU); ctx.fill();
      } else if (f.kind === 'dash') {
        // 残影 = 路径上 3 个渐淡的自己（ease-out 分布：起步密、末尾稀）。阶段 3：优先画 hero.png。
        for (let i = 0; i < 3; i++) {
          const q = easeOut((i + 1) / 4);
          ctx.globalAlpha = fade * (0.44 - 0.13 * i);
          const gx = f.x0 + (f.x1 - f.x0) * q, gy = f.y0 + (f.y1 - f.y0) * q;
          const sz = this._drawEntity(ctx, 'hero', gx, gy, f.r);
          if (sz && this.skin !== DEFAULT_SKIN && this._skinMasks[this.skin]) {
            const { dw, dh } = this._entitySize('hero', f.r);
            ctx.drawImage(this._skinMasks[this.skin], gx - dw / 2, gy - dh / 2, dw, dh);
          }
          if (!sz) { ctx.save(); ctx.translate(gx, gy); ctx.fillStyle = COLOR.player; this._playerPath(ctx, f.r); ctx.restore(); }
        }
        ctx.globalAlpha = 1;
      } else if (f.kind === 'chest') {
        ctx.strokeStyle = `rgba(214,171,88,${fade})`;
        ctx.lineWidth = 3;
        ctx.beginPath(); ctx.arc(f.x, f.y, f.r + 44 * eo, 0, TAU); ctx.stroke();
      }
    }

    this._pdone('fx');
    // ══════════ 屏幕层 ══════════ 世界层到此结束
    ctx.restore();

    // 白闪：一帧级的全屏提亮。用「时长」而不是真·一帧 —— 掉帧时真一帧会整帧看不见。
    // reducedMotion 下跳过（前庭敏感用户保护，与粒子同一条策略）。
    // 注意它在 restore **之后**：白闪铺的是视口而不是世界，放进世界层会跟着相机漂。
    if (!this.reduced && c.flashT >= 0) {
      const k = clamp(c.flashT / ARENA.SHOCKWAVE_FLASH, 0, 1);
      ctx.fillStyle = `rgba(232,227,218,${0.38 * k})`;
      ctx.fillRect(0, 0, w, h);
    }

    // ── 阶段 4-7.x：暗角（径向渐变，屏幕四角压暗）—— 聚焦中心 + 增加纵深感。纯屏幕层。
    if (!this.reduced) {
      const vg = ctx.createRadialGradient(w / 2, h / 2, Math.min(w, h) * 0.30, w / 2, h / 2, Math.max(w, h) * 0.72);
      vg.addColorStop(0, 'rgba(0,0,0,0)');
      vg.addColorStop(1, 'rgba(0,0,0,0.42)');
      ctx.fillStyle = vg;
      ctx.fillRect(0, 0, w, h);
    }

    // ── 阶段 4-10：受击红屏脉冲（玩家吃伤害时屏幕边缘泛红，快速衰减）── 纯屏幕层。
    if (!this.reduced && c.hurtT >= 0) {
      const k = clamp(c.hurtT / ARENA.HURT_FLASH, 0, 1);
      const rg = ctx.createRadialGradient(w / 2, h / 2, Math.min(w, h) * 0.32, w / 2, h / 2, Math.max(w, h) * 0.78);
      rg.addColorStop(0, 'rgba(224,40,40,0)');
      rg.addColorStop(0.65, `rgba(224,40,40,${0.12 * k})`);
      rg.addColorStop(1, `rgba(224,40,40,${0.52 * k})`);
      ctx.fillStyle = rg;
      ctx.fillRect(0, 0, w, h);
    }

    // ── 阶段 4-11：升级全屏暖光扩散 —— 等级提升那一刻从屏幕中心荡开一圈暖色光环（纯视觉）。
    if (!this.reduced && c.levelFlashT >= 0) {
      const k = clamp(c.levelFlashT / ARENA.LEVEL_FLASH_T, 0, 1);   // 1 → 0（随时间收束）
      const rad = Math.max(w, h) * 0.72 * (1 - k);                  // 从中心向外扩散
      ctx.save();
      ctx.globalAlpha = 0.5 * k;
      ctx.strokeStyle = 'rgba(240,199,94,0.9)';                     // 暖金（与升级横幅/音效同色系）
      ctx.lineWidth = 8 * k + 2;
      ctx.beginPath();
      ctx.arc(w / 2, h / 2, rad, 0, TAU);
      ctx.stroke();
      // 中心微亮：强化"成长"瞬间
      const cg = ctx.createRadialGradient(w / 2, h / 2, 0, w / 2, h / 2, Math.max(w, h) * 0.30 * (1 - k) + 1);
      cg.addColorStop(0, `rgba(240,199,94,${0.10 * k})`);
      cg.addColorStop(1, 'rgba(240,199,94,0)');
      ctx.fillStyle = cg;
      ctx.fillRect(0, 0, w, h);
      ctx.restore();
    }

    // ── 阶段 4-11：Boss 出场红场脉冲 —— 强大敌人降临那一刻全屏径向泛红（纯视觉，独立于受击脉冲）。
    if (!this.reduced && c.bossFlashT >= 0) {
      const k = clamp(c.bossFlashT / ARENA.BOSS_ENTER_FLASH_T, 0, 1);
      const rg = ctx.createRadialGradient(w / 2, h / 2, Math.min(w, h) * 0.18, w / 2, h / 2, Math.max(w, h) * 0.82);
      rg.addColorStop(0, `rgba(150,18,18,${0.10 * k})`);
      rg.addColorStop(0.7, `rgba(196,28,28,${0.24 * k})`);
      rg.addColorStop(1, `rgba(224,40,40,${0.58 * k})`);
      ctx.fillStyle = rg;
      ctx.fillRect(0, 0, w, h);
    }

    this._pdone('screen');
    // ── HUD：倒计时 + 波次 + HP 条 + XP 条 + 等级 + 角落击杀计数 ──
    // ★ 阶段 4-6：HUD 渲染前强制回到 dpr 基准变换。HUD 在世界层 ctx.restore() 之后画，
    //   正常情况变换已经是 dpr 基准；这一行是双保险——万一将来世界层某处 save/restore 失衡，
    //   HUD 也绝不会继承屏震偏移（HUD 抖动/位移 = 读错血条）或任何缩放。
    //   HUD 元素（血条 / 计时 / 击杀数 / 等级）一律固定字号、固定位置、无 scale 动画。
    ctx.setTransform(this._dpr, 0, 0, this._dpr, 0, 0);
    const remain = Math.ceil(c.remainSec);
    const mm = Math.floor(remain / 60), ss = remain % 60;
    ctx.fillStyle = COLOR.paper;
    if (this._f1 !== FONT_BIG) { this._f1 = FONT_BIG; ctx.font = FONT_BIG; }
    ctx.textAlign = 'center';
    ctx.textBaseline = 'top';
    ctx.fillText(`${mm}:${String(ss).padStart(2, '0')}`, w / 2, 14);

    // 波次读数与倒计时同处一个视觉行（右对齐）：帮玩家理解"越来越密"不是错觉。
    // 不要把它跟下方的 Lv/击杀 挤在同一行 —— 三个标签两行放，读起来会像排版事故。
    if (this._f2 !== FONT_SMALL) { this._f2 = FONT_SMALL; ctx.font = FONT_SMALL; }
    ctx.textAlign = 'right';
    ctx.fillStyle = c.inClimax() ? COLOR.blade : COLOR.ink;
    ctx.fillText(
      c.inClimax() ? '高潮' : `波次 ${ARENA.WAVES.findIndex((x) => x === c.wave()) + 1}/${ARENA.WAVES.length}`,
      w - 24, 24,
    );
    ctx.textAlign = 'left';

    const barW = w - 48, barX = 24, hpY = 50;
    ctx.fillStyle = 'rgba(232,227,218,0.15)';
    ctx.fillRect(barX, hpY, barW, 8);
    ctx.fillStyle = c.hp / c.maxHp < 0.3 ? COLOR.danger : COLOR.paper;
    ctx.fillRect(barX, hpY, barW * clamp(c.hp / c.maxHp, 0, 1), 8);

    const xpY = hpY + 16;
    ctx.fillStyle = 'rgba(168,154,230,0.18)';
    ctx.fillRect(barX, xpY, barW, 5);
    ctx.fillStyle = COLOR.gem;
    ctx.fillRect(barX, xpY, barW * clamp(c.xp / c.xpToLevel, 0, 1), 5);

    ctx.fillStyle = COLOR.ink;
    ctx.textAlign = 'left';
    // 阶段 6-4：魂火（局内商店货币）随 Lv/HP 同行显示 —— 让玩家随时看得见攒了多少。
    ctx.fillText(`Lv.${c.level}  HP ${Math.ceil(c.hp)}/${c.maxHp}  魂火 ${Math.floor(c.soulfire)}`, barX, xpY + 10);

    // 角落击杀计数（数字往上跳本身就是爽点，不需要额外奖励挂钩）
    ctx.textAlign = 'right';
    ctx.fillStyle = COLOR.paper;
    ctx.fillText(`击杀 ${c.kills}`, w - 24, xpY + 10);
    ctx.textAlign = 'left';

    // ── 阶段 4-4：Boss 血条（屏幕顶部、占屏宽 60% 的粗红条）──
    // ★ 位置压在 XP 条下方而不是叠在顶部倒计时上：倒计时是"还能撑多久"，
    //   Boss 血条是"还要打多久"，两者都是时间读数，放在一起会互相干扰。
    const boss = c.bossRef && !c.bossRef.dead ? c.bossRef : null;
    if (boss) {
      const b = BOSS_TYPES[boss.kind];
      const bw = w * 0.6, bx = (w - bw) / 2, by = xpY + 36;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'bottom';
      ctx.fillStyle = COLOR.paper;
      ctx.fillText(b.label, w / 2, by - 4);
      ctx.textBaseline = 'top';
      ctx.fillStyle = 'rgba(232,227,218,0.15)';
      ctx.fillRect(bx, by, bw, 10);
      ctx.fillStyle = '#b3402f';                       // 粗红条
      ctx.fillRect(bx, by, bw * clamp(boss.hp / boss.maxHp, 0, 1), 10);
      ctx.strokeStyle = 'rgba(232,227,218,0.45)';
      ctx.lineWidth = 1;
      ctx.strokeRect(bx, by, bw, 10);
      ctx.textAlign = 'left';
    }

    // ── 阶段 4-3：连杀 Combo（spec 一-3）──
    // 屏幕右侧**竖排**，N 越大字越大、颜色 白→黄→橙→红。
    // ★ 纯显示：combo 不参与任何伤害/经济判定（spec 明文「只显示，不影响数值」）。
    //   顺带用"剩余窗口"驱动一次轻微收缩 + 变淡 —— 那是"快断了"的读数，
    //   玩家因此会主动去续连，而不是等它自己消失。
    if (c.combo >= 2) {
      let tier = ARENA.COMBO_TIERS[0];
      for (const t of ARENA.COMBO_TIERS) if (c.combo >= t.n) tier = t;
      const urg = clamp(c.comboT / ARENA.COMBO_WINDOW, 0, 1);
      ctx.font = FONT_COMBO(Math.round(tier.size * (0.84 + 0.16 * urg)));
      ctx.fillStyle = tier.color;
      ctx.globalAlpha = 0.45 + 0.55 * urg;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      const lines = ['连', '击', `×${c.combo}`];
      let cy = h * 0.40;
      for (const s of lines) {
        ctx.fillText(s, w - 24, cy);
        cy += tier.size + 6;
      }
      ctx.globalAlpha = 1;
    }

    // ── 阶段 4-3：中央横幅（里程碑 / 后一阶段的 Boss 警告）──
    // 不暂停、不弹窗（spec 二-3 / 4-4）：只是屏幕中央一行字，前 70% 全亮、后 30% 淡出。
    if (this._banners.length) {
      ctx.font = FONT_BANNER;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      for (let i = 0; i < this._banners.length; i++) {
        const b = this._banners[i];
        const p = clamp(b.t / (b.life || ARENA.MILE_FADE), 0, 1);
        const a = p < 0.7 ? 1 : 1 - (p - 0.7) / 0.3;
        ctx.globalAlpha = clamp(a, 0, 1);
        ctx.fillStyle = b.evo ? COLOR.evo : b.event ? COLOR.event : COLOR.paper;
        ctx.fillText(b.text, w / 2, h * 0.30 + i * 30);
      }
      ctx.globalAlpha = 1;
    }
    this._f1 = ''; this._f2 = '';
    // ⚠ 上面两处直接改了 ctx.font，必须把字体缓存标记清掉 ——
    //   否则下一帧 HUD 那两行 `if (this._f1 !== FONT_BIG)` 会**跳过赋值**，
    //   于是倒计时/血条读数用的是上一次的连击字体（静默的文字错版）。

    // 技能槽：三槽各自显示 持有/就绪/CD（CD 时变灰并显示剩余秒数）。
    // 未拥有的槽显示"锁"。只在显示文本真的变化时写 DOM：CD 数字一秒只变 10 次，
    // 每帧写 textContent + classList 会持续触发样式重算，纯浪费。
    if (this.skillBar) {
      for (const k of Object.keys(this.skillSlots)) {
        const el = this.skillSlots[k];
        const owned = !!c.skills[k];
        const cd = owned ? c.skillCd(k) : 0;
        const ready = owned && cd <= 0;
        const sig = `${owned ? 1 : 0}|${ready ? 1 : 0}|${cd > 0 ? cd.toFixed(1) : ''}`;
        if (el._sig !== sig) {
          el._sig = sig;
          const label = el.querySelector('span');
          label.textContent = !owned ? '锁' : ready ? (SKILL_SHORT[k] || '—') : cd.toFixed(1);
          el.classList.toggle('locked', !owned);
          el.classList.toggle('cd', owned && cd > 0);
          el.classList.toggle('ready', ready);
          el.title = owned ? `${SKILL_LABEL[k]}（${SKILL_SLOT_KEYS[k]}）` : '尚未获得';
        }
      }
    }

    this._pdone('hud');
    // 阶段 3：持有物图标栏（武器/技能/被动，被动带 ×n）。仅签名变化时才重写 DOM。
    this._renderInventory(c);

    // 悬浮摇杆（拖动时绘制）
    if (this.joy.active) {
      ctx.strokeStyle = 'rgba(232,227,218,0.25)';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(this.joy.ox, this.joy.oy, 48, 0, TAU);
      ctx.stroke();
      ctx.fillStyle = 'rgba(232,227,218,0.5)';
      ctx.beginPath();
      ctx.arc(this.joy.ox + this.joy.x * 48, this.joy.oy + this.joy.y * 48, 20, 0, TAU);
      ctx.fill();
    }

    this._pdone('ui');
    if (DBG) this._renderDbg(ctx, w, h);
  }

  /** 阶段 3：持有物图标栏。把"当前带了什么"画成一行 chip，随升级实时刷新。
   *  武器/技能各占一格（持有即显示），被动按拿过的次数显示 ×n。
   *  ★ 只在持有签名变化时才重写 innerHTML：一局里每帧都重写会把这套小 DOM 反复创建、
   *    触发浏览器布局重算，纯浪费（同屏满屏时每帧都在跑）。 */
  _renderInventory(c) {
    const parts = [];
    for (const w of WEAPONS) if (c.weapons[w.id]) parts.push({ t: 'w', label: w.label });
    for (const s of SKILLS) if (c.skills[s.id]) parts.push({ t: 's', label: s.label });
    const tally = {};
    for (const id of c.upgradesTaken) tally[id] = (tally[id] || 0) + 1;
    for (const p of PASSIVES) if (tally[p.id]) parts.push({ t: 'p', label: p.label, n: tally[p.id] });
    const sig = parts.map((x) => `${x.t}:${x.label}:${x.n || 1}`).join('|');
    if (sig === this._invSig) return;
    this._invSig = sig;
    this.invEl.innerHTML = parts
      .map((p) => `<span class="inv-chip inv-${p.t}">${p.label}${p.n > 1 ? ` ×${p.n}` : ''}</span>`)
      .join('');
  }

  /** 玩家剪影（身体 + 头）。抽成方法是为了让**闪现残影**复用同一个形状 ——
   *  两处各画一遍的话，改一次形状就会漏一处，残影会变成另一个人的影子。 */
  _playerPath(ctx, pr) {
    ctx.beginPath();
    // 身体：上窄下宽的梯形（肩 → 脚）。比"尖三角 + 顶上一个圆"更像人 ——
    // 后者在 14px 半径下会糊成一个钥匙孔，满屏怪里根本读不出"这是我"。
    ctx.moveTo(-pr * 0.46, -pr * 1.80); // 左肩
    ctx.lineTo(pr * 0.46, -pr * 1.80);  // 右肩
    ctx.lineTo(pr * 0.80, 0);           // 右脚（原点 = 脚底）
    ctx.lineTo(-pr * 0.80, 0);          // 左脚
    ctx.closePath();
    ctx.fill();
    // 头：坐在肩上方的圆（底边正好贴住肩线，不留缝以免剪影断开）
    ctx.beginPath();
    ctx.arc(0, -pr * 2.32, pr * 0.52, 0, TAU);
    ctx.fill();
  }

  /** ?dbg=1：输入 / 帧率 / 实体数 / 手感读数（左下角）。真机操控异常时，让用户直接读数值反馈。 */
  _renderDbg(ctx, w, h) {
    const c = this.core;
    const lines = [
      `in  (${this.input.x.toFixed(2)}, ${this.input.y.toFixed(2)})`,
      `key [${[...this.keys].join(',')}]`,
      `joy (${this.joy.x.toFixed(2)}, ${this.joy.y.toFixed(2)}) ${this.joy.active ? 'ON' : '--'}`,
      `pos (${Math.round(c.player.x)}, ${Math.round(c.player.y)})  ${c.w}x${c.h}`,
      `en ${c.enemies.length} gem ${c.gems.length} lv ${c.level} fps ${this._fps}`,
      // 速度 / 死亡动画 / 蓄力态：「人物滑冰停不下来」「怪死了不消失」这类观感问题
      // 全靠这三个读数区分"是动画没走完"还是"状态没被清掉"。
      `spd ${Math.round(Math.sqrt(c.player.vx ** 2 + c.player.vy ** 2))} dying ${c.deaths.length} chg ${c.shockChargeT >= 0 ? 'Y' : '-'}`,
      `shots ${c.shots} dmg ${c.dmg} mag ${Math.round(c.magnet)}`,
    ];
    // 阶段 6-1：帧耗时剖析 Top6（每帧毫秒 / 占整帧 %）—— 定位渲染瓶颈的那一组读数
    if (this.prof) {
      for (const t of this._profTop().slice(0, 6)) {
        lines.push(`${t.ms.toFixed(2)}ms ${String(Math.round(t.pc)).padStart(2)}% ${t.k}`);
      }
    }
    const lh = 13, pad = 6, bw = 200;
    const bh = lines.length * lh + pad * 2;
    const bx = 8, by = h - bh - 8;
    ctx.fillStyle = 'rgba(0,0,0,0.66)';
    ctx.fillRect(bx, by, bw, bh);
    if (this._f2 !== FONT_SMALL) { this._f2 = FONT_SMALL; ctx.font = FONT_SMALL; }
    ctx.fillStyle = '#a89ae6';
    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';
    lines.forEach((s, i) => ctx.fillText(s, bx + pad, by + pad + i * lh));
  }

  /** 探针/外部用：立刻结束本局（存活判定按当前是否活满进行） */
  forceFinish() {
    if (this.ended || !this.core) return;
    this.core.done = true;
    this.core.survived = this.core.hp > 0;
    this._end();
  }

  /** 探针/外部用：释放冲击波（透传到 ArenaCore；阶段 1 的老接口，保留） */
  shock() {
    return this.core ? this.core.shockwave() : false;
  }

  /** 探针/外部用：放一个技能（走循环指针，与真人按键同一条路径） */
  cast() {
    return this.core ? this.core.castSkill() : false;
  }

  /** 探针/演示用：把模拟推进 sec 秒（不渲染）。用于录制时"跳到后期"而不必真等 8 分钟。
   *  走 1/60 的细步长而不是一次性大步长 —— 大步长会让惯性/接触判定失真，
   *  于是"跳过去"的那一局和"真打过去"的那一局不是同一个状态。 */
  fastForward(sec) {
    if (!this.core) return;
    const h = 1 / 60;
    for (let t = 0; t < sec && !this.core.done; t += h) {
      const drive = this.driver ? this.driver.tick(this.core) : null;
      if (this.core.pendingUpgrade) {
        this.core.chooseUpgrade(drive ? drive.pick : 0); // 快进时不阻塞在三选一
        continue;
      }
      // 阶段 6-4：快进同样不阻塞在商栈（自动「下次再来」，与 sim 口径一致）。
      if (this.core.shopOpen) { this.core.resolveShop([]); continue; }
      this.core.step(h, drive && drive.input ? drive.input : { x: 0, y: 0 });
      if (drive && drive.cast) this.core.castSkill();
    }
    // 快进会让人瞬移上千像素：让相机在下一次绘制时**直接咔到位**，
    // 否则画面会从起点一路平移过去（观感上像"卡了半秒"，录屏尤其难看）。
    this._camReady = false;
    this._needsPaint = true;
  }

  _end() {
    if (this.ended) return;
    this.ended = true;
    if (this.raf) cancelAnimationFrame(this.raf);
    this.raf = 0;
    const res = this.core ? this.core.result() : null;
    this._teardown();
    this.onDone?.(res);
  }

  _teardown() {
    this._resetInput(); // 退出时清干净输入态
    this.canvas.removeEventListener('pointerdown', this._onPointerDown);
    window.removeEventListener('pointermove', this._onPointerMove);
    window.removeEventListener('pointerup', this._onPointerUp);
    window.removeEventListener('pointercancel', this._onPointerUp);
    window.removeEventListener('keydown', this._onKeyDown);
    window.removeEventListener('keyup', this._onKeyUp);
    window.removeEventListener('resize', this._onResize);
    window.removeEventListener('blur', this._resetInput);
    document.removeEventListener('visibilitychange', this._resetInput);
    this.root?.remove();
  }
}

const SPRITE_RES = 96; // 离屏精灵分辨率（>绘制尺寸，靠降采样拿到平滑边缘）
const ARENA_KEYS = new Set([
  'ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'w', 'a', 's', 'd', 'W', 'A', 'S', 'D',
]);
